window.TOEFL_LR = [{"n":1,"adv":false,"v":"i7ceGWYcHmI","s":[[28,"This is the main library on campus.","這是校園的主圖書館。"],[41,"Students come here to study and borrow books.","學生來這裡讀書和借書。"],[54,"The first floor has group study rooms you can reserve.","一樓有可以預約的團體討論室。"],[68,"The second floor is a quiet zone for individual work.","二樓是個人自習的安靜區。"],[83,"To check out books, use your student ID at the front desk.","要借書,請在櫃台使用你的學生證。"],[99,"If you need research help, the librarians are available every afternoon.","如果需要研究上的協助,館員每天下午都在。"],[117,"Please remember to return all borrowed materials by the due date to avoid late fees.","請記得在到期日前歸還所有借閱資料,以免被收逾期費。"],[162,"Welcome to the campus recreation center.","歡迎來到校園休閒中心。"],[174,"Please scan your student ID at the entrance.","請在入口刷你的學生證。"],[187,"Locker rooms are located down the hallway on your left.","更衣室在走廊盡頭的左手邊。"],[201,"Towels can be borrowed from the equipment desk.","毛巾可以在器材櫃台借用。"],[215,"Group fitness classes begin on the hour in Studio B.","團體健身課程每小時整點在 B 教室開始。"],[232,"If you're using weights, wipe them down before returning them to the rack.","如果你使用了重量器材,請先擦乾淨再放回架上。"],[249,"For safety, report any damaged machines to a staff member immediately so they can be taken out of service.","為了安全,發現任何損壞的機器請立刻告知工作人員,以便停止使用。"],[298,"Welcome to the University Media Center.","歡迎來到大學媒體中心。"],[309,"Cameras and tripods can be checked out with your ID.","可以用你的證件借相機和三腳架。"],[322,"Editing suites are located on the second floor.","剪輯室位於二樓。"],[336,"Reservations are recommended during peak hours.","尖峰時段建議先預約。"],[351,"Food is not allowed near the equipment racks.","器材架附近禁止飲食。"],[364,"If you need help with software, ask a technician at the help desk.","如果軟體方面需要協助,請詢問服務台的技術人員。"],[380,"Return all equipment on time to avoid late fees and keep access available for everyone.","請準時歸還所有器材,以免被收逾期費,也讓每個人都能使用。"]]},
{"n":2,"adv":false,"v":"0Of5PGa8oeY","s":[[28,"Welcome to the public library.","歡迎來到公共圖書館。"],[38,"Please speak quietly inside at all times.","在館內請隨時輕聲說話。"],[51,"Computers are available for one-hour sessions.","電腦每次可使用一小時。"],[65,"Books are arranged by category along each aisle.","書籍依類別排列在各個走道上。"],[79,"If you need help finding something, ask at the front desk.","如果需要幫忙找東西,請到櫃台詢問。"],[93,"Study rooms can be reserved for up to two hours per day.","自習室每天最多可預約兩小時。"],[102,"Before you leave, return borrowed materials to the drop box near the entrance.","離開前,把借閱的資料投進入口附近的還書箱。"],[152,"Welcome to the community pool.","歡迎來到社區游泳池。"],[163,"All swimmers must shower before entering.","所有游泳者入池前都必須淋浴。"],[176,"Lifeguards rotate stations every 30 minutes.","救生員每 30 分鐘輪換一次崗位。"],[190,"Lane assignments are posted on the board.","水道分配公告在看板上。"],[204,"Children under 12 require an adult in the water with them.","12 歲以下的兒童必須有大人一起下水。"],[220,"For safety, diving is allowed only at the deep end.","為了安全,只有在深水區才可以跳水。"],[235,"Please exit the pool immediately if you hear the emergency whistle and wait for further instructions.","如果聽到緊急哨聲,請立刻離開泳池並等候進一步指示。"],[283,"Welcome to the Belleview Mall.","歡迎來到 Belleview 購物中心。"],[294,"Directory maps are located near each entrance.","每個入口附近都有樓層導覽圖。"],[308,"Restrooms are on the second floor next to the escalators.","洗手間在二樓手扶梯旁邊。"],[323,"Food court seating is available on both levels.","兩層樓都有美食街的座位。"],[337,"If you need customer service, visit the information booth.","如果需要客服,請到服務台。"],[354,"Some stores offer student discounts with a valid ID.","有些店家憑有效證件提供學生折扣。"],[364,"Before the mall closes, announcements will be made over the speakers.","購物中心打烊前,會透過廣播宣布。"]]},
{"n":3,"adv":false,"v":"BgtVUR-rj1w","s":[[28,"Welcome to city hall services.","歡迎來到市政府服務處。"],[39,"Please state the purpose of your visit.","請說明你來訪的目的。"],[50,"Application forms are available on the counter to your right.","申請表放在你右手邊的櫃台上。"],[64,"Completed forms must be submitted with valid identification.","填好的表格必須連同有效證件一起繳交。"],[79,"Processing times vary depending on the type of request.","處理時間依申請類型而有所不同。"],[94,"If additional documents are required, you will be notified by email.","如果需要額外文件,會以電子郵件通知你。"],[111,"Services may be delayed during high-volume periods or public administrative reviews.","在洽公人數多或行政審查期間,服務可能會延遲。"],[152,"Welcome to the post office.","歡迎來到郵局。"],[163,"Please take a number from the machine.","請從機器抽取號碼牌。"],[175,"Service counters will assist customers in numerical order.","服務櫃台會依號碼順序為顧客服務。"],[189,"Packages must be properly sealed before reaching the counter.","包裹在拿到櫃台前必須封好。"],[204,"International shipments require customs forms to be completed.","國際包裹必須填寫報關單。"],[220,"If you are unsure how to fill out the form, ask a clerk for assistance.","如果不確定怎麼填表,請向職員尋求協助。"],[237,"Transactions may take longer during peak hours, especially before holidays and weekends.","尖峰時段辦理業務可能會比較久,特別是假日和週末前。"],[282,"This is the airline check-in counter.","這裡是航空公司的報到櫃台。"],[293,"Please have your passport and ticket ready.","請準備好你的護照和機票。"],[305,"Checked luggage must be placed on the scale beside the counter.","託運行李必須放在櫃台旁邊的磅秤上。"],[318,"Bags exceeding the weight limit will require an additional fee.","超過重量限制的行李需要額外付費。"],[332,"Boarding passes are issued after your documents are verified.","證件核對無誤後才會發給登機證。"],[346,"If you are traveling with special items, notify the staff before tagging your luggage.","如果你攜帶特殊物品,請在行李掛牌前告知工作人員。"],[363,"Passengers are advised to proceed directly to security screening once the check-in process is complete.","完成報到手續後,建議旅客直接前往安全檢查。"]]},
{"n":4,"adv":false,"v":"8uhWKD7nNhw","s":[[16,"Welcome to the campus information desk.","歡迎來到校園服務台。"],[27,"Please wait in line until it's your turn.","請排隊等候,直到輪到你。"],[38,"Maps of the campus are available on the counter.","櫃台上有校園地圖可以拿取。"],[50,"If you need directions, an assistant can help you.","如果你需要問路,助理可以幫你。"],[64,"Offices and classrooms are listed on the digital board behind me.","辦公室和教室都列在我身後的電子看板上。"],[80,"If you've lost something, fill out a report so we can contact you if it's found.","如果你遺失了東西,請填寫報告單,找到時我們才能聯絡你。"],[91,"Before you leave, please check the bulletin board for updates about events and building hours.","離開前,請查看公布欄上的活動和大樓開放時間的最新消息。"]]},
{"n":5,"adv":false,"v":"bv4fLgxzcKQ","s":[[16,"Welcome to the campus recreation center.","歡迎來到校園休閒中心。"],[26,"Membership cards must be scanned at the entrance.","會員卡必須在入口刷卡。"],[38,"Towels and lockers are available for daily use.","每天都有毛巾和置物櫃可以使用。"],[51,"Group fitness classes are scheduled throughout the day.","團體健身課程排在一整天的不同時段。"],[64,"The swimming pool is open from 6:00 in the morning until 10 at night.","游泳池從早上 6 點開放到晚上 10 點。"],[72,"Equipment should be returned to its proper place after each session.","每次使用完後,器材應放回原位。"],[93,"Personal belongings must be stored in lockers to keep the facility safe and organized.","個人物品必須存放在置物櫃裡,以維持場館的安全和整齊。"]]},
{"n":6,"adv":false,"v":"Jtqpf0sElmQ","s":[[16,"This is the main lobby of the science building.","這是科學館的主大廳。"],[28,"Classrooms are located down the hall.","教室在走廊的另一頭。"],[39,"Lab coats and safety goggles are required for all lab sessions.","所有實驗課都必須穿實驗衣、戴護目鏡。"],[53,"Research posters from students are displayed near the stairway.","學生的研究海報展示在樓梯附近。"],[67,"Chemical storage areas are restricted to authorized personnel only.","化學品儲藏區僅限授權人員進入。"],[82,"If you need help finding a lab, consult the directory on the wall.","如果需要幫忙找實驗室,請查看牆上的樓層指南。"],[97,"Before entering any laboratory, make sure to follow the posted safety procedures.","進入任何實驗室之前,務必遵守公告的安全程序。"]]},
{"n":7,"adv":false,"v":"uzByMDLG-nM","s":[[16,"This is the campus health center.","這是校園健康中心。"],[26,"Students come here for medical care.","學生來這裡看病。"],[37,"You must check in at the front desk upon arrival.","抵達時必須先到櫃台報到。"],[49,"Bring your student ID and insurance information with you.","請攜帶你的學生證和保險資料。"],[61,"The nurses can help you with minor illnesses and injuries.","護理師可以協助處理輕微的疾病和受傷。"],[73,"For specialized treatment, they may refer you to an outside clinic.","需要專科治療時,他們可能會把你轉介到校外的診所。"],[88,"If you need counseling services, appointments can be scheduled through the same system.","如果你需要諮商服務,也可以透過同一個系統預約。"]]},
{"n":8,"adv":false,"v":"CFc8VWq2JAc","s":[[16,"You are entering the parking garage.","你正在進入停車場。"],[25,"Please take a parking ticket.","請取停車票。"],[36,"Available spaces are marked with green lights.","空車位以綠燈標示。"],[48,"Vehicles must be parked within the designated lines.","車輛必須停在指定的線內。"],[61,"Payment machines are located near the elevators on each level.","每一層的電梯附近都有繳費機。"],[75,"If you lose your ticket, contact the service office before exiting.","如果遺失停車票,出場前請聯絡服務處。"],[91,"The management is not responsible for damage or theft occurring inside the parking facility.","管理單位對停車場內發生的損壞或竊盜不負責任。"]]},
{"n":9,"adv":false,"v":"ih2lVsPlmY8","s":[[17,"Welcome to the central bus terminal.","歡迎來到中央公車總站。"],[28,"Schedules are posted on the digital boards.","時刻表公布在電子看板上。"],[38,"Tickets can be purchased at the counters or online.","車票可以在櫃台或網路上購買。"],[52,"Platforms are numbered clearly along the main hallway.","月台沿著主要通道清楚編號。"],[65,"Luggage storage is available near the east entrance.","東側入口附近有行李寄放處。"],[80,"Announcements for departures will be made over the public address system.","發車資訊會透過廣播系統宣布。"],[96,"Lost items should be reported immediately to the information desk for assistance.","遺失物品應立即向服務台報告以尋求協助。"]]},
{"n":10,"adv":false,"v":"Prn07WOtDkk","s":[[17,"Welcome to the science museum.","歡迎來到科學博物館。"],[27,"This museum features interactive exhibits.","這間博物館以互動式展覽為特色。"],[39,"The first floor focuses on biology and life sciences.","一樓以生物學和生命科學為主。"],[52,"The physics section includes hands-on demonstrations.","物理區有可以動手操作的示範。"],[66,"Guided tours start every hour near the entrance.","導覽每小時在入口附近出發。"],[79,"Please avoid touching the displays unless they are marked as interactive.","除非標示為互動式展品,否則請避免觸摸展示品。"],[94,"Before you leave, check out the gift shop for educational materials and souvenirs.","離開前,去禮品店看看教育用品和紀念品。"]]},
{"n":11,"adv":false,"v":"kB0tDlJqLlE","s":[[16,"You are now on the subway platform.","你現在在地鐵月台上。"],[27,"Please stand behind the safety line.","請站在安全線後方。"],[37,"Trains arrive on this platform every 10 minutes.","這個月台每 10 分鐘有一班車進站。"],[49,"Do not attempt to board until passengers have exited.","等乘客下車後再上車。"],[62,"Priority seating is reserved for elderly and disabled riders.","博愛座保留給年長者和身障乘客。"],[77,"If the platform is crowded, wait for the next train.","如果月台很擁擠,請等下一班車。"],[91,"For your safety, remain alert at all times and follow instructions announced over the loudspeaker.","為了你的安全,請隨時保持警覺,並遵守擴音器廣播的指示。"]]},
{"n":12,"adv":false,"v":"SwRxoOdpOSM","s":[[16,"The library stays open until midnight on weekdays.","圖書館平日開放到午夜。"],[28,"You can pick up your new student ID card tomorrow morning.","你明天早上可以領取新的學生證。"],[41,"Please remember to bring your registration forms to the main office.","請記得把你的註冊表格帶到主辦公室。"],[55,"If you lose your dorm key, you will need to pay a small replacement fee.","如果遺失宿舍鑰匙,你需要支付一小筆補發費用。"],[69,"The campus shuttle runs every 15 minutes starting from the north parking lot.","校園接駁車從北側停車場出發,每 15 分鐘一班。"],[84,"Students who are interested in the internship must submit their applications by Friday afternoon.","對實習有興趣的學生必須在週五下午前繳交申請。"],[101,"Although the cafeteria is under renovation, temporary meal services are available in the student lounge.","雖然學生餐廳正在整修,學生交誼廳有提供臨時供餐服務。"]]},
{"n":13,"adv":false,"v":"dLfaL7Lv5QQ","s":[[17,"The quiet study area is located on the third floor of the building.","安靜自習區在大樓的三樓。"],[30,"Students can borrow up to 10 books at a time with a valid ID.","學生憑有效證件一次最多可以借 10 本書。"],[42,"You must return all reserve materials by the end of the semester.","所有指定參考資料都必須在學期結束前歸還。"],[56,"The online database provides access to thousands of academic journals and news articles.","線上資料庫提供數千種學術期刊和新聞文章。"],[74,"Librarians are available to help you find primary sources for your history research project.","館員可以幫你為歷史研究報告找到第一手資料。"],[92,"If you cannot find the book on the shelf, you can request it through the interlibrary loan system.","如果在書架上找不到那本書,你可以透過館際合作借書系統申請。"],[111,"Despite the increase in digital resources, the university continues to invest in physical archives for specialized research purposes.","儘管數位資源越來越多,學校仍持續投資實體檔案館,以供專門研究使用。"]]},
{"n":14,"adv":false,"v":"vZHrFFmcSzw","s":[[17,"Welcome to the university dormitory.","歡迎來到大學宿舍。"],[28,"New students should check in at the reception desk on the first floor.","新生應到一樓的接待櫃台報到。"],[41,"After you receive your key, use the elevator or stairs to go directly to your assigned room.","拿到鑰匙後,搭電梯或走樓梯直接前往你被分配的房間。"],[57,"For safety reasons, keep your door locked when sleeping or away from your room.","為了安全,睡覺或離開房間時請把門鎖好。"],[73,"Quiet hours begin at 10:00 in the evening, so please lower your music and voices at that time.","晚上 10 點開始是安靜時間,屆時請降低音樂和說話的音量。"],[90,"For large luggage, you can borrow a cart from the reception and return it as soon as you're finished.","如果有大型行李,可以向櫃台借推車,用完請盡快歸還。"],[109,"In case of a fire alarm, leave the building immediately using the stairs and wait for instructions outside.","如果火災警報響起,請立刻走樓梯離開大樓,並在外面等候指示。"]]},
{"n":15,"adv":false,"v":"VZLGTPsuwbw","s":[[17,"Welcome to the international arrivals hall.","歡迎來到國際入境大廳。"],[28,"Please have your passport and boarding pass ready at the immigration counter.","請在入境審查櫃台準備好護照和登機證。"],[43,"Follow the green signs to collect your luggage from the baggage claim area.","依照綠色指標到行李提領區領取行李。"],[58,"If your bag does not appear after 20 minutes, report it to the lost luggage desk.","如果 20 分鐘後你的行李還沒出現,請到行李遺失櫃台報告。"],[75,"Customs officers may ask you to open your suitcase for a quick inspection.","海關人員可能會要求你打開行李箱做簡單檢查。"],[92,"Free airport shuttles to the city center depart every 15 minutes from bay number three.","前往市中心的免費機場接駁車每 15 分鐘從 3 號月台發車。"],[112,"Currency exchange machines are located near the exit, but check the rates before using one.","出口附近有外幣兌換機,但使用前請先確認匯率。"]]},
{"n":16,"adv":false,"v":"cTReS00gBRA","s":[[16,"This is an emergency announcement.","這是一則緊急廣播。"],[27,"Please remain calm and attentive.","請保持冷靜並注意聽。"],[39,"Exit signs are located above each doorway.","每個門口上方都有出口標誌。"],[52,"Do not use elevators during an evacuation.","疏散時請勿搭乘電梯。"],[57,"Assist those who may need help if it is safe to do so.","在安全的情況下,協助可能需要幫忙的人。"],[80,"Follow staff instructions and proceed to the nearest exit.","遵守工作人員的指示,前往最近的出口。"],[95,"Once outside, move to the designated assembly area and remain there until authorities declare the building safe.","到外面後,前往指定的集合區,並待在那裡直到有關單位宣布大樓安全。"]]},
{"n":17,"adv":false,"v":"l5CyqxVH7_s","s":[[17,"Welcome to the city museum.","歡迎來到市立博物館。"],[27,"Please keep your ticket visible.","請讓你的票保持在看得見的地方。"],[39,"Large bags must be checked at the security desk.","大型包包必須寄放在安檢櫃台。"],[53,"Flash photography is not allowed inside the exhibit halls.","展覽廳內禁止使用閃光燈拍照。"],[67,"Audio guides are available in multiple languages at the counter.","櫃台提供多種語言的語音導覽。"],[83,"If you join a guided tour, remain with the group throughout the visit.","如果參加導覽,參觀全程請跟著團體。"],[99,"Visitors who violate museum rules may be asked to leave without a ticket refund.","違反博物館規定的參觀者可能會被請離開,且不退票。"]]},
{"n":18,"adv":false,"v":"O4EYGjN6gIo","s":[[17,"Welcome to the public community library.","歡迎來到公共社區圖書館。"],[30,"Show your library card or ID to borrow books at the circulation desk.","在借還書櫃台出示借書證或證件即可借書。"],[45,"Return items to the drop box if the desk is closed.","如果櫃台已關閉,請把物品投入還書箱。"],[60,"Computers for public use are on the second floor with a one-hour limit.","公用電腦在二樓,每次限用一小時。"],[75,"Printing costs 10 cents per page in black and white or 50 cents in color.","列印黑白每頁 10 美分,彩色每頁 50 美分。"],[92,"Children's reading programs start every Saturday morning in the community room.","兒童閱讀活動每週六上午在社區活動室開始。"],[108,"For help finding a book or using the online catalog, ask any staff member in a green vest.","如需協助找書或使用線上目錄,請詢問任何一位穿綠色背心的工作人員。"]]},
{"n":19,"adv":false,"v":"FHGD62oFbqg","s":[[17,"All students must log out of their accounts before leaving the lab.","所有學生離開電腦教室前都必須登出帳號。"],[30,"The computer lab will be closed for maintenance this coming Friday.","電腦教室這個星期五將因維修而關閉。"],[44,"You can print up to 50 pages for free using your student credit.","你可以用學生額度免費列印最多 50 頁。"],[58,"To reset your password, please follow the instructions sent to your university email.","若要重設密碼,請依照寄到你學校電子信箱的說明操作。"],[73,"If the software crashes while you are working, be sure to report the error to the technician.","如果軟體在你使用時當機,務必向技術人員回報錯誤。"],[91,"Wireless internet access is available throughout the campus, but you must register your device first.","整個校園都有無線網路,但你必須先註冊你的裝置。"],[110,"While the IT department provides technical support for university hardware, they cannot repair personal laptops or mobile devices.","雖然資訊部門為學校的硬體提供技術支援,但他們無法修理個人的筆電或行動裝置。"]]},
{"n":20,"adv":false,"v":"4ycYS2Nwmcs","s":[[17,"This is a city public bus.","這是一輛市區公車。"],[28,"Pay your fare using cash or a contactless card at the front machine.","在前方的機器用現金或感應卡付車資。"],[42,"Hold on to the handrails while the bus is moving.","公車行駛時請握好扶手。"],[55,"Please offer your seat to elderly passengers or those with young children.","請讓座給年長乘客或帶著幼童的乘客。"],[70,"Do not eat strong-smelling food or play music without headphones.","不要吃味道重的食物,也不要不戴耳機播放音樂。"],[88,"Press the stop button when you see your stop approaching on the display.","看到螢幕顯示你的站快到了,就按下車鈴。"],[104,"Exit through the rear doors and watch your step when the bus is at a curb or platform.","從後門下車,公車停靠路邊或月台時請注意腳步。"]]},
{"n":21,"adv":false,"v":"bGFTjoOa2N8","s":[[17,"Welcome to the city zoo.","歡迎來到市立動物園。"],[26,"Please keep your ticket with you.","請隨身攜帶你的門票。"],[37,"The map shows the main paths and exhibit areas.","地圖上標示了主要的路線和展區。"],[50,"Feeding times for the animals are posted near each enclosure.","動物的餵食時間公告在每個展區附近。"],[65,"If you're visiting with children, stay within the marked walkways.","如果帶孩子來參觀,請待在標示的步道內。"],[81,"Some areas are closed for cleaning, so follow the signs for detours.","有些區域正在清潔而關閉,請依照指標繞道。"],[98,"Photography is allowed, but flash should be turned off to avoid disturbing the animals.","可以拍照,但應關閉閃光燈,以免驚擾動物。"]]},
{"n":22,"adv":false,"v":"jOU8F1ygi1w","s":[[16,"Welcome to the public library.","歡迎來到公共圖書館。"],[26,"Please keep your voice low at all times.","請隨時保持低聲。"],[39,"Personal belongings should be stored in the lockers near the entrance.","個人物品應存放在入口附近的置物櫃裡。"],[54,"Food and uncovered drinks are not permitted inside the reading areas.","閱覽區內禁止食物和未加蓋的飲料。"],[69,"Computers may be used for up to one hour per person.","每人使用電腦最多一個小時。"],[84,"If you need additional time, request an extension at the information desk.","如果需要更多時間,請到服務台申請延長。"],[101,"Failure to follow library policies may result in temporary suspension of borrowing and computer privileges.","不遵守圖書館規定可能會被暫停借書和使用電腦的權利。"]]},
{"n":23,"adv":false,"v":"tc5Zcr6mlg0","s":[[17,"Please have your passport and boarding pass ready.","請準備好你的護照和登機證。"],[29,"Laptops must be removed from your bag at the security gate.","在安檢門必須把筆電從包包裡拿出來。"],[43,"The flight to London is delayed by approximately 45 minutes.","飛往倫敦的班機延誤約 45 分鐘。"],[59,"Passengers are allowed to carry one small personal item onto the plane.","乘客可以攜帶一件小型個人物品上飛機。"],[74,"If your luggage is overweight, you may have to pay an additional service fee.","如果你的行李超重,可能需要支付額外的服務費。"],[91,"Please listen carefully for the announcement regarding the change of your departure gate.","請仔細聆聽有關登機門變更的廣播。"],[108,"While the duty-free shop is open, most restaurants in this terminal are closed for the night.","雖然免稅店還開著,但這個航廈大部分的餐廳晚上都已經關門了。"]]},
{"n":24,"adv":false,"v":"XsvaHAlJu70","s":[[17,"Please have your exact change ready.","請準備好剛好的零錢。"],[28,"This bus goes directly to the central station.","這班公車直達中央車站。"],[40,"You must press the red button to request a stop.","要下車必須按紅色按鈕。"],[54,"Passengers should enter through the front door and exit through the rear.","乘客應從前門上車、後門下車。"],[69,"If the bus is full, please move toward the back to make more room.","如果公車客滿,請往後面移動以騰出更多空間。"],[85,"You can download the mobile app to track the real-time location of your bus.","你可以下載手機應用程式來追蹤公車的即時位置。"],[102,"Due to heavy traffic downtown, expect significant delays on all routes heading toward the suburbs.","由於市中心交通繁忙,所有開往郊區的路線預計都會大幅延誤。"]]},
{"n":25,"adv":false,"v":"oAvLxxRCb4w","s":[[17,"Mind the gap between the train and the platform.","注意列車與月台之間的空隙。"],[29,"The express train to the airport departs from Track 4.","前往機場的快車從第 4 月台出發。"],[42,"Keep your ticket with you until you have exited the station.","離開車站前請保留好你的車票。"],[57,"Please keep your personal belongings with you at all times during the journey.","旅途中請隨時攜帶好你的個人物品。"],[73,"If you miss your scheduled departure, your ticket may be used for the next train.","如果你錯過預定的班次,車票可以用來搭下一班車。"],[90,"Passengers are reminded that smoking and loud music are strictly prohibited on all train carriages.","提醒乘客,所有車廂內嚴格禁止吸菸和大聲播放音樂。"],[110,"Because of scheduled track maintenance, trains will operate on a modified schedule throughout the weekend.","由於預定的軌道維修,整個週末列車將依調整後的時刻表行駛。"]]},
{"n":26,"adv":false,"v":"1Dk7hh5BawY","s":[[17,"Please stand behind the yellow line.","請站在黃線後方。"],[28,"Do not block the doors while the train is moving.","列車行駛時請勿擋住車門。"],[40,"Eating and drinking are strictly prohibited inside the subway cars.","地鐵車廂內嚴格禁止飲食。"],[54,"Make sure to let passengers exit the train before you attempt to step on.","上車前務必先讓乘客下車。"],[70,"Priority seating must be reserved for elderly and disabled passengers.","博愛座必須保留給年長和身障的乘客。"],[87,"If you notice any suspicious items left on the seat, please notify a staff member immediately.","如果發現座位上留有任何可疑物品,請立刻通知工作人員。"],[106,"While using headphones is allowed, please keep the volume at a level that does not disturb others.","雖然可以使用耳機,但請把音量保持在不會打擾別人的程度。"]]},
{"n":27,"adv":false,"v":"3fkHsf6qazs","s":[[17,"This is the main dining hall.","這是主要的學生餐廳。"],[29,"Students can choose from several food stations.","學生可以從幾個餐點區中選擇。"],[43,"Your meal plan is linked to your student ID card.","你的餐費方案和學生證連結在一起。"],[58,"Vegetarian and gluten-free options are available every day.","每天都有素食和無麩質的選擇。"],[74,"Please place your used dishes on the return cart near the exit.","請把用過的餐具放在出口附近的回收推車上。"],[90,"The dining hall gets busy around noon, so plan ahead if you can.","中午前後餐廳會很擁擠,所以可以的話請事先規劃。"],[109,"If you have dietary restrictions, you may consult the nutrition coordinator for assistance.","如果你有飲食限制,可以向營養協調員諮詢協助。"]]},
{"n":28,"adv":false,"v":"7bTBBoxxF98","s":[[17,"Please check in at the front desk.","請在櫃台報到。"],[29,"Visiting hours end at 8:00 every evening.","探病時間每天晚上 8 點結束。"],[42,"You must wear a mask while inside the waiting room.","在候診室內必須戴口罩。"],[56,"Please turn off your mobile phones before entering the examination area.","進入診療區前請關掉手機。"],[71,"Patients are requested to arrive at least 15 minutes before their scheduled appointment.","病人請在預約時間前至少 15 分鐘到達。"],[89,"If you have any questions about your medication, please consult with the pharmacist on the first floor.","如果對用藥有任何疑問,請向一樓的藥師諮詢。"],[108,"Although the main entrance is closed at night, the emergency room remains open 24 hours a day.","雖然正門晚上關閉,急診室仍 24 小時開放。"]]},
{"n":29,"adv":false,"v":"F1ooUhBsaYk","s":[[16,"The food court is on the top floor.","美食街在頂樓。"],[28,"Please keep your receipt to receive a full refund.","請保留收據才能全額退款。"],[42,"Escalators are located near the center of the shopping mall.","手扶梯在購物中心的中央附近。"],[57,"You can find the restrooms down the hallway past the shoe store.","洗手間在走廊盡頭,經過鞋店就到了。"],[72,"Gift cards can be purchased at the customer service desk and used in any shop.","禮物卡可以在客服中心購買,並在任何店家使用。"],[89,"If you lose your keys or wallet, please visit the security office near the main entrance.","如果遺失鑰匙或錢包,請到正門附近的保全室。"],[108,"Because of the holiday sale, expect the parking garage to be full during the weekend afternoon.","由於假日特賣,預計週末下午停車場會客滿。"]]},
{"n":30,"adv":false,"v":"qLHgdCKBGyA","s":[[16,"Log in using your student username.","用你的學生帳號登入。"],[29,"Select the document you wish to print.","選擇你要列印的文件。"],[41,"The color printer is currently out of ink.","彩色印表機目前沒有墨水了。"],[54,"You can add more money to your account online.","你可以在網路上為你的帳戶加值。"],[68,"If the paper gets jammed, please ask the lab assistant for help.","如果卡紙,請找電腦教室助理幫忙。"],[75,"Remember to collect your pages from the tray before you leave the lab.","離開電腦教室前,記得從出紙匣拿走你的文件。"],[101,"Although wireless printing is available, you must be connected to the university network to use it.","雖然可以無線列印,但你必須連上學校的網路才能使用。"]]},
{"n":31,"adv":false,"v":"TmTXXTea4g0","s":[[17,"Please take a number and wait.","請抽號碼牌等候。"],[29,"All visitors must sign the guest log.","所有訪客都必須在訪客登記簿上簽名。"],[41,"The office closes for lunch at 12:00.","辦公室 12 點午休關閉。"],[58,"You can pay your parking tickets at the second window.","你可以在第二個窗口繳交停車罰單。"],[74,"If you need a copy of your records, please fill out this form.","如果你需要紀錄的副本,請填寫這份表格。"],[91,"Make sure to bring your original documents when you come back for your final interview.","回來參加最後一次面談時,務必帶著你的正本文件。"],[110,"Because the building is under construction, the main entrance will be closed for the entire month.","因為大樓正在施工,正門整個月都會關閉。"]]},
{"n":32,"adv":false,"v":"yyrERQRvLxw","s":[[16,"Welcome to academic advising.","歡迎來到學業輔導處。"],[28,"Please check in at the front desk.","請在櫃台報到。"],[40,"Appointments are scheduled through the online portal.","預約透過線上系統安排。"],[53,"Advisers are available Monday through Friday during office hours.","輔導老師在週一到週五的辦公時間都可以諮詢。"],[62,"Remember to bring a physical copy of your transcript to the meeting.","記得帶一份紙本成績單來面談。"],[84,"If you need help choosing courses, discuss your academic goals with your adviser.","如果選課需要幫忙,請和你的輔導老師討論你的學業目標。"],[102,"Students planning to graduate should schedule an advising session at least one semester in advance.","打算畢業的學生應至少提前一學期預約輔導。"]]},
{"n":33,"adv":false,"v":"StWCkWgLdhs","s":[[17,"Please take a number and wait.","請抽號碼牌等候。"],[29,"Your signature is required on the bottom line.","需要你在最下面那一行簽名。"],[44,"You must pass a vision test to renew your license.","你必須通過視力檢查才能換發駕照。"],[59,"Please have your proof of insurance ready for the clerk to review.","請準備好你的保險證明讓職員審核。"],[74,"If you fail the written exam, you can retake it after 24 hours have passed.","如果筆試沒通過,24 小時後可以重考。"],[92,"Make sure to bring a valid form of identification when you come for your road test.","來參加路考時,務必攜帶有效的身分證件。"],[110,"Due to a shortage of staff today, the waiting time for all services will be much longer.","由於今天人手不足,所有服務的等候時間都會長很多。"]]},
{"n":34,"adv":false,"v":"x9XzHqvZrMo","s":[[17,"Welcome to the National Art Gallery.","歡迎來到國家美術館。"],[30,"This gallery features contemporary artwork.","這間美術館以當代藝術作品為特色。"],[42,"The exhibition changes every few months during the year.","展覽每年每隔幾個月就會更換。"],[56,"Please keep a safe distance from all the artworks on display.","請與所有展出的藝術品保持安全距離。"],[71,"While photography is allowed, the use of flash is strictly prohibited in the building.","雖然可以拍照,但館內嚴格禁止使用閃光燈。"],[89,"If you would like a guided tour, please ask for assistance at the main reception desk.","如果想參加導覽,請到主接待櫃台詢問。"],[107,"During special events, guest artists are invited to the gallery to lead lectures and weekend workshops.","特別活動期間,美術館會邀請客座藝術家主持講座和週末工作坊。"]]},
{"n":35,"adv":false,"v":"TpoBfUqDqQw","s":[[17,"Welcome to the city post office.","歡迎來到市區郵局。"],[29,"Please take a number from the machine.","請從機器抽取號碼牌。"],[41,"Boxes and mailing envelopes are available on the shelves.","架子上有紙箱和郵寄信封。"],[55,"If you need to send something quickly, ask about express shipping.","如果需要快速寄送,請詢問快遞服務。"],[71,"International packages always require a short customs form before they can be sent.","國際包裹在寄出前一定要填一張簡短的報關單。"],[89,"Stamps can be purchased at the main counter or the digital kiosk near the door.","郵票可以在主櫃台或門口附近的自助機購買。"],[100,"Before you leave the building, please double-check that the recipient's address and zip code are correct.","離開郵局前,請再次確認收件人的地址和郵遞區號正確。"]]},
{"n":36,"adv":false,"v":"4oSHAEUKDYM","s":[[16,"Welcome to Central City Park.","歡迎來到中央市立公園。"],[28,"Dogs must stay on a leash.","狗必須繫上牽繩。"],[39,"If you want a boat, visit the lake office.","如果想租船,請到湖邊的辦公室。"],[52,"Picnic tables are available on a first-come, first-served basis.","野餐桌採先到先使用的方式。"],[68,"Please throw all your trash into the bins provided near the exit.","請把所有垃圾丟進出口附近的垃圾桶。"],[84,"The public playground will be closed for a deep cleaning starting tomorrow at noon.","公共遊樂場從明天中午開始將關閉進行深度清潔。"],[102,"Even though the weather is warm, the park fountains are currently turned off for necessary repairs.","雖然天氣溫暖,公園的噴泉目前因必要的維修而關閉。"]]},
{"n":37,"adv":false,"v":"T-AMY2qkxGw","s":[[16,"Welcome to the student residence hall.","歡迎來到學生宿舍。"],[28,"Each room houses two students.","每個房間住兩名學生。"],[40,"Laundry machines are located in the basement.","洗衣機在地下室。"],[53,"Quiet hours begin at 10:00 every night.","每晚 10 點開始是安靜時間。"],[67,"If you have maintenance issues, please submit a request online.","如果有需要維修的問題,請在網路上提出申請。"],[82,"Safety checks occur once a month to ensure that everyone is following the dorm rules.","每個月會進行一次安全檢查,確保每個人都遵守宿舍規定。"],[100,"Please remember to keep your key card with you, as all doors will lock behind you.","請記得隨身攜帶門禁卡,因為所有的門在你身後都會自動上鎖。"]]},
{"n":38,"adv":false,"v":"we8AebVRaf8","s":[[16,"Welcome to the city parking office.","歡迎來到市立停車管理處。"],[28,"Please display your permit on the windshield.","請把停車證放在擋風玻璃上。"],[40,"Bicycles should be locked to the metal racks.","腳踏車應鎖在金屬車架上。"],[53,"You can track the local shuttle using a mobile app.","你可以用手機應用程式追蹤當地接駁車。"],[68,"If the main garage is full, you can park in the lot across the street.","如果主停車場客滿,你可以停在對街的停車場。"],[84,"Visitors who park in the restricted spaces will receive a fine from the city.","停在限制車位的訪客會收到市政府的罰單。"],[102,"While weekend parking is free for everyone, a valid permit is required during business hours.","雖然週末停車對所有人免費,但上班時間需要有效的停車證。"]]},
{"n":39,"adv":false,"v":"9HSTT5XWphE","s":[[17,"Enjoy your shopping today.","祝你今天購物愉快。"],[23,"Our store is open daily until 10:00.","本店每天營業到 10 點。"],[40,"Paper bags are available at the checkout counter.","結帳櫃台有提供紙袋。"],[54,"If you cannot find an item, please ask for assistance.","如果找不到商品,請尋求協助。"],[70,"Customers with fewer than 10 items should use the express lane.","購買少於 10 件商品的顧客請使用快速結帳通道。"],[86,"You can get a full refund if you bring back the original receipt and the item.","如果你帶著原始收據和商品回來,就可以全額退款。"],[104,"While the bakery is usually busy, there are no lines during the early morning hours.","雖然麵包區通常很忙,但清晨時段都不用排隊。"]]},
{"n":40,"adv":false,"v":"Ky6Ksjrp3A0","s":[[17,"Enjoy the show today.","祝你今天看表演愉快。"],[28,"Tickets go on sale two weeks in advance.","門票提前兩週開賣。"],[41,"Please arrive early to find your reserved seats.","請提早到場找你預訂的座位。"],[55,"Performances will begin promptly at the scheduled time.","表演會準時在預定時間開始。"],[70,"Late seating is only allowed during a break in the show.","遲到者只能在表演中場休息時入座。"],[85,"Programs and concessions are available for purchase in the main lobby area.","節目單和點心飲料可在主大廳購買。"],[104,"If you have any questions about the performance, please ask a staff member for assistance.","如果對表演有任何疑問,請向工作人員尋求協助。"]]},
{"n":41,"adv":false,"v":"a_GNGX4CfCQ","s":[[16,"The clinic opens at 8:00 a.m.","診所早上 8 點開門。"],[28,"Appointments are usually preferred here.","這裡通常希望病人先預約。"],[40,"Please bring your insurance card to the front desk.","請帶健保卡到櫃台。"],[54,"We ask that you wait in the lobby quietly.","請你在大廳安靜等候。"],[69,"Face masks are required for everyone during the flu season.","流感季節期間,每個人都必須戴口罩。"],[85,"Your prescriptions can be filled at the local pharmacy located right next door.","你可以在隔壁的藥局領取處方藥。"],[103,"Please arrive 15 minutes early for new patient registration to complete all necessary paperwork.","初診病人請提早 15 分鐘到達,完成所有必要的文件手續。"]]},
{"n":42,"adv":false,"v":"hJahWcColnw","s":[[16,"Sort your waste carefully here.","請在這裡仔細做好垃圾分類。"],[28,"Paper goes in the blue bin.","紙類丟進藍色回收桶。"],[40,"Plastic bottles should be crushed first.","塑膠瓶應先壓扁。"],[54,"Electronics are accepted on Tuesdays only.","電子產品只在星期二收取。"],[69,"Please do not bring hazardous materials like paint or batteries.","請不要帶油漆或電池等有害物質來。"],[87,"Staff will help you if you are unsure about any items.","如果你不確定任何物品怎麼丟,工作人員會協助你。"],[104,"Please remember to check the labels before you put items into the bins.","把物品丟進回收桶前,請記得先看標示。"]]},
{"n":43,"adv":false,"v":"tzIeJzSpHqQ","s":[[17,"Welcome to the parking garage.","歡迎來到停車場。"],[28,"Daily permits are available at the kiosk.","單日停車證可在自助機購買。"],[40,"Reserved spaces are marked for monthly members only.","保留車位僅供月租會員使用。"],[54,"Electric vehicle charging stations are on the ground level.","電動車充電站在一樓。"],[69,"Payment is accepted by credit card or mobile app.","可以用信用卡或手機應用程式付款。"],[84,"Vehicles must be removed by midnight to avoid overnight fees.","車輛必須在午夜前開走,以免被收過夜費。"],[101,"Please make sure to lock your vehicle and keep your valuables with you.","請務必鎖好車,並把貴重物品帶在身上。"]]},
{"n":44,"adv":false,"v":"wwAISUp_zKc","s":[[16,"Welcome to the weekly farmers market.","歡迎來到每週一次的農夫市集。"],[28,"Vendors accept cash and digital payments.","攤商接受現金和電子支付。"],[40,"Local farmers bring fresh produce every week.","在地農夫每週都會帶來新鮮農產品。"],[55,"Free sampling is encouraged at many stalls.","許多攤位都歡迎免費試吃。"],[69,"Reusable bags are highly recommended for shopping.","非常建議購物時使用環保袋。"],[84,"Live music performs near the central seating area every weekend.","每個週末在中央座位區附近都有現場音樂表演。"],[102,"The market operates rain or shine from 9:00 a.m. until 2:00 p.m. every Saturday.","市集每週六早上 9 點到下午 2 點營業,風雨無阻。"]]},
{"n":45,"adv":false,"v":"O89hWxck098","s":[[16,"Welcome to the University Testing Center.","歡迎來到大學考試中心。"],[29,"Present your student ID at the check-in desk.","在報到櫃台出示你的學生證。"],[42,"Personal belongings must be stored in assigned lockers.","個人物品必須存放在指定的置物櫃裡。"],[56,"Electronic devices are strictly prohibited inside the exam room.","考場內嚴格禁止攜帶電子裝置。"],[71,"Scratch paper and pencils are provided by the supervisor.","監考人員會提供計算紙和鉛筆。"],[88,"If you have technical issues, raise your hand and wait for assistance.","如果遇到技術問題,請舉手等候協助。"],[106,"Please remain seated while all materials are collected and verified by the exam supervisor.","監考人員收回並核對所有資料時,請留在座位上。"]]},
{"n":46,"adv":false,"v":"yEkVE99WJ2M","s":[[17,"This laundry room is for residents.","這間洗衣房供住戶使用。"],[29,"Machines accept payment via the mobile app.","機器可以用手機應用程式付款。"],[42,"Detergent pods are sold at the front desk.","櫃台有販售洗衣球。"],[55,"Wash cycles typically last about 45 minutes.","洗衣程序通常大約 45 分鐘。"],[70,"Large tables are provided for sorting your clothes.","有大桌子讓你分類衣服。"],[85,"Please report machine issues using the posted contact number.","機器有問題請撥打公告的聯絡電話回報。"],[103,"The room is monitored by cameras to ensure the security of all residents.","這個房間有監視器監控,以確保所有住戶的安全。"]]},
{"n":47,"adv":false,"v":"fiV6rC31kis","s":[[17,"This is the community swimming pool.","這是社區游泳池。"],[28,"All guests must shower before entering.","所有客人入池前都必須淋浴。"],[40,"Lap swimming takes place in the two center lanes.","來回游泳請使用中間的兩個水道。"],[55,"Towels and lockers are available near the entrance.","入口附近有毛巾和置物櫃可用。"],[69,"If you need help, a lifeguard is always on duty.","如果需要幫忙,隨時都有救生員值班。"],[85,"Children must stay within arm's reach of an adult at all times.","兒童必須隨時待在大人伸手可及的範圍內。"],[103,"When the whistle sounds, please exit the water and wait for the next announcement.","哨聲響起時,請離開水中並等待下一個廣播。"]]},
{"n":48,"adv":false,"v":"N7vn-jGBQyg","s":[[17,"This is the community fitness center.","這是社區健身中心。"],[28,"Please scan your membership card before entering.","進入前請先刷你的會員卡。"],[40,"Cardio machines are located on the upper level.","有氧運動器材在樓上。"],[54,"Free weights are always located in the back area.","自由重量器材都放在後面的區域。"],[69,"Please wipe down all machines and return the equipment.","請擦拭所有機器並把器材歸位。"],[85,"If you are unsure how to use something, please ask for help.","如果不確定某樣器材怎麼使用,請尋求協助。"],[102,"Personal trainers are available by appointment to help you reach your fitness goals.","可以預約私人教練,幫助你達成健身目標。"]]},
{"n":49,"adv":false,"v":"AogiJ8iHmw8","s":[[17,"Welcome to the city public library.","歡迎來到市立公共圖書館。"],[29,"Library cards are required for checkout.","借書需要借書證。"],[42,"Computers are located on the main floor.","電腦設在一樓。"],[56,"Quiet study areas are designated on the upper level.","樓上設有安靜的自習區。"],[71,"Books can be renewed online or at the circulation desk.","書可以在網路上或流通櫃台續借。"],[88,"Overdue items incur small fines based on the number of days late.","逾期物品會依照逾期天數收取少許罰款。"],[106,"Events and workshops are held regularly in the community room downstairs.","樓下的社區活動室定期舉辦活動和工作坊。"]]},
{"n":50,"adv":false,"v":"XSgCbV2f00g","s":[[17,"Welcome to the dormitory.","歡迎來到宿舍。"],[28,"Each room comes with basic furniture.","每個房間都附有基本家具。"],[40,"Laundry facilities are located downstairs.","洗衣設施在樓下。"],[54,"Quiet hours begin at 10:00 p.m. on weekdays.","平日的安靜時間從晚上 10 點開始。"],[68,"Common areas are open for studying or socializing.","公共區域開放給大家讀書或交誼。"],[75,"Resident assistants are available for support throughout the year.","宿舍輔導員全年都可以提供協助。"],[94,"Before moving in, review the list of approved and prohibited items.","搬進來之前,請先看過允許和禁止攜帶的物品清單。"]]},
{"n":51,"adv":false,"v":"z_zgW5HF7nE","s":[[17,"Welcome to the flight.","歡迎搭乘本班機。"],[29,"Please have your boarding pass ready.","請準備好你的登機證。"],[42,"Place larger bags in the overhead bin.","把較大的包包放在上方的行李櫃。"],[49,"Small personal items belong under your seat.","小型的個人物品請放在座位底下。"],[71,"All electronic devices must be in airplane mode.","所有電子裝置都必須切換到飛航模式。"],[89,"Fasten your seat belt while the aircraft is in motion.","飛機移動時請繫好安全帶。"],[107,"The flight attendants will now begin our in-flight beverage and snack service.","空服員現在將開始提供機上飲料和點心服務。"]]},
{"n":52,"adv":false,"v":"D3rxWSbVgww","s":[[17,"Visit the writing center.","來寫作中心看看。"],[29,"Bring a draft of your essay.","帶著你的文章草稿。"],[41,"Tutors help with grammar and citations.","輔導員會協助處理文法和引用格式。"],[55,"Appointments usually last for about 30 minutes.","每次預約通常大約 30 分鐘。"],[70,"Walk-in sessions are always available on a first-come basis.","隨時都可以現場諮詢,先到先服務。"],[76,"Our experienced tutors will assist you with formatting and style.","我們經驗豐富的輔導員會協助你處理格式和文體。"],[103,"Please remain quiet while other students are working on their final assignments.","其他同學在寫期末作業時,請保持安靜。"]]},
{"n":53,"adv":false,"v":"abNAYuw8u6g","s":[[17,"Welcome to the lecture hall.","歡迎來到演講廳。"],[30,"Please take a seat quietly.","請安靜入座。"],[43,"Emergency exits are marked on both sides of the room.","教室兩側都有標示緊急出口。"],[59,"Food and open drinks are not allowed during the lecture.","上課期間不得飲食,也不能有未加蓋的飲料。"],[76,"Laptops may be used for note-taking, but sound must be turned off.","可以用筆電做筆記,但必須關掉聲音。"],[94,"If you arrive late, enter through the rear doors to minimize disruption.","如果遲到,請從後門進入,盡量減少干擾。"],[114,"Once the lecture begins, students are expected to remain seated until the session ends.","課程一開始,學生就應該坐到下課為止。"]]},
{"n":54,"adv":false,"v":"PaDr7LHXAH0","s":[[16,"Welcome to the city bus terminal.","歡迎來到市區公車總站。"],[30,"Please check the departure board carefully.","請仔細查看發車時刻看板。"],[44,"Tickets must be purchased before entering the boarding area.","進入候車區之前必須先買票。"],[60,"Buses depart from the numbered gates located along the main platform.","公車從主月台沿線編號的乘車門發車。"],[77,"Passengers should arrive at their gate at least 10 minutes early.","乘客應至少提早 10 分鐘到達乘車門。"],[94,"If your bus is delayed, listen for updates over the public announcement system.","如果你的公車誤點,請注意廣播系統的最新消息。"],[114,"For safety reasons, unattended luggage may be removed and reported to terminal security.","基於安全考量,無人看管的行李可能會被移走並通報總站保全。"]]},
{"n":55,"adv":false,"v":"0COwIn5MSkw","s":[[17,"Welcome to the hospital.","歡迎來到醫院。"],[31,"Please sign in using the touch screen.","請用觸控螢幕報到。"],[46,"Appointment confirmations can be printed at the kiosk nearby.","可以在附近的自助機列印預約確認單。"],[63,"Visitors are required to wear masks in all clinical areas.","訪客在所有診療區域都必須戴口罩。"],[80,"Waiting times may vary depending on patient priority and staffing levels.","等候時間可能因病人的優先順序和人力狀況而有所不同。"],[99,"If your condition worsens, notify the reception staff immediately.","如果你的狀況惡化,請立刻通知櫃台人員。"],[121,"For patient privacy, personal conversations should be kept quiet throughout the waiting area.","為了保護病人隱私,在整個候診區私人談話請保持小聲。"]]},
{"n":56,"adv":false,"v":"1FGUhK2md48","s":[[17,"Welcome to the lab.","歡迎來到實驗室。"],[31,"Safety rules are very important here.","在這裡,安全規則非常重要。"],[46,"Keep your workspace clean and organized at all times.","隨時保持你的工作區乾淨整齊。"],[62,"Always wear goggles and gloves before starting any experiment.","開始任何實驗之前,一定要戴上護目鏡和手套。"],[79,"If you spill a chemical, please notify the instructor immediately.","如果打翻化學藥品,請立刻通知老師。"],[98,"Never mix chemical substances unless the lab manual instructions indicate to do so.","除非實驗手冊有指示,否則絕對不要混合化學物質。"],[111,"Before leaving, dispose of all materials properly and wash your hands thoroughly with soap and water.","離開前,妥善丟棄所有材料,並用肥皂和清水徹底洗手。"]]},
{"n":57,"adv":false,"v":"U_1B0DqCpDQ","s":[[17,"Enter the parking lot.","進入停車場。"],[31,"Please follow the directional arrows.","請依照方向箭頭行駛。"],[45,"Available spaces are marked with white lines.","可停的車位都以白線標示。"],[61,"Vehicles must be parked within a single marked space.","車輛必須停在單一的停車格內。"],[79,"Payment machines are located near the pedestrian exits.","繳費機設在行人出口附近。"],[97,"If you experience payment issues, use the help button on the machine.","如果繳費有問題,請按機器上的求助按鈕。"],[116,"The parking authority is not responsible for loss or damage to personal property.","停車場管理單位對個人財物的遺失或損壞不負責任。"]]},
{"n":58,"adv":false,"v":"S6QUhaIGtSI","s":[[17,"Welcome to the botanical garden.","歡迎來到植物園。"],[31,"Please stay on the marked paths.","請走在標示的步道上。"],[44,"Informational signs are posted beside each plant collection.","每個植物區旁邊都設有解說牌。"],[60,"Visitors are not permitted to pick flowers or remove any plants.","遊客不得摘花或帶走任何植物。"],[77,"Guided tours are offered daily and begin near the main entrance.","每天都有導覽,從正門附近出發。"],[95,"If you have questions about specific species, ask a staff member wearing a green badge.","如果對特定物種有疑問,請詢問配戴綠色名牌的工作人員。"],[116,"To help protect rare plants and wildlife, visitors are asked to follow all posted rules throughout the garden.","為了保護珍稀的植物和野生動物,請遊客在整個植物園內遵守所有公告的規定。"]]},
{"n":59,"adv":false,"v":"6-XqcYOUA1Y","s":[[17,"This is lost and found.","這裡是失物招領處。"],[30,"Please describe your missing item.","請描述你遺失的物品。"],[44,"We store all found valuable objects.","我們保管所有拾獲的貴重物品。"],[60,"Items are organized by the date they were found.","物品依照拾獲的日期整理存放。"],[76,"Please provide a detailed description for our inventory records.","請提供詳細的描述,以便我們登錄在清單紀錄上。"],[96,"You must present a valid photo ID to claim your belongings.","你必須出示有效的附照片身分證件才能領回物品。"],[107,"Any items not claimed within 30 days will be processed for public auction or disposal.","30 天內未被領取的物品將被公開拍賣或處理掉。"]]},
{"n":60,"adv":false,"v":"Brrvb6d1AzU","s":[[18,"Keep hallways clear.","保持走廊暢通。"],[30,"Please stay to the right.","請靠右走。"],[44,"Avoid congregating near the elevator doors.","避免聚集在電梯門附近。"],[59,"Yield to staff moving heavy equipment.","禮讓搬運重型器材的工作人員。"],[75,"Use designated areas for all video calls.","所有視訊通話請在指定區域進行。"],[92,"Please keep your voice low when passing active workspaces.","經過有人工作的區域時請降低音量。"],[111,"If you need to have an extended discussion, please move into a private meeting room.","如果需要長時間討論,請移到獨立的會議室。"]]},
{"n":61,"adv":false,"v":"zVdmd1H3PBw","s":[[17,"Stay in marked areas.","請待在標示的區域內。"],[31,"Please swim within protected zones.","請在有防護的區域內游泳。"],[45,"Children must be supervised at all times.","兒童必須隨時有人看顧。"],[61,"Lifeguards are stationed along the shoreline during daylight hours.","白天時段海岸線沿途都有救生員駐守。"],[80,"Strong currents may occur beyond the designated swimming zone.","指定的游泳區外可能會有強勁的海流。"],[98,"If you see someone in distress, alert a lifeguard immediately.","如果看到有人遇險,請立刻通知救生員。"],[118,"For your protection, beach conditions and warnings are updated regularly throughout the day.","為了保護你的安全,海灘狀況和警告會在一天中定期更新。"]]},
{"n":62,"adv":false,"v":"6-rhr8DXUV8","s":[[17,"Dress for success.","穿著得體,邁向成功。"],[30,"Please bring three printed resumes.","請帶三份印好的履歷。"],[45,"Turn off your mobile phone now.","現在請把手機關機。"],[60,"Arrive early for your mock interview.","模擬面試請提早到。"],[75,"Use the online portal to schedule all your meetings.","使用線上系統安排你所有的面談。"],[95,"Career counselors are available to provide professional feedback on your cover letter.","職涯輔導員可以為你的求職信提供專業的意見。"],[116,"If you need help with your application, please visit the main office for a walk-in session.","如果申請需要協助,請到主辦公室現場諮詢。"]]},
{"n":63,"adv":false,"v":"Dtydh1GIyIQ","s":[[16,"Scan your items.","掃描你的商品。"],[30,"Please place items in the bagging area.","請把商品放在裝袋區。"],[45,"Select your preferred payment method on the screen.","在螢幕上選擇你想用的付款方式。"],[62,"Wait for the green light before you start scanning.","等綠燈亮了再開始掃描。"],[79,"Heavy or bulky items may stay in your shopping cart.","又重又大的商品可以留在購物車裡。"],[98,"An associate will assist you with restricted items or technical errors.","遇到限購商品或技術錯誤時,店員會協助你。"],[118,"If the machine malfunctions, please remain at the station and wait for a store employee.","如果機器故障,請留在原地等候店員。"]]},
{"n":64,"adv":false,"v":"a-OAvIza2AY","s":[[17,"Join a club.","參加一個社團。"],[31,"Visit the information desk for help.","需要幫忙請到服務台。"],[45,"Student ID cards are issued on the second floor.","學生證在二樓發放。"],[61,"You can book a private study room through the app.","你可以透過應用程式預約個人自習室。"],[78,"Please keep the common lounge area clean for other students.","請為其他同學保持公共交誼區的整潔。"],[97,"The lost and found office is located near the main entrance.","失物招領處在正門附近。"],[117,"If you want to start an organization, please submit a formal proposal to the committee.","如果你想成立一個社團,請向委員會提交正式的申請書。"]]},
{"n":67,"adv":false,"v":"urKUgtDllPs","s":[[17,"Wear safety goggles.","戴上護目鏡。"],[29,"Always handle chemicals with care.","處理化學藥品時一定要小心。"],[44,"Keep your workstation clean and organized.","保持你的工作檯乾淨整齊。"],[60,"Do not perform any unauthorized experiments.","不要進行任何未經許可的實驗。"],[77,"Properly dispose of all waste in labeled containers.","把所有廢棄物妥善丟進有標示的容器。"],[95,"You must report any equipment malfunctions to the instructor immediately.","任何設備故障都必須立刻向老師報告。"],[115,"If you are unsure about a procedure, please consult the laboratory manual for further guidance.","如果不確定某個步驟,請查閱實驗手冊以獲得進一步的指引。"]]},
{"n":69,"adv":false,"v":"DBkuLoT84cc","s":[[17,"Boarding starts now.","現在開始登船。"],[31,"Please wait behind the yellow line.","請在黃線後方等候。"],[46,"Foot passengers should use the side ramp.","徒步乘客請使用側邊的坡道。"],[62,"Vehicles must turn off their engines during transit.","航行期間車輛必須熄火。"],[79,"Life jackets are located underneath your assigned seats.","救生衣放在你指定座位的下方。"],[97,"Bicycles are permitted only in the specific designated storage areas.","腳踏車只能停放在特定的指定存放區。"],[117,"If the weather becomes severe, please remain inside the cabin for your personal safety.","如果天氣變得惡劣,為了你的安全請待在船艙內。"]]},
{"n":71,"adv":false,"v":"5OzFE6byGrA","s":[[18,"Silence your phone.","請把手機調成靜音。"],[30,"Please remove all metal objects now.","現在請取下所有金屬物品。"],[45,"Empty your pockets into the plastic bins.","把口袋裡的東西倒進塑膠籃裡。"],[61,"Electronic devices must remain powered off inside courtrooms.","在法庭內,電子裝置必須保持關機。"],[79,"All visitors must pass through a security screening station.","所有訪客都必須通過安全檢查站。"],[98,"Maintaining absolute silence is required while the court is in session.","開庭期間必須保持絕對安靜。"],[118,"If you fail to follow these regulations, security will ask you to leave the building.","如果不遵守這些規定,保全會請你離開大樓。"]]},
{"n":72,"adv":false,"v":"wgv2UAuAQFo","s":[[18,"Find your seat.","找到你的座位。"],[29,"Please occupy your assigned seating.","請坐在你被分配的座位上。"],[43,"There will be a 20-minute intermission.","中場會有 20 分鐘的休息。"],[58,"Flash photography is not permitted during performances.","表演期間禁止使用閃光燈拍照。"],[75,"Late arrivals will be seated during the first applause.","遲到的觀眾會在第一次鼓掌時入座。"],[93,"Refreshments are only available for purchase in the main lobby area.","點心飲料只在主大廳區域販售。"],[113,"If you leave your seat during the show, wait for an usher to assist with your re-entry.","如果表演中離開座位,請等候帶位人員協助你回座。"]]},
{"n":73,"adv":false,"v":"oDMpLVRgniA","s":[[17,"Check your credits.","檢查你的學分。"],[30,"Please submit your final transcript.","請繳交你的最終成績單。"],[45,"Enrollment begins on the first Monday of October.","選課從十月的第一個星期一開始。"],[60,"Prerequisites are strictly required for this specific advanced course.","這門進階課程嚴格要求先修科目。"],[77,"Graduation applications are due by the final spring semester deadline.","畢業申請必須在春季學期的最後期限前提交。"],[96,"You must verify your enrollment status before receiving any financial aid.","領取任何助學金之前,你必須確認自己的在學狀態。"],[116,"If you plan to transfer, please request an official physical copy of your academic records.","如果你打算轉學,請申請一份正式的紙本成績紀錄。"]]},
{"n":74,"adv":false,"v":"hnZjD8Q27EE","s":[[16,"Store food properly.","妥善存放食物。"],[30,"Keep food inside locked vehicles.","把食物放在上鎖的車內。"],[44,"Do not hike alone after sunset.","日落後不要獨自健行。"],[59,"Please pack out every piece of trash.","請把每一件垃圾都帶走。"],[76,"Maintain a 100-yard distance from all large wildlife.","與所有大型野生動物保持 100 碼的距離。"],[94,"Sudden weather changes occur frequently at these high mountain elevations.","在這樣的高海拔山區,天氣經常突然變化。"],[114,"If you get lost, please provide your exact GPS coordinates to the park rangers.","如果迷路,請向公園巡守員提供你準確的 GPS 座標。"]]},
{"n":75,"adv":false,"v":"vfVCEM5vgGg","s":[[16,"State your purpose.","說明你的目的。"],[25,"Present your valid passport.","出示你的有效護照。"],[43,"Bring original documents to your interview.","面談時攜帶正本文件。"],[58,"Biometric appointments require a strictly confirmed time.","生物特徵採集的預約必須有確認好的時間。"],[77,"Processing times vary depending on your specific visa category.","處理時間依你的簽證類別而有所不同。"],[95,"You must notify the local office of any physical address changes.","任何住址變更都必須通知當地辦事處。"],[114,"If your application is pending, please check the online portal for all recent status updates.","如果你的申請還在審核中,請到線上入口網站查看最新的狀態。"]]},
{"n":76,"adv":false,"v":"cklZZWljiIc","s":[[17,"Have tickets ready.","請準備好門票。"],[29,"Open all bags for inspection.","打開所有包包接受檢查。"],[43,"Prohibited items include glass and outside alcohol.","違禁物品包括玻璃製品和外帶的酒類。"],[60,"All spectators must pass through metal detectors.","所有觀眾都必須通過金屬探測門。"],[77,"Please remain in your assigned section during play.","比賽進行時請待在你指定的區域。"],[94,"Smoking is strictly forbidden inside the entire stadium complex.","整個體育場園區內嚴格禁止吸菸。"],[113,"If you experience a medical emergency, please alert the nearest security officer immediately.","如果發生緊急醫療狀況,請立刻通知最近的保全人員。"]]},
{"n":77,"adv":false,"v":"vrJwBiMu6Fs","s":[[17,"Wear your wristband.","請戴上你的手環。"],[30,"Please keep your ticket for re-entry.","請保留你的票以便再次入場。"],[43,"Outside food is prohibited inside the gates.","大門內禁止攜帶外食。"],[58,"Please supervise children near the carnival rides.","在嘉年華遊樂設施附近請看顧好孩子。"],[74,"Lost items are held at the central information booth.","遺失物品存放在中央服務台。"],[92,"You must maintain a clear path for all emergency vehicles.","你必須為所有緊急車輛保持通道暢通。"],[111,"If you feel unwell, please visit the first aid station to receive immediate medical assistance.","如果覺得身體不舒服,請到急救站接受立即的醫療協助。"]]},
{"n":78,"adv":true,"v":"JGvj7KyBSyM","s":[[25,"The deadline to drop a class without a penalty is this Friday.","不受處罰退選課程的截止日期是這個星期五。"],[43,"You need to meet with your academic adviser before registering for classes.","選課前你需要先和你的導師面談。"],[62,"Transcripts can be requested through the student portal for a small processing fee.","可以透過學生入口網站申請成績單,需支付少許手續費。"],[81,"Late applications for graduation will not be accepted under any circumstances after the final deadline.","最後期限過後,在任何情況下都不接受逾期的畢業申請。"],[103,"Most introductory courses fill up quickly, so it is recommended that you enroll as early as possible.","大多數入門課程很快就會額滿,所以建議你盡早選課。"],[125,"Students who wish to change their major must submit a formal petition to the dean of students.","想轉系的學生必須向學務長提交正式申請。"],[145,"Although some classes are offered online, the majority of the core curriculum requires in-person attendance at least once a week.","雖然有些課程在線上開設,但大部分核心課程每週至少需要親自出席一次。"]]},
{"n":79,"adv":false,"v":"MBj8K7YkRUU","s":[[17,"State your business.","說明你的來意。"],[30,"Please present a valid photo identification.","請出示有效的附照片身分證件。"],[45,"All visitors must check in at the front desk.","所有訪客都必須在櫃台登記。"],[63,"Please remove all metal objects before entering the scanner.","進入掃描器前,請取下所有金屬物品。"],[81,"Unauthorized personnel are not permitted beyond the security checkpoint.","未經授權的人員不得通過安全檢查站。"],[102,"You must wear your issued visitor badge visibly on your outer clothing.","你必須把發給你的訪客證明顯地配戴在外衣上。"],[123,"Please abandon all prohibited items before attempting to enter the restricted building area.","進入大樓管制區域之前,請丟棄所有違禁物品。"]]},
{"n":80,"adv":false,"v":"X1mxIG7jf7I","s":[[17,"Wear safety helmets.","請戴安全帽。"],[30,"Do not touch the machinery.","請勿觸碰機器。"],[43,"Please stay within the yellow lines.","請待在黃線內。"],[58,"Always wear your protective safety goggles.","務必戴上防護用的護目鏡。"],[76,"Watch for moving parts on the automated conveyor.","小心自動輸送帶上的活動零件。"],[93,"Avoid distracting the technicians while they are operating heavy equipment.","技術人員操作重型設備時,避免讓他們分心。"],[113,"Visitors must follow designated paths to avoid interfering with the automated manufacturing process.","訪客必須沿著指定路線走,以免干擾自動化的生產流程。"]]},
{"n":81,"adv":false,"v":"BAk1oZnDUBo","s":[[17,"Keep the aisles clear.","保持走道暢通。"],[30,"Please supervise all children.","請看顧好所有孩子。"],[44,"Do not loiter near emergency exits.","不要在緊急出口附近逗留。"],[59,"Follow all safety signs on the moving escalators.","搭乘電扶梯時請遵守所有安全標示。"],[76,"Please keep your original receipt for all item returns.","退貨時請保留原始收據。"],[95,"Shoplifting is a criminal offense and will be fully prosecuted.","順手牽羊是刑事犯罪,一律依法追訴。"],[115,"If you notice any suspicious activity, please notify mall security personnel immediately.","如果發現任何可疑活動,請立刻通知商場保全人員。"]]},
{"n":82,"adv":false,"v":"Tg6lThwi6d8","s":[[17,"Confirm your booking.","確認你的訂位。"],[30,"Please arrive 15 minutes before seating.","請在入座前 15 分鐘抵達。"],[46,"Late arrivals may lose their table assignment.","遲到可能會失去保留的座位。"],[63,"A valid credit card is strictly required to guarantee tables.","必須提供有效的信用卡才能保留座位。"],[81,"Please notify us regarding any specific dietary requirements or allergies.","如有任何特殊飲食需求或過敏,請告知我們。"],[102,"All cancellations must be made at least 24 hours in advance to avoid a penalty.","所有取消都必須至少提前 24 小時,以免被收取罰款。"],[123,"Missing the grace period results in a standard no-show fee automatically charged to your card.","超過寬限時間未到,會自動從你的信用卡收取標準的未到費用。"]]},
{"n":83,"adv":true,"v":"4dfW9ARQIy8","s":[[25,"Sale items may be available only while supplies last.","特價商品可能售完為止。"],[42,"Customers should keep their receipts for any exchanges or refunds.","顧客應保留收據,以便換貨或退款。"],[61,"Some stores offer extended warranties for an additional fee at the time of purchase.","有些店家在購買時提供需額外付費的延長保固。"],[81,"Customers are encouraged to compare prices carefully before making a final purchasing decision.","鼓勵顧客在做最後的購買決定前仔細比價。"],[102,"Refunds are typically processed using the original payment method, depending on store policy and verification procedures.","退款通常會依照店家政策和核對程序,退回原本的付款方式。"],[125,"If a product is defective, customers should contact customer service promptly to request an inspection or replacement.","如果產品有瑕疵,顧客應盡快聯絡客服,要求檢查或更換。"],[149,"Although most stores offer return policies, customers should always review the conditions carefully before completing any purchase online or in store.","雖然大多數店家都有退貨政策,但無論在線上或實體店購物,顧客在完成購買前都應仔細閱讀相關條件。"]]},
{"n":84,"adv":false,"v":"z55nNmQWSpQ","s":[[17,"Keep the glass clean.","保持玻璃乾淨。"],[29,"No flash photography is permitted.","禁止使用閃光燈拍照。"],[42,"Please refrain from tapping on acrylic tanks.","請勿敲打壓克力水族箱。"],[58,"Wash hands thoroughly before touching any marine life.","觸摸任何海洋生物之前,請徹底洗手。"],[76,"Please avoid splashing water or throwing objects near the open exhibits.","請避免在開放式展區附近潑水或丟東西。"],[96,"All visitors must remain behind the safety rails during scheduled animal feedings.","在定時的動物餵食期間,所有遊客都必須待在安全欄杆後方。"],[118,"If you notice a leak, please notify a staff member at the main desk immediately.","如果發現漏水,請立即通知服務台的工作人員。"]]},
{"n":85,"adv":false,"v":"ICUhZSi-yfM","s":[[17,"Start the simulation.","開始模擬。"],[30,"Please reset the experiment after use.","使用後請將實驗重設。"],[44,"Do not force any mechanical levers upward.","不要硬把任何機械拉桿往上扳。"],[59,"All young children must be accompanied by an adult.","所有幼童都必須由大人陪同。"],[76,"Use the provided hand sanitizer before touching any touchscreen displays.","觸碰任何觸控螢幕前,請使用提供的乾洗手。"],[96,"Please remain behind the yellow safety line during the live physics demonstration.","現場物理示範期間,請待在黃色安全線後方。"],[116,"If the display malfunctions, please press the red button to call a technician for assistance.","如果展示裝置故障,請按紅色按鈕呼叫技術人員協助。"]]},
{"n":85.5,"adv":false,"v":"iAaZe-qik8s","s":[[17,"Expect cloudy skies.","預計天空多雲。"],[24,"Temperatures will stay cool.","氣溫將維持涼爽。"],[45,"Light rain is possible later.","稍晚可能會下小雨。"],[60,"Rain may develop in some areas late in the afternoon.","傍晚時分部分地區可能會下雨。"],[76,"The daytime high will reach 20 degrees Celsius by mid-afternoon.","白天最高溫將在午後達到攝氏 20 度。"],[96,"Winds will strengthen this evening across much of the northern region.","今晚北部大部分地區的風勢將增強。"],[115,"Tomorrow morning, skies will clear, but temperatures will remain well below normal seasonal averages.","明天早上天氣會轉晴,但氣溫仍會明顯低於季節的正常平均值。"]],"name":"85B"},
{"n":86,"adv":true,"v":"CrKixkh75oo","s":[[26,"Passengers must present valid identification at the security checkpoint.","乘客必須在安檢站出示有效的身分證件。"],[44,"Liquids must be placed in approved containers before going through airport screening.","通過機場安檢前,液體必須裝在核准的容器中。"],[64,"Boarding announcements are made in advance, so travelers should remain near their assigned departure gate.","登機廣播會提前通知,所以旅客應待在指定的登機門附近。"],[85,"Travelers are advised to arrive early to allow sufficient time for check-in, security screening, and possible delays.","建議旅客提早到達,預留足夠的時間辦理報到、安檢和應付可能的延誤。"],[108,"Some items may be restricted depending on airline regulations and destination-specific entry requirements.","部分物品可能會依航空公司規定和目的地的入境要求而受到限制。"],[130,"In the event of a delay, passengers will receive updated information through airport displays and official airline notifications.","如果發生延誤,乘客會透過機場顯示螢幕和航空公司的正式通知收到最新資訊。"],[153,"Although most flights depart on schedule, unexpected severe weather or technical problems may occasionally cause unavoidable delays for travelers worldwide.","雖然大多數班機都準時起飛,但突如其來的惡劣天氣或技術問題偶爾仍會為全球旅客造成無法避免的延誤。"]]},
{"n":87,"adv":false,"v":"Ly3TUn8Xyz0","s":[[18,"Stay on the trail.","請走在步道上。"],[29,"Pack out all trash.","把所有垃圾帶走。"],[42,"Yield to hikers moving uphill.","禮讓上坡的健行者。"],[58,"Avoid stepping on fragile vegetation.","避免踩踏脆弱的植物。"],[73,"Monitor elevation gain to avoid exhaustion.","注意爬升的高度,以免體力透支。"],[90,"Wear sturdy footwear to maintain traction on uneven terrain.","穿著堅固的鞋子,在不平的地形上保持抓地力。"],[109,"Visitors must remain on marked paths to prevent damage to the delicate mountain ecosystem.","遊客必須走在標示的路徑上,以免破壞脆弱的山區生態系統。"]]},
{"n":88,"adv":false,"v":"yDrrlv1RfyU","s":[[17,"Remain behind the ropes.","請待在圍繩後方。"],[30,"Please do not touch the fossils.","請勿觸摸化石。"],[44,"Do not disturb the skeletal remains.","請勿觸動骨骸。"],[59,"Handle all archaeological replicas with care.","小心拿取所有考古複製品。"],[77,"Avoid leaning against the protective glass display cases.","避免倚靠保護用的玻璃展示櫃。"],[95,"Large backpacks must be checked into the secure cloakroom area.","大型背包必須寄放在安全的寄物處。"],[115,"Please maintain a quiet environment for the preservation of these rare ancient artifacts.","為了保存這些珍貴的古代文物,請保持安靜的環境。"]]},
{"n":90,"adv":true,"v":"f2_841yROHc","s":[[26,"Library resources are available to all enrolled students.","所有在學學生都可以使用圖書館資源。"],[42,"Students are encouraged to utilize academic support services early in the semester.","鼓勵學生在學期初就善用學業輔導服務。"],[61,"Access to specialized equipment may require prior authorization from the supervising department.","使用專門設備可能需要事先取得主管單位的授權。"],[81,"Counseling appointments are confidential and are scheduled based on availability and individual needs.","諮商預約會保密,並依照可預約時段和個人需求安排。"],[102,"Students experiencing academic difficulty may be referred to additional support programs for targeted assistance.","有學業困難的學生可能會被轉介到額外的輔導計畫,獲得針對性的協助。"],[124,"Use of shared facilities is subject to institutional policies intended to ensure fairness and safety for all users.","共用設施的使用須遵守學校的規定,以確保所有使用者的公平與安全。"],[145,"Although most services operate year-round, access may be temporarily limited during peak periods due to staffing constraints and facility maintenance.","雖然大多數服務全年開放,但在尖峰時期可能因人力不足和設施維修而暫時限制使用。"]]},
{"n":91,"adv":false,"v":"woMULmmr3u0","s":[[17,"Keep the aisles clear.","保持走道暢通。"],[30,"Display your wristband for entry.","出示你的手環以便入場。"],[44,"Do not climb on the safety barricades.","不要攀爬安全護欄。"],[60,"Professional recording equipment is strictly prohibited inside.","場內嚴格禁止使用專業錄音錄影器材。"],[79,"Please remain within your designated standing section at all times.","請隨時待在你指定的站立區內。"],[98,"No outside food or beverages are allowed inside the main venue.","主場館內禁止攜帶外食和飲料。"],[117,"Please exit the facility slowly to ensure the continuous safety of all our guests.","請緩慢離開場館,以確保所有來賓的安全。"]]},
{"n":92,"adv":false,"v":"vcHk9gskooI","s":[[17,"Support local artisans.","支持在地工藝師。"],[30,"Browse unique handicrafts.","瀏覽獨特的手工藝品。"],[45,"Please validate all souvenir vouchers.","請確認所有紀念品兌換券的有效性。"],[61,"Only use authorized currency for purchases.","購物時只能使用核准的貨幣。"],[79,"Please supervise children during their interaction with delicate exhibits.","孩子接觸易碎的展示品時,請在旁看顧。"],[98,"Most vendors will accommodate digital payment methods for your convenience.","為了方便,大多數攤商都接受電子支付。"],[119,"Ensure that all fragile merchandise is wrapped securely before you exit the fairgrounds.","離開市集會場前,確保所有易碎商品都包裝妥當。"]]},
{"n":93,"adv":false,"v":"6Fckbbd3msY","s":[[17,"Have your ID ready.","請準備好你的身分證件。"],[29,"Please provide a valid credit card.","請提供一張有效的信用卡。"],[45,"Room keys are issued upon check-in.","入住時會發給房間鑰匙。"],[61,"Please leave your luggage with the porter at the desk.","請把行李交給櫃台的行李員。"],[77,"Valet parking is available at the main entrance for all registered hotel guests.","所有登記入住的房客都可以在正門使用代客停車服務。"],[97,"Complimentary breakfast is served daily in the dining area on the second floor.","每天在二樓用餐區供應免費早餐。"],[118,"To access the wireless network, please enter your login credentials into the authorization portal.","要使用無線網路,請在驗證頁面輸入你的登入帳密。"]]},
{"n":94,"adv":false,"v":"pHeL8KxCiXc","s":[[17,"Face the door.","面向門站。"],[30,"Allow others to exit first.","讓別人先出去。"],[45,"Stand clear of the closing elevator doors.","遠離正在關閉的電梯門。"],[62,"Please step to the back of the cabin.","請往電梯後方站。"],[78,"Use the door hold button for boarding passengers.","有人要進來時,請按開門鈕。"],[96,"Refrain from pushing the floor buttons multiple times in succession.","請勿連續多次按樓層按鈕。"],[116,"If the elevator becomes stuck, press the emergency alarm to call for technical assistance.","如果電梯卡住,請按緊急警鈴呼叫技術人員協助。"]]},
{"n":95,"adv":true,"v":"EhXtRJHDNiU","s":[[26,"Participants must sign a consent form before joining the study.","參與者加入研究前必須簽署同意書。"],[43,"All personal information collected during the research will remain confidential.","研究期間收集的所有個人資料都會保密。"],[61,"Researchers will explain the study procedures before asking participants to begin the assigned tasks.","研究人員會先說明研究程序,再請參與者開始指定的任務。"],[82,"Participants may withdraw from the study at any time without penalty or negative consequences.","參與者可以隨時退出研究,不會受到處罰或任何負面影響。"],[104,"Data collected during the experiment will be analyzed to identify patterns and support the study's objectives.","實驗期間收集的資料會被分析,以找出規律並支持研究目標。"],[128,"Some studies require follow-up sessions to monitor changes and ensure the accuracy of the research findings.","有些研究需要後續追蹤,以觀察變化並確保研究結果的準確性。"],[150,"Although most studies follow strict ethical guidelines, participants should review consent forms carefully to fully understand potential risks and procedures.","雖然大多數研究都遵守嚴格的倫理規範,參與者仍應仔細閱讀同意書,充分了解可能的風險和程序。"]]},
{"n":96,"adv":false,"v":"RM191wa53AE","s":[[17,"Secure your spot.","先占好你的位子。"],[29,"Turn off all electronics.","關掉所有電子產品。"],[43,"Please avoid blocking the projection path.","請避免擋住投影的光線。"],[60,"Keep all pets within the designated lawn area.","所有寵物都應待在指定的草坪區域內。"],[76,"Use headphones to prevent frequency interference with the sound system.","請使用耳機,以免干擾音響系統的頻率。"],[95,"Dispose of all litter in the appropriate recycling or trash containers.","把所有垃圾丟進適當的回收桶或垃圾桶。"],[114,"Ensure that your folding chairs do not obstruct the view of the visitors seated behind.","確保你的折疊椅不會擋住坐在後面觀眾的視線。"]]},
{"n":97,"adv":false,"v":"2OsX2R8-IVM","s":[[17,"Maintain your distance.","請保持距離。"],[29,"Please do not touch any painted surfaces.","請勿觸碰任何畫作表面。"],[45,"Patrons must remain behind the yellow floor lines.","參觀者必須站在地上的黃線後方。"],[62,"Professional photography equipment is not allowed inside the gallery.","藝廊內禁止使用專業攝影器材。"],[80,"Please silence all mobile phones to maintain a quiet gallery environment.","請將手機調成靜音,以維持藝廊的安靜環境。"],[98,"Large groups must be accompanied by a professional guide during the entire tour.","大型團體在整個參觀過程中必須有專業導覽員陪同。"],[119,"If you feel crowded, move to a different gallery to find more comfortable personal space.","如果覺得擁擠,可以移到其他展廳,找個比較舒適的個人空間。"]]},
{"n":98,"adv":false,"v":"QTCUNxnIg9c","s":[[17,"Respect the animals.","請尊重動物。"],[30,"Do not feed any exhibit animals.","請勿餵食任何展示中的動物。"],[45,"Please avoid tapping on the glass partitions.","請避免敲打玻璃隔板。"],[61,"Maintain a quiet tone near the bird sanctuary.","在鳥類保護區附近請輕聲細語。"],[78,"Please keep all strollers and large bags outside the petting area.","請把所有嬰兒車和大型包包留在觸摸區外面。"],[97,"Children must be supervised at all times by a responsible parent or adult.","兒童必須隨時由負責的家長或成人看顧。"],[117,"If an animal approaches the fence, do not reach your hands inside the primary enclosure.","如果動物靠近圍欄,請勿把手伸進主要的圍欄內。"]]},
{"n":99,"adv":false,"v":"uJCUuGB7muU","s":[[17,"Keep the area clear.","保持這個區域淨空。"],[30,"Do not climb on railings.","不要攀爬欄杆。"],[45,"Children must wear proper shoes.","兒童必須穿著合適的鞋子。"],[61,"Use swings individually, one at a time.","盪鞦韆一次一人,輪流使用。"],[78,"Staff inspect equipment for potential hazards daily.","工作人員每天檢查設施是否有潛在危險。"],[96,"Parents should supervise children closely and prevent risky behavior at all times.","家長應隨時密切看顧孩子,並防止危險的行為。"],[109,"Before leaving, gather belongings and ensure all children remain within designated play areas.","離開前,收好隨身物品,並確保所有孩子都待在指定的遊戲區內。"]]},
{"n":100,"adv":true,"v":"7yQnmXKGGjs","s":[[26,"Please put on your safety goggles before entering the lab.","進入實驗室前請戴上護目鏡。"],[42,"The lab reports are due every Tuesday at the start of class.","實驗報告每週二上課開始時繳交。"],[59,"Make sure to clean all the glass equipment thoroughly after each use.","每次使用後,務必把所有玻璃器材徹底清洗乾淨。"],[78,"If you encounter any issues with the microscope, please inform the teaching assistant.","如果顯微鏡有任何問題,請告知助教。"],[98,"All biological samples must be stored in the refrigerator located at the back of the room.","所有生物樣本都必須存放在教室後方的冰箱裡。"],[120,"You are required to work with a partner while conducting the chemical analysis portion of the experiment.","進行實驗的化學分析部分時,你必須和一位夥伴合作。"],[141,"Because the chemicals are highly sensitive to light, the curtains in the workspace must remain closed throughout the afternoon.","因為這些化學物質對光非常敏感,工作區的窗簾整個下午都必須保持拉上。"]]},
{"n":101,"adv":false,"v":"-XzWAnjz9Ho","s":[[17,"Welcome to the arena.","歡迎來到體育館。"],[31,"Please keep walkways clear.","請保持走道暢通。"],[45,"Show your ticket at the entrance.","在入口出示你的票。"],[62,"Use the staircase to reach upper seating levels.","走樓梯前往上層座位區。"],[79,"Please hold the handrail, especially during busy entry and exit.","請握好扶手,特別是在進出場人多的時候。"],[98,"For safety, move slowly in crowded areas and follow staff directions.","為了安全,在擁擠的區域請慢慢走,並遵守工作人員的指示。"],[118,"After the event ends, please leave your section calmly and follow posted exit signs.","活動結束後,請冷靜離開你的區域,並依照出口標示走。"]]},
{"n":102,"adv":false,"v":"mrHi-qYJUAk","s":[[17,"Please stand still.","請站穩不要動。"],[24,"Always face the forward direction.","請一律面向前方。"],[46,"Hold the handrails for extra balance.","握住扶手以保持平衡。"],[63,"Do not sit on the mechanical treads.","不要坐在電扶梯的階梯上。"],[79,"Keep your loose clothing away from the side panels.","讓寬鬆的衣物遠離兩側的護板。"],[96,"Avoid walking or running while on the moving escalator to prevent serious injury.","搭乘運轉中的電扶梯時避免走動或奔跑,以免嚴重受傷。"],[117,"In an emergency, immediately activate the stop switch located at the escalator landing area.","發生緊急狀況時,立即按下電扶梯出入口處的停止開關。"]]},
{"n":103,"adv":false,"v":"FH8cJRLOtFw","s":[[17,"Choose your movie first.","先選你要看的電影。"],[31,"Then, select your showtime.","接著選擇場次。"],[45,"Please authorize your digital transaction.","請授權你的電子交易。"],[63,"Present your valid student ID for discounts.","出示有效的學生證以享有折扣。"],[81,"Please confirm your assigned seating on the interactive monitor.","請在互動螢幕上確認你的座位。"],[100,"Check your ticket for the designated theater number and premiere time.","查看票上指定的影廳號碼和開演時間。"],[120,"Purchase your concessions in the lobby before the main feature begins at the scheduled screening time.","在正片於預定時間開演前,先到大廳買好點心飲料。"]]},
{"n":104,"adv":false,"v":"Y2epteR-k74","s":[[17,"Dress appropriately today.","今天請穿著得體。"],[30,"Wait at the reception desk.","請在接待櫃台等候。"],[44,"Turn off your mobile devices.","請關掉你的行動裝置。"],[59,"Inform the server of any dietary allergies.","如有任何食物過敏,請告知服務生。"],[76,"Please confirm your reservations with the host upon your arrival.","抵達時請向接待人員確認你的訂位。"],[95,"We will do our best to accommodate your specific seating requests.","我們會盡力配合你特別的座位需求。"],[113,"Kindly notify the staff before utilizing the various amenities located within the facility.","使用場內各項設施之前,請先告知工作人員。"]]},
{"n":105,"adv":false,"v":"IB-6ptjOBnU","s":[[18,"Check ride times.","查看遊樂設施的時間。"],[31,"Store your loose items.","把零散的物品收好。"],[44,"You can buy souvenirs near the main entrance.","你可以在正門附近買紀念品。"],[60,"The mascots will greet visitors during the afternoon parade.","吉祥物會在下午的遊行中和遊客打招呼。"],[79,"The Ferris wheel offers great views of the entire park.","摩天輪可以看到整座樂園的美景。"],[97,"Children under 48 inches must be accompanied by an adult.","身高未滿 48 英吋的兒童必須由大人陪同。"],[117,"Don't miss the colorful parade in the afternoon, followed by spectacular fireworks at night.","別錯過下午繽紛的遊行,以及晚上壯觀的煙火。"]]},
{"n":106,"adv":true,"v":"HENBR-mNcvM","s":[[25,"Always fasten your safety harness before entering any ride.","搭乘任何遊樂設施前,務必扣好安全帶。"],[43,"Remain properly seated during the carousel's complete rotation.","旋轉木馬轉完一整圈之前,請保持坐好。"],[61,"Carefully supervise children while interacting with costumed mascots.","孩子和穿著玩偶裝的吉祥物互動時,請仔細看顧。"],[82,"Follow the posted safety barriers around rides and concession stands at all times.","隨時遵守遊樂設施和販賣部周圍設置的安全圍欄。"],[102,"Adhere to instructions from attendants during parades, performances, and other organized park events.","在遊行、表演和其他園區活動期間,請遵守服務人員的指示。"],[123,"Observe maximum seating capacity before boarding automated passenger vehicles operating along elevated amusement tracks.","搭乘沿著高架軌道運行的自動遊園車之前,請遵守最大載客量的規定。"],[147,"Prior to boarding automated passenger vehicles, verify seating capacity compliance and confirm secure harness attachment throughout the entire attraction cycle.","搭乘自動遊園車之前,確認符合載客量規定,並確保整趟行程中安全帶都牢牢扣好。"]]},
{"n":107,"adv":false,"v":"HsSWlYM_Ffc","s":[[18,"Buy some grain here.","在這裡買一些飼料穀物。"],[31,"Feed our animals gently.","請溫柔地餵我們的動物。"],[45,"Always sanitize your hands after contact.","接觸動物後一定要消毒雙手。"],[60,"Use only the authorized feed provided.","只能使用我們提供的指定飼料。"],[77,"Respect the dietary restrictions of each specific animal.","請尊重每種動物的飲食限制。"],[96,"Please supervise small children during their interaction with the goats.","小朋友和山羊互動時,請在旁看顧。"],[115,"Ensure that you wash your hands thoroughly before exiting the designated animal encounter zone.","離開指定的動物互動區之前,務必徹底洗手。"]]},
{"n":108,"adv":false,"v":"BU01JEFrYxk","s":[[17,"Turn off the power completely.","把電源完全關閉。"],[31,"Always wear protective gloves.","務必戴上防護手套。"],[46,"Inspect the machine carefully before use.","使用前仔細檢查機器。"],[63,"Check each component for visible wear.","檢查每個零件是否有明顯的磨損。"],[79,"Tighten loose bolts and adjust moving parts.","鎖緊鬆動的螺栓,並調整活動零件。"],[97,"Apply lubricant to the gears and carefully test the system.","在齒輪上塗潤滑油,並小心測試系統。"],[117,"After finishing maintenance, record observations and prepare equipment for the next inspection.","完成保養後,記錄觀察結果,並為下一次檢查準備好設備。"]]},
{"n":109,"adv":false,"v":"cl9dLC5xRys","s":[[17,"Loud noise is restricted.","禁止大聲喧嘩。"],[31,"Visitors should keep voices low.","訪客應輕聲說話。"],[46,"Sound from devices may disturb others.","裝置發出的聲音可能會打擾別人。"],[64,"Staff monitor this area during busy hours.","尖峰時段會有工作人員在這一區巡視。"],[82,"Excessive noise can negatively affect nearby conversations.","過大的噪音會影響附近的人交談。"],[101,"Posted signs remind guests to maintain a quiet environment.","張貼的告示提醒客人維持安靜的環境。"],[120,"If sound levels rise too much, please lower your volume and respect the shared space.","如果音量太大,請降低音量,並尊重這個共用的空間。"]]},
{"n":110,"adv":true,"v":"PyyTK-u-nTA","s":[[26,"Welcome to the municipal recycling collection facility.","歡迎來到市立資源回收場。"],[43,"Please sort recyclable materials according to their assigned category.","請依照指定的類別把可回收物分類。"],[62,"Paper, glass, and plastic items must be deposited in their respective collection bins.","紙類、玻璃和塑膠物品必須投入各自的回收桶。"],[82,"All containers should be completely emptied and thoroughly rinsed prior to disposal.","所有容器在丟棄前都應完全清空並徹底沖洗。"],[102,"Oversized recyclable materials must be placed in the designated central loading section.","大型的可回收物必須放在指定的中央裝載區。"],[124,"If you are uncertain about the appropriate disposal location, please consult the on-site recycling staff.","如果不確定該丟在哪裡,請詢問現場的回收人員。"],[146,"Improper sorting of recyclable materials may result in items being rejected and redirected to general waste processing facilities.","回收物分類不當可能導致物品被拒收,並轉送到一般垃圾處理場。"]]},
{"n":111,"adv":false,"v":"Y4fIzPXu_OA","s":[[17,"Welcome to the observation deck.","歡迎來到觀景台。"],[31,"Visitors gather near the glass panels.","遊客聚集在玻璃窗附近。"],[47,"Many people look out over the city skyline.","許多人眺望城市的天際線。"],[64,"Information displays show major landmarks across the city.","資訊看板標示出全市的主要地標。"],[82,"Visitors use binoculars to view distant buildings clearly.","遊客用望遠鏡清楚觀看遠方的建築。"],[100,"Staff monitor visitor movement and ensure everyone remains behind safety barriers.","工作人員注意遊客的動向,確保每個人都待在安全護欄後方。"],[112,"Before leaving, take a final look across the skyline and follow signs toward the elevator.","離開前,再看一眼天際線,然後依照指標前往電梯。"]]},
{"n":112,"adv":false,"v":"xPbvOK_SBtM","s":[[18,"Open the toolbox carefully.","小心打開工具箱。"],[32,"Take out the tools one by one.","把工具一件一件拿出來。"],[47,"Select a proper screwdriver for the task.","為這項工作選一支合適的螺絲起子。"],[63,"Place the tools neatly on the workbench.","把工具整齊地放在工作檯上。"],[80,"Check each nail closely for loose or worn parts.","仔細檢查每根釘子有沒有鬆動或磨損的地方。"],[98,"Use the correct tool when tightening bolts or adjusting small components.","鎖緊螺栓或調整小零件時,使用正確的工具。"],[117,"Before leaving, return all tools to the toolbox and secure the lid properly.","離開前,把所有工具放回工具箱,並把蓋子蓋好。"]]},
{"n":113,"adv":false,"v":"iB2XMhytCkA","s":[[18,"Please take a seat here.","請在這裡坐下。"],[32,"Cover one eye with your hand.","用手遮住一隻眼睛。"],[46,"Read the letters on the eye chart aloud.","大聲唸出視力表上的字母。"],[63,"Keep your head still during the optical test.","視力檢查時頭部保持不動。"],[80,"The doctor will check your vision to update your prescription.","醫生會檢查你的視力,以更新你的配鏡度數。"],[98,"Please adjust your focus when viewing objects at different distances.","看不同距離的物體時,請調整你的焦距。"],[117,"If your vision has changed, the doctor may recommend corrective lenses or further testing.","如果你的視力有變化,醫生可能會建議配戴矯正鏡片或做進一步檢查。"]]},
{"n":114,"adv":false,"v":"24ywFP4jUG4","s":[[17,"Please check in at the desk.","請到櫃台報到。"],[30,"Show your ID to receive your number.","出示身分證件以領取你的號碼布。"],[45,"Collect your race packet after verification.","核對身分後領取你的參賽物資袋。"],[60,"Runners should review the race route before the event.","跑者應在比賽前先了解比賽路線。"],[71,"Personal belongings can be stored in designated areas near the starting line.","個人物品可以寄放在起跑線附近的指定區域。"],[97,"Participants should arrive early to complete check-in and prepare for the race.","參賽者應提早到達,完成報到並為比賽做準備。"],[117,"All runners must follow safety guidelines and listen for instructions before the race begins.","比賽開始前,所有跑者都必須遵守安全規定並注意聽指示。"]]},
{"n":115,"adv":true,"v":"EioA3ptODOk","s":[[25,"Please proceed to the registration desk to complete the check-in process.","請前往報到櫃台完成報到手續。"],[44,"Present your identification to receive your conference badge and materials.","出示你的身分證件以領取會議識別證和資料。"],[64,"Name badges are organized alphabetically to facilitate an efficient registration process.","名牌依照字母順序排列,讓報到流程更有效率。"],[85,"Conference schedules and session details are included in your official registration packet.","會議議程和各場次的詳細資訊都在你的正式報到資料袋裡。"],[107,"Session rooms are clearly designated according to topic, format, and scheduled presentation times.","各場次的會議室依照主題、形式和預定的發表時間清楚標示。"],[120,"Presenters should confirm their assigned session time and technical requirements with the coordinator upon arrival.","發表人抵達時應向協調人員確認自己的場次時間和技術需求。"],[142,"Attendees are strongly advised to arrive early, as seating capacity may be limited for highly anticipated sessions.","強烈建議與會者提早到場,因為熱門場次的座位可能有限。"]]},
{"n":116,"adv":false,"v":"Tb5Im2VuAVw","s":[[17,"Workers are renovating the room.","工人正在整修房間。"],[30,"Walls are being painted in neutral colors.","牆壁正被漆成中性色。"],[46,"Tools and materials are organized on the floor.","工具和材料整齊地放在地板上。"],[62,"Carpets and furniture have been moved to another room.","地毯和家具已經被搬到另一個房間。"],[80,"Electricians install new lights and check the wiring carefully.","電工安裝新的燈具並仔細檢查線路。"],[98,"Contractors measure spaces and plan layouts for furniture arrangement.","承包商測量空間並規劃家具的擺設配置。"],[118,"During the renovation, workers coordinate tasks and manage materials while keeping the site safe.","整修期間,工人協調分工、管理材料,同時維持工地的安全。"]]},
{"n":117,"adv":false,"v":"60DP90iu-R4","s":[[17,"Sign up at the desk.","在櫃台報名。"],[31,"Enter your name and email.","輸入你的姓名和電子郵件。"],[46,"Fill out the form with your basic details.","在表格上填寫你的基本資料。"],[63,"Make sure your information is correct before submitting.","送出前確認你的資料正確。"],[80,"You may need to confirm your email to complete the registration process.","你可能需要確認電子郵件才能完成註冊程序。"],[99,"Some services require additional steps such as verifying your identity or setting a password.","有些服務需要額外的步驟,例如驗證身分或設定密碼。"],[122,"After signing up, you will receive a confirmation message and instructions to access your account.","註冊後,你會收到一則確認訊息和登入帳戶的說明。"]]},
{"n":118,"adv":false,"v":"ZMI-tO0Eid8","s":[[17,"Start your order on the screen.","在螢幕上開始點餐。"],[31,"Select your items from the menu.","從菜單中選擇你要的餐點。"],[45,"Review your order before moving to payment.","付款前先檢查你的訂單。"],[61,"Choose your payment method and follow the instructions.","選擇付款方式並依照指示操作。"],[79,"You can customize your order by adding or removing ingredients.","你可以增加或減少配料來客製化你的餐點。"],[97,"After payment, a receipt will be printed with your order number.","付款後會印出一張有訂單號碼的收據。"],[117,"When your number is called, please proceed to the counter to collect your order.","叫到你的號碼時,請到櫃台領取餐點。"]]},
{"n":119,"adv":false,"v":"OWIYq75f2pc","s":[[17,"Save your files to the cloud.","把你的檔案存到雲端。"],[30,"Use a trusted cloud service regularly.","定期使用值得信賴的雲端服務。"],[46,"Upload important files and check they are saved.","上傳重要檔案並確認它們已儲存。"],[64,"Make sure your files are uploaded before closing the app.","關閉應用程式前,確認檔案都已上傳。"],[80,"Automatic backups can protect your data from loss or device failure.","自動備份可以保護你的資料,避免遺失或因裝置故障而損失。"],[99,"You can access your files from different devices if they are stored in the cloud.","如果檔案存在雲端,你就可以從不同的裝置存取。"],[119,"If your device stops working, you can restore files from the cloud and continue working.","如果你的裝置壞了,你可以從雲端還原檔案並繼續工作。"]]},
{"n":120,"adv":false,"v":"lzhj2WHCGjQ","s":[[17,"Please show your driver's license.","請出示你的駕照。"],[30,"Confirm your reservation at the counter.","在櫃台確認你的預約。"],[46,"Choose your rental car based on availability.","依照可租的車輛選擇你的租車。"],[63,"Review the rental agreement before signing the document.","簽名之前先仔細閱讀租車合約。"],[79,"You may add insurance coverage for additional protection during your rental period.","你可以加保保險,在租車期間獲得額外的保障。"],[99,"Inspect the vehicle carefully and report any existing damage before leaving the lot.","離開停車場前,仔細檢查車子並回報任何既有的損傷。"],[119,"Return the car on time to avoid extra charges and ensure a smooth rental process.","準時還車,以避免額外費用並確保租車過程順利。"]]},
{"n":121,"adv":true,"v":"OrMuNPv0lrc","s":[[26,"Back up your files regularly to prevent unexpected data loss.","定期備份你的檔案,以防資料意外遺失。"],[45,"Always save secure copies of important data in a reliable location.","務必把重要資料的安全備份存在可靠的地方。"],[65,"Use a secure and encrypted device to store your backups safely.","使用安全且加密的裝置來妥善存放你的備份。"],[85,"Verify that your files have been properly saved after each backup process.","每次備份後,確認你的檔案都已正確儲存。"],[105,"Automated backup systems can help prevent data loss in the event of unexpected technical failures.","自動備份系統可以在發生意外技術故障時,幫助防止資料遺失。"],[126,"It is strongly recommended to store backup files in multiple locations to enhance overall data security and accessibility.","強烈建議把備份檔案存放在多個地方,以提升整體資料的安全性和可取得性。"],[149,"If a system failure occurs, having updated backups will allow you to restore your data quickly and avoid permanent loss.","如果系統發生故障,擁有最新的備份能讓你快速還原資料,避免永久遺失。"]]},
{"n":122,"adv":false,"v":"boS_tkfxWS0","s":[[17,"A delivery attempt was made.","已嘗試投遞包裹。"],[30,"The package could not be delivered today.","包裹今天無法送達。"],[45,"No one was available to receive the item.","當時沒有人可以簽收。"],[61,"Please check the delivery notice for further instructions.","請查看投遞通知單上的進一步說明。"],[78,"If the package is not claimed, it may be returned to the sender.","如果包裹無人領取,可能會被退回給寄件人。"],[97,"You can reschedule the shipment or pick up the package at a nearby location.","你可以重新安排投遞時間,或到附近的地點領取包裹。"],[117,"Make sure to bring a valid ID when collecting your package from the service point.","到服務據點領取包裹時,記得攜帶有效的身分證件。"]]},
{"n":123,"adv":false,"v":"SNuAD6vQd8s","s":[[17,"The road is closed ahead.","前方道路封閉。"],[30,"Follow the posted detour signs.","請依照公告的改道標誌行駛。"],[45,"Traffic is being redirected to an alternate route.","車流正被引導到替代道路。"],[62,"Drivers should expect delays due to ongoing construction work.","由於正在施工,駕駛人應預期會有延誤。"],[79,"Please reduce your speed and follow all safety signs in the area.","請減速,並遵守該區域所有的安全標誌。"],[98,"Construction crews are working nearby, so stay alert and proceed with caution.","施工人員正在附近工作,所以請保持警覺、小心通行。"],[118,"If possible, plan an alternate route in advance to avoid delays and heavy traffic congestion.","如果可以,請事先規劃替代路線,以避免延誤和嚴重的交通壅塞。"]]},
{"n":124,"adv":false,"v":"GMLlXLdlXYM","s":[[18,"Turn off the device.","把裝置關機。"],[31,"Wait a few seconds before restarting.","等幾秒鐘再重新開機。"],[45,"Press the power button to turn it on again.","按電源鍵再次開機。"],[61,"Check if the screen responds after the device restarts.","裝置重新開機後,檢查螢幕是否有反應。"],[79,"If the issue continues, try restarting the device one more time.","如果問題持續,再試著重新開機一次。"],[99,"Make sure all apps are closed before restarting to avoid potential system errors.","重新開機前確認所有應用程式都已關閉,以避免可能的系統錯誤。"],[119,"If the problem persists, restart the device and check for updates or contact technical support.","如果問題仍然存在,重新開機並檢查更新,或聯絡技術支援。"]]},
{"n":125,"adv":false,"v":"8Q5dSMKGY1M","s":[[17,"Wash your hands thoroughly.","徹底洗手。"],[31,"Apply soap for effective cleaning.","抹上肥皂才能有效清潔。"],[45,"Dry completely using towels or a hand dryer.","用毛巾或烘手機把手完全弄乾。"],[52,"Dispose of used paper products in designated bins.","把用過的紙類丟進指定的垃圾桶。"],[78,"Keep the area sanitary and use facilities as intended.","保持環境衛生,並依照用途使用設施。"],[96,"Avoid direct contact with surfaces after cleaning to maintain proper hygiene.","清潔後避免直接碰觸表面,以維持良好衛生。"],[116,"If any issues are observed, inform staff so the space can be cleaned and maintained promptly.","如果發現任何問題,請通知工作人員,以便及時清潔和維護。"]]},
{"n":126,"adv":true,"v":"5yX7S55HK6M","s":[[26,"Patients should bring valid identification to every medical appointment.","病人每次看診都應攜帶有效的身分證件。"],[43,"Please arrive early to complete any required forms before seeing the doctor.","請提早到達,在看醫生前填好所有必要的表格。"],[63,"Prescription medications should be taken exactly as instructed by your healthcare provider.","處方藥應完全依照醫療人員的指示服用。"],[83,"Patients are encouraged to describe their symptoms clearly to support an accurate diagnosis and appropriate treatment.","鼓勵病人清楚描述症狀,以利準確的診斷和適當的治療。"],[104,"Appointment times may vary depending on the number of patients and the complexity of their medical concerns.","看診時間可能因病人人數和病情的複雜程度而有所不同。"],[125,"If test results require further review, the clinic will contact patients to discuss follow-up care or additional evaluation.","如果檢查結果需要進一步審閱,診所會聯絡病人討論後續照護或額外的評估。"],[148,"Although routine appointments are usually brief, patients should prepare questions in advance to ensure clear communication with their healthcare providers.","雖然例行看診通常很短,病人仍應事先準備問題,以確保和醫療人員溝通清楚。"]]},
{"n":127,"adv":false,"v":"233uRhYnsvE","s":[[17,"Keep noise levels low.","請保持低音量。"],[31,"Speak quietly in this study area.","在這個自習區請小聲說話。"],[46,"Loud conversations may disturb others nearby.","大聲交談可能會打擾附近的人。"],[62,"Please use headphones when playing audio or videos.","播放音訊或影片時請戴耳機。"],[79,"Library staff may remind visitors to lower volume during peak hours.","尖峰時段圖書館人員可能會提醒讀者降低音量。"],[96,"Phone calls should be taken outside the reading room to avoid disrupting study sessions.","請到閱覽室外接電話,以免打擾他人讀書。"],[116,"If noise continues, you may be asked to leave to maintain a quiet study environment.","如果持續製造噪音,你可能會被請離開,以維持安靜的讀書環境。"]]},
{"n":128,"adv":false,"v":"jmuUiHz5eSY","s":[[17,"Park only in marked spaces.","只能停在畫好的停車格內。"],[30,"Use rest areas for short breaks.","利用休息區短暫休息。"],[44,"Restrooms and vending machines are nearby.","附近有洗手間和自動販賣機。"],[60,"Do not leave valuables unattended inside your vehicle.","不要把貴重物品留在車內無人看管。"],[77,"Drivers should rest if they feel tired before continuing.","駕駛人如果感到疲倦,應先休息再繼續上路。"],[95,"Dispose of trash properly to keep the rest area clean for all travelers.","妥善丟棄垃圾,為所有旅客保持休息區的整潔。"],[106,"Before leaving, check your vehicle and personal belongings to ensure nothing is left behind.","離開前,檢查你的車子和個人物品,確保沒有遺漏任何東西。"]]},
{"n":129,"adv":false,"v":"AweVg2n5ClQ","s":[[17,"Please show your ticket clearly.","請清楚出示你的票。"],[30,"Enter through the main gate entrance.","從正門入口進入。"],[44,"Follow signs to your screening room.","依照指標前往你的放映廳。"],[59,"Staff will guide you if you need assistance.","如果需要協助,工作人員會為你引導。"],[76,"Snacks and drinks are available at the concession stand.","販賣部有賣零食和飲料。"],[93,"Turn off mobile devices before the movie begins to avoid disturbing others.","電影開始前請關掉手機,以免打擾別人。"],[111,"Late arrivals should enter quietly and find seats without blocking the screen or aisles.","遲到的觀眾應安靜進場,找座位時不要擋住螢幕或走道。"]]},
{"n":130,"adv":false,"v":"Em1cicNSTUE","s":[[17,"Sort your clothes properly first.","先把衣服好好分類。"],[30,"Load items into the washer carefully.","小心地把衣物放進洗衣機。"],[44,"Add detergent to the correct compartment.","把洗衣精加到正確的槽裡。"],[60,"Select the cycle based on fabric type and temperature.","依照布料種類和溫度選擇洗衣模式。"],[77,"Remove clothes promptly after the washing cycle fully ends.","洗衣程序完全結束後,立刻把衣服拿出來。"],[94,"Use the dryer and clean the lint filter before starting the machine safely.","使用烘衣機時,先清理棉絮過濾網再安全地啟動機器。"],[113,"Do not leave laundry unattended for long periods, to allow other users to use the machines.","不要把衣物長時間放著不管,讓其他人也能使用機器。"]]},
{"n":131,"adv":true,"v":"vyTXcD93iM8","s":[[25,"Resident assistants are available in the lobby if you have any questions.","如果有任何問題,大廳有宿舍輔導員可以協助。"],[44,"Smoking is strictly prohibited inside all dormitory buildings and common areas.","所有宿舍大樓和公共區域內嚴格禁止吸菸。"],[63,"Laundry facilities are located in the basement and are open 24 hours a day.","洗衣設施位於地下室,24 小時開放。"],[82,"Guests must be signed in at the front desk and must carry a visitor pass at all times.","訪客必須在櫃台登記,並隨時攜帶訪客證。"],[103,"The annual spring festival will feature live music, food trucks, and various student performances.","一年一度的春季節慶將有現場音樂、餐車和各種學生表演。"],[124,"If you plan to stay in the dorms during the winter break, you must notify the housing office by November.","如果你打算寒假期間留在宿舍,必須在十一月前通知住宿組。"],[145,"Due to the high demand for on-campus housing, students are encouraged to apply for a room as soon as they are admitted.","由於校內住宿需求很高,鼓勵學生一被錄取就立刻申請宿舍。"]]},
{"n":132,"adv":false,"v":"ORbK6CMsdn0","s":[[18,"Enter through the lobby.","從大廳進入。"],[31,"Sign in at the reception.","在櫃台簽到。"],[46,"Present your ID to security staff.","向保全人員出示你的身分證件。"],[64,"Wait until your access badge is issued.","等候你的通行證發放。"],[81,"Visitors must be escorted while inside the building.","訪客在大樓內必須有人陪同。"],[99,"Use the elevator only after receiving proper clearance from the front desk staff.","必須先得到櫃台人員的許可,才能使用電梯。"],[112,"Before leaving, return your badge and sign out at the main reception desk area downstairs.","離開前,到樓下的主櫃台歸還通行證並簽退。"]]},
{"n":133,"adv":false,"v":"Xi_oiCgw4Uo","s":[[18,"Keep your dog on a leash.","請替你的狗繫上牽繩。"],[31,"Enter through the gated dog park area.","從有門的狗公園區域進入。"],[46,"Remove the leash only in the off-leash zone.","只有在無牽繩區才能解開牽繩。"],[53,"Always carry waste bags to clean up after your pet.","隨時攜帶拾便袋,清理寵物的排泄物。"],[79,"Make sure your dog is vaccinated before entering the park.","進入公園前,確認你的狗已經打過疫苗。"],[97,"Monitor your dog's behavior to prevent conflicts with other animals nearby.","注意你的狗的行為,防止和附近其他動物起衝突。"],[117,"If your dog shows aggression, leave the area immediately to ensure safety for others.","如果你的狗出現攻擊行為,立刻離開該區,以確保其他人的安全。"]]},
{"n":134,"adv":false,"v":"4uF1wkFbWSA","s":[[17,"Please stand on the moving walkway.","請站在電動步道上。"],[30,"Hold the handrail to maintain your balance.","握住扶手以保持平衡。"],[46,"Stand on the right side unless you are walking.","除非你在走動,否則請站在右側。"],[63,"Keep your luggage close to avoid obstructing other passengers.","把行李放在身邊,以免妨礙其他乘客。"],[81,"Do not stop abruptly, as it may disrupt the steady movement of people behind you.","不要突然停下來,因為這可能會打亂後面的人穩定前進。"],[100,"Pay attention when entering or exiting to avoid losing balance and to step off safely.","上下步道時要注意,避免失去平衡並安全地走下來。"],[121,"If you are carrying large items, remain stationary and allow other passengers to pass safely on the left.","如果你帶著大型物品,請站著不動,讓其他乘客從左側安全通過。"]]},
{"n":135,"adv":false,"v":"S7lL9BF4CzU","s":[[17,"Schedule your appointment online.","在網路上預約。"],[31,"Select a preferred date and time.","選擇你想要的日期和時間。"],[46,"Check available time slots on the booking page.","在預約頁面查看可預約的時段。"],[63,"Enter your personal details to complete the reservation.","輸入你的個人資料以完成預約。"],[81,"You will receive a confirmation email with your appointment information.","你會收到一封附有預約資訊的確認信。"],[100,"If you need to make changes, update your appointment through the online system.","如果需要更改,請透過線上系統更新你的預約。"],[120,"Please arrive early and confirm your appointment at the front desk before your scheduled time.","請提早到達,並在預約時間前到櫃台確認你的預約。"]]},
{"n":136,"adv":true,"v":"_S6qRfCjiao","s":[[25,"Back up your research data regularly to prevent accidental loss.","定期備份你的研究資料,以免意外遺失。"],[42,"Carefully verify all experimental results before moving forward with your analysis.","進行分析之前,仔細核對所有的實驗結果。"],[61,"Use specialized software to perform accurate and reliable statistical analysis on your data.","使用專門的軟體,對你的資料進行準確可靠的統計分析。"],[82,"Make sure your findings are clearly and accurately documented for review and future reference.","確保你的研究發現被清楚準確地記錄下來,以供審查和日後參考。"],[102,"Submit your final manuscript on time for evaluation through the formal peer-review process.","準時提交最終稿件,以接受正式的同儕審查評估。"],[122,"Properly cite all external sources to avoid plagiarism and maintain academic integrity in your research work.","正確引用所有外部資料來源,以避免抄襲並維護研究的學術誠信。"],[144,"If you discover a significant error, inform your primary research adviser immediately before the final submission deadline.","如果發現重大錯誤,在最後繳交期限前立即通知你的主要指導教授。"]]},
{"n":137,"adv":false,"v":"JMoVQYtBRzI","s":[[17,"Do not enter this area.","請勿進入此區域。"],[24,"Authorized personnel only beyond this point.","此處以後僅限授權人員進入。"],[47,"Safety helmets must be worn inside the construction zone.","在施工區內必須戴安全帽。"],[66,"Warning signs indicate potential hazards in this restricted section.","警告標誌標示出這個管制區域內可能的危險。"],[83,"Visitors are not permitted unless accompanied by trained site staff.","除非有受過訓練的工地人員陪同,否則訪客不得進入。"],[103,"Heavy equipment may be operating nearby, so maintain a safe distance at all times.","附近可能有重型機具在運作,所以請隨時保持安全距離。"],[125,"Failure to follow these safety rules may result in removal from the site for your protection.","為了保護你的安全,不遵守這些安全規則可能會被請離工地。"]]},
{"n":138,"adv":false,"v":"CabeKKIn4_w","s":[[17,"Prepare your items for screening.","準備好你的物品接受安檢。"],[31,"Place bags on the conveyor belt.","把包包放在輸送帶上。"],[46,"Remove electronics from your carry-on luggage.","把電子產品從隨身行李中拿出來。"],[62,"Liquids must follow the required size and packaging limits.","液體必須符合規定的容量和包裝限制。"],[81,"Walk through the metal detector when instructed by security staff.","依照安檢人員的指示走過金屬探測門。"],[99,"If an alarm sounds, you may be asked to undergo additional screening procedures.","如果警報響起,你可能會被要求接受額外的檢查程序。"],[120,"After screening, collect your belongings promptly and move forward to avoid blocking the security line.","安檢後,迅速拿好你的物品往前走,以免擋住安檢隊伍。"]]},
{"n":139,"adv":false,"v":"pE5Jg3Ta8To","s":[[18,"Please follow the campus map.","請依照校園地圖走。"],[32,"A guided tour is available to new students.","新生可以參加導覽。"],[48,"The library offers quiet spaces for study and research.","圖書館提供安靜的空間讓人讀書和做研究。"],[65,"The student center includes dining areas and event spaces.","學生活動中心有用餐區和活動場地。"],[83,"Sports facilities can be used by students with valid campus access cards.","持有效校園門禁卡的學生可以使用運動設施。"],[102,"Academic buildings are open during regular class hours for enrolled students on weekdays.","教學大樓在平日正常上課時間開放給在學學生使用。"],[122,"If assistance is needed, campus staff can provide directions and information regarding facilities and services.","如果需要協助,校園工作人員可以提供路線指引,以及設施和服務的相關資訊。"]]},
{"n":140,"adv":false,"v":"DvKiCEi04vA","s":[[18,"Browse furniture in the showroom.","在展示間瀏覽家具。"],[32,"Staff are available for product information.","工作人員可以提供產品資訊。"],[48,"Check price tags and item details carefully.","仔細查看價格標籤和商品細節。"],[65,"Some items may require assembly after purchase at home.","有些商品買回家後可能需要自行組裝。"],[82,"Furniture can be tested for comfort before making a decision.","做決定前可以先試試家具是否舒適。"],[101,"Delivery options and scheduling can be arranged at the service desk.","可以在服務台安排配送方式和時間。"],[114,"Before checkout, confirm your order details and delivery address to avoid any issues later.","結帳前,確認你的訂單內容和送貨地址,以免日後發生問題。"]]},
{"n":141,"adv":true,"v":"hMrMXHJFN0s","s":[[25,"Browse the showroom displays to compare different furniture styles.","瀏覽展示間的陳列,比較不同的家具風格。"],[37,"Feel free to test furniture for comfort and stability to ensure it meets your needs.","歡迎試用家具的舒適度和穩固度,確保它符合你的需求。"],[64,"Ask staff about the detailed product dimensions and available customization options.","向工作人員詢問詳細的產品尺寸和可選擇的客製化選項。"],[85,"Some items may require assembly at home, so review the included instructions beforehand.","有些商品可能需要在家組裝,所以請事先閱讀附上的說明書。"],[106,"Delivery services and scheduling options can be arranged at the service desk based on your availability.","可以依照你方便的時間,在服務台安排配送服務和時間。"],[128,"Check price tags carefully and review item specifications before making a purchase decision in the store.","在店內決定購買前,仔細查看價格標籤並檢查商品規格。"],[141,"Before completing your purchase, confirm all order details, delivery arrangements, and warranty coverage to avoid future issues.","完成購買前,確認所有訂單細節、配送安排和保固範圍,以免日後發生問題。"]]},
{"n":142,"adv":false,"v":"FIvH456pIxY","s":[[17,"Payment details are entered securely.","付款資料會被安全地輸入。"],[32,"The transaction is processed through the system.","交易透過系統處理。"],[48,"A verification code is sent to your registered device.","驗證碼會傳送到你註冊的裝置。"],[66,"The code must be entered to confirm the payment.","必須輸入驗證碼才能確認付款。"],[84,"Additional checks may be required depending on the payment method used.","依照使用的付款方式,可能需要額外的驗證。"],[104,"A confirmation message is displayed once the transaction has been successfully verified.","交易驗證成功後會顯示確認訊息。"],[125,"If verification fails, the payment may be declined and the transaction must be reviewed again.","如果驗證失敗,付款可能會被拒絕,交易必須重新檢查。"]]},
{"n":143,"adv":false,"v":"4zgL7lPYuPU","s":[[17,"Clocks are adjusted this weekend.","這個週末要調整時鐘。"],[32,"The official time advances by one hour.","官方時間會往前調一個小時。"],[48,"Most digital devices update automatically during overnight system cycles.","大多數數位裝置會在夜間系統運作時自動更新。"],[68,"Certain analog clocks still require manual adjustment before sleep.","有些指針式時鐘仍需要在睡前手動調整。"],[90,"The shift produces longer daylight hours extending into the evening.","這項調整讓白天的時間變長,一直延續到傍晚。"],[109,"Individuals often experience mild fatigue while adapting to the revised schedule.","人們在適應調整後的作息時,常會感到輕微疲倦。"],[130,"Full adjustment may take several days as normal sleep patterns gradually stabilize under the new time.","完全適應可能需要好幾天,讓正常的睡眠模式在新時間下逐漸穩定。"]]},
{"n":144,"adv":false,"v":"o-o49IoGS18","s":[[17,"This trail starts near the visitor center.","這條步道從遊客中心附近開始。"],[32,"It passes through a quiet forest area.","它穿過一片安靜的森林。"],[49,"The ground includes uneven terrain and exposed roots.","地面有不平的地形和外露的樹根。"],[67,"Some parts of the trail have gradual elevation changes.","步道有些路段有緩慢的高度變化。"],[85,"Hikers should keep a steady pace during longer sections.","健行者在較長的路段應保持穩定的步伐。"],[105,"Weather and light conditions may affect visibility and trail safety.","天氣和光線狀況可能影響能見度和步道安全。"],[124,"Good preparation, including checking the route in time, helps ensure a safe and comfortable hike.","做好準備,包括及時確認路線,有助於確保健行安全又舒適。"]]},
{"n":145,"adv":false,"v":"PftlxqEYvzg","s":[[18,"This food court offers seating.","這個美食街有座位。"],[32,"Tables are available for all visitors.","所有訪客都可以使用桌子。"],[48,"Various food options are available nearby.","附近有各式各樣的餐點可以選擇。"],[66,"Seating near busy vendors fills quickly around mealtimes.","熱門攤位附近的座位在用餐時間很快就會坐滿。"],[85,"Tray return stations are located throughout the dining area.","整個用餐區都設有餐盤回收站。"],[104,"Cleaning staff regularly maintain the seating area to support overall cleanliness.","清潔人員定期整理座位區,以維持整體的清潔。"],[125,"Guests are encouraged to return trays after meals for easier cleaning and faster table turnover.","鼓勵客人用餐後歸還餐盤,方便清潔並加快座位的流動。"]]},
{"n":146,"adv":true,"v":"mpH9KOrlEz0","s":[[26,"Welcome to today's academic study workshop session.","歡迎參加今天的學術讀書工作坊。"],[45,"Please take a seat near the front of the classroom upon arrival.","抵達後請坐在教室前方。"],[63,"Workshop materials are available on each table for participants' convenience.","每張桌上都備有工作坊資料,方便參加者使用。"],[84,"The session will focus on effective note-taking strategies for academic lecture settings.","這堂課將著重於學術講課情境中有效的筆記策略。"],[105,"Group activities will be conducted following the introductory presentation and guided instructor explanation.","在開場簡報和講師的引導說明之後,將進行小組活動。"],[127,"If questions arise during the session, please save them for the designated discussion period at the end.","如果課程中有問題,請留到最後指定的討論時間再提出。"],[149,"Additional academic support resources and future workshop schedules are available through the student success website online for reference.","更多的學業輔導資源和未來的工作坊時間表,可以在學生成功中心的網站上查詢參考。"]]},
{"n":147,"adv":false,"v":"ATt5u7zLpIE","s":[[17,"Volunteers are needed for the festival.","這個節慶活動需要志工。"],[32,"Registration is available online.","可以在網路上報名。"],[48,"Name badges will be provided at check-in.","報到時會發放名牌。"],[65,"Volunteers may assist with guest directions and event setup.","志工可能會協助為來賓指路和布置活動場地。"],[84,"Comfortable footwear is recommended for long periods of standing.","因為需要長時間站立,建議穿舒適的鞋子。"],[104,"Food and beverages will be available during scheduled volunteer breaks.","在安排好的志工休息時間會提供餐點和飲料。"],[124,"Final instructions and shift assignments will be emailed to volunteers before the festival begins.","活動開始前,最後的說明和排班會以電子郵件寄給志工。"]]},
{"n":148,"adv":false,"v":"oyCSNTqoxjc","s":[[17,"A QR code is displayed nearby.","附近有展示一個 QR code。"],[32,"Open the camera on your device.","打開你裝置上的相機。"],[48,"Position the code within the screen frame.","把 QR code 對準在螢幕框框內。"],[65,"A link should appear after scanning successfully on your device.","成功掃描後,你的裝置上應該會出現一個連結。"],[86,"Tap the link to access additional information or related services.","點一下連結,取得更多資訊或相關服務。"],[106,"Some codes may direct users to registration forms or digital menus online.","有些 QR code 可能會把使用者帶到線上報名表或電子菜單。"],[127,"If scanning does not work, staff may provide assistance or offer an alternative access method.","如果掃描沒有作用,工作人員可以提供協助或其他的使用方式。"]]},
{"n":149,"adv":false,"v":"UaD0YQgv8Oo","s":[[18,"This area is for waiting guests.","這個區域是給等候的客人使用的。"],[32,"Seating is available on a first-come basis.","座位採先到先坐。"],[49,"Personal belongings should remain nearby at all times.","個人物品應隨時放在身邊。"],[67,"Quiet conversation is encouraged in shared waiting spaces.","在共用的等候空間請輕聲交談。"],[86,"Mobile devices should be used with headphones when possible.","使用行動裝置時請盡量戴耳機。"],[105,"Food and beverages may be restricted in certain waiting areas during busy service periods.","在忙碌的服務時段,某些等候區可能會限制飲食。"],[127,"Staff may provide regular updates if wait times become significantly longer than expected.","如果等候時間比預期長很多,工作人員可能會定期提供最新消息。"]]},
{"n":150,"adv":false,"v":"i_J4cOTrO4E","s":[[17,"This pharmacy provides health services.","這家藥局提供健康服務。"],[32,"Customers may speak with a licensed pharmacist.","顧客可以和有執照的藥師諮詢。"],[49,"Prescriptions are prepared based on doctor instructions.","處方藥依照醫師的指示調配。"],[67,"Wait times may vary depending on the number of orders.","等候時間可能因訂單數量而有所不同。"],[77,"Over-the-counter medications are available for common health needs.","店內有販售應付常見健康需求的成藥。"],[105,"Staff can provide guidance on proper dosage and safe medication use.","工作人員可以提供正確劑量和安全用藥的指導。"],[126,"If you have questions about your medication, the pharmacist can offer detailed information and support.","如果你對藥物有疑問,藥師可以提供詳細的資訊和協助。"]]},
{"n":151,"adv":true,"v":"9GyAhtmZlB0","s":[[26,"Terms and conditions apply to all services.","所有服務都適用條款與細則。"],[42,"Users are required to review the terms before proceeding.","使用者在繼續之前必須詳閱條款。"],[61,"Access to certain features may depend on agreement with the stated terms.","能否使用某些功能可能取決於是否同意所列的條款。"],[82,"The terms outline user responsibilities and limitations related to service usage.","條款說明了使用服務時使用者的責任和限制。"],[103,"Updates to the terms may occur periodically, and continued use indicates acceptance of these changes.","條款可能會定期更新,繼續使用即表示接受這些變更。"],[125,"Users are encouraged to read all sections carefully to understand their rights and obligations under the agreement.","鼓勵使用者仔細閱讀所有段落,以了解協議下自己的權利與義務。"],[148,"By continuing to use the service, users acknowledge that they have read, understood, and agreed to the terms and conditions.","繼續使用本服務,即表示使用者確認已閱讀、了解並同意條款與細則。"]]},
{"n":152,"adv":false,"v":"ZU59wlnMYM8","s":[[17,"Umbrella rental is available here.","這裡提供雨傘租借服務。"],[32,"Rentals can be requested at the front desk.","可以在櫃台申請租借。"],[48,"A small deposit may be required at checkout.","租借時可能需要支付少許押金。"],[66,"Umbrellas should be returned to the designated return point.","雨傘應歸還到指定的歸還處。"],[84,"Rental periods may vary depending on weather conditions and demand.","租借期限可能依天氣狀況和需求而有所不同。"],[103,"Damaged or lost umbrellas may result in additional charges based on rental policies.","依照租借規定,損壞或遺失雨傘可能需要支付額外費用。"],[124,"If you need assistance with your rental, staff can provide information and help process your return.","如果租借上需要協助,工作人員可以提供資訊並幫你辦理歸還。"]]},
{"n":153,"adv":false,"v":"7TohEF6huYg","s":[[17,"Maintenance requests can be submitted online.","維修申請可以在線上提出。"],[32,"A request form is available through the service portal.","申請表可以在服務入口網站取得。"],[48,"Photos may help staff understand the problem more quickly.","照片可以幫助工作人員更快了解問題。"],[66,"Provide clear details about the issue when completing the form.","填寫表單時,請清楚說明問題的細節。"],[85,"Urgent issues are usually handled first based on priority levels.","緊急問題通常會依照優先等級先處理。"],[103,"Response times may vary depending on the type of request submitted.","回應時間可能因提出的申請類型而有所不同。"],[123,"If the issue continues after repair, you may submit a follow-up request for further assistance.","如果修理後問題仍然存在,你可以再提出後續申請以獲得進一步協助。"]]},
{"n":154,"adv":false,"v":"rz868gd9g3o","s":[[17,"Visitor check-in is required.","訪客必須辦理登記。"],[30,"All visitors must sign in upon arrival.","所有訪客抵達時都必須簽到。"],[46,"Identification may be requested at the front desk.","櫃台可能會要求出示身分證件。"],[64,"A visitor badge will be issued after completing the check-in process.","完成登記後會發給訪客證。"],[82,"Visitors are expected to wear their badge while inside the building at all times.","訪客在大樓內應隨時配戴訪客證。"],[101,"Badges should be returned to the front desk before leaving the building after the visit.","參訪結束、離開大樓前,應將訪客證歸還櫃台。"],[121,"If a badge is lost, please inform staff so a replacement can be issued and recorded properly.","如果遺失訪客證,請通知工作人員,以便補發並妥善登記。"]]},
{"n":155,"adv":false,"v":"uoPHDQ5IUwY","s":[[17,"Elevator capacity is limited.","電梯的載客量有限。"],[31,"A maximum number of passengers is allowed.","電梯有乘客人數上限。"],[47,"Please follow posted signs indicating the safe capacity limit.","請遵守標示安全載客量的告示。"],[66,"Exceeding the limit may affect elevator performance and overall safety.","超過限制可能會影響電梯的運作和整體安全。"],[84,"During busy periods, passengers may need to wait for the next available elevator.","尖峰時段,乘客可能需要等下一班電梯。"],[104,"Large items or heavy loads may reduce the number of passengers allowed in each ride.","大型物品或重物可能會減少每趟可搭乘的人數。"],[125,"For safety reasons, all passengers should follow capacity guidelines and wait if the elevator is full.","為了安全,所有乘客都應遵守載客規定,電梯滿載時請等候。"]]},
{"n":156,"adv":false,"v":"-yABCVC7fv0","s":[[17,"Equipment safety is important.","設備安全很重要。"],[32,"Basic safety rules should be followed.","應遵守基本的安全規則。"],[47,"Protective gear is recommended when using certain equipment.","使用某些設備時建議穿戴防護裝備。"],[65,"Users should check equipment condition before beginning any task.","使用者開始任何工作前應檢查設備狀況。"],[75,"Improper use may result in damage to equipment or possible injury.","不當使用可能造成設備損壞或人員受傷。"],[102,"If any issue is noticed, users should report it to staff to ensure safe operation.","如果發現任何問題,使用者應通報工作人員,以確保安全運作。"],[124,"Safety instructions are provided to help users operate equipment correctly and avoid common risks.","我們提供安全說明,幫助使用者正確操作設備並避免常見的風險。"]]},
{"n":157,"adv":true,"v":"9hgxFxEH3w0","s":[[26,"This study involves voluntary research participation.","這項研究採自願參與。"],[43,"Participants must review the consent form before taking part.","參與者在參加前必須詳閱同意書。"],[62,"The form explains the purpose of the study and the procedures involved.","同意書說明研究的目的和相關程序。"],[82,"Participation is voluntary, and individuals may withdraw at any time without penalty.","參與完全自願,個人可隨時退出而不受任何處罰。"],[95,"Personal information collected during the study will be kept confidential and used only for research purposes.","研究期間收集的個人資料會被保密,且僅用於研究目的。"],[125,"Potential risks and benefits are described to help participants make an informed decision before agreeing to participate.","同意書說明可能的風險與好處,幫助參與者在同意參加前做出知情的決定。"],[148,"By signing the consent form, participants confirm that they understand the study procedures and agree to participate under the stated conditions.","簽署同意書即表示參與者確認了解研究程序,並同意在所述條件下參加。"]]},
{"n":158,"adv":false,"v":"fgZMNMqHnfQ","s":[[17,"Follow basic pool safety rules.","遵守基本的游泳池安全規則。"],[32,"Lifeguards are present during operating hours.","開放時間內都有救生員在場。"],[49,"Children should remain within designated shallow areas.","兒童應待在指定的淺水區內。"],[67,"Running is not allowed on wet surfaces around the pool deck.","泳池邊濕滑的地面上禁止奔跑。"],[85,"Swimmers should check depth markers before entering deeper sections.","游泳者進入較深區域前應先查看水深標示。"],[105,"Diving is only permitted in clearly marked areas with sufficient depth for safe entry.","只有在標示清楚、水深足以安全入水的區域才可以跳水。"],[126,"If you feel unwell or tired, leave the pool immediately and rest to avoid possible accidents.","如果感到不舒服或疲倦,請立刻離開泳池休息,以避免可能的意外。"]]},
{"n":159,"adv":false,"v":"OJ2ls8BkBcU","s":[[17,"Appointments may be cancelled.","預約可以取消。"],[32,"Cancellations can be made online or by phone.","可以透過網路或電話取消。"],[48,"Notice should be given before the scheduled appointment time.","應在預約時間之前事先通知。"],[65,"Late cancellations may result in a fee depending on the service.","太晚取消可能會依服務項目收取費用。"],[84,"Reminder messages may include cancellation and rescheduling details.","提醒訊息可能包含取消和改期的相關資訊。"],[104,"Rescheduling may be available if the request is made early enough.","如果夠早提出,或許可以改期。"],[124,"If no notice is given, the appointment may be marked as missed and affect future visits.","如果沒有事先通知,這次預約可能被記為未到,並影響日後的預約。"]]},
{"n":160,"adv":false,"v":"lm57J4jArkg","s":[[17,"Building access is controlled.","大樓的進出有管制。"],[32,"Entry is permitted through the main entrance.","只能從正門進入。"],[48,"All visitors must sign in upon arrival at reception.","所有訪客抵達時都必須在櫃台簽到。"],[66,"Access badges are required to enter restricted areas inside the building.","進入大樓內的管制區域需要門禁卡。"],[86,"Employees may use key cards to enter secure areas during regular working hours.","員工在正常上班時間可以用門禁卡進入安全區域。"],[105,"Security staff monitor entry points to ensure that only authorized individuals enter the building.","保全人員監控各出入口,確保只有經授權的人才能進入大樓。"],[128,"If access is denied, visitors should contact reception staff for assistance and further instructions.","如果無法進入,訪客應聯絡櫃台人員尋求協助和進一步指示。"]]},
{"n":161,"adv":false,"v":"HpdX5IBgMQk","s":[[17,"Turn off the light first.","先把燈關掉。"],[32,"Make sure the switch is completely off.","確認開關完全關閉。"],[48,"Wait a few minutes for the bulb to cool.","等幾分鐘讓燈泡冷卻。"],[64,"Carefully remove the burned-out bulb by twisting it left.","向左轉,小心地取下燒壞的燈泡。"],[83,"If the glass is broken, wear gloves to protect your hands.","如果玻璃破了,要戴手套保護雙手。"],[102,"Insert the new bulb gently and twist it to the right until secure.","輕輕裝上新燈泡,向右轉直到鎖緊。"],[123,"After replacing the bulb, restore power and check that the new light works properly.","換好燈泡後,恢復電源並確認新燈泡正常發亮。"]]},
{"n":162,"adv":false,"v":"TvMCMLiW2Ms","s":[[17,"Begin by unpacking all parts.","先把所有零件拆開包裝。"],[32,"Check that all pieces are included.","確認所有零件都齊全。"],[48,"Assembly instructions are provided in the package.","包裝裡附有組裝說明書。"],[67,"Identify each part before starting the assembly process.","開始組裝前先認出每一個零件。"],[86,"Use the correct tools when connecting parts to ensure a secure fit.","連接零件時使用正確的工具,確保接合牢固。"],[108,"Follow each step carefully to avoid mistakes and ensure proper alignment of all parts.","仔細依照每個步驟,避免出錯並確保所有零件正確對齊。"],[129,"If any part is missing or damaged, contact customer support to request a replacement part.","如果有任何零件缺少或損壞,請聯絡客服要求更換零件。"]]},
{"n":163,"adv":true,"v":"uhmPPWoP8hw","s":[[25,"Begin by carefully unpacking all components in a clean, organized workspace.","先在乾淨整齊的工作區小心拆開所有零件的包裝。"],[42,"Verify that every required piece and fastening tool is included before assembly begins.","開始組裝前,確認每個必要的零件和固定工具都齊全。"],[61,"Thoroughly review the enclosed instruction manual to understand each step before connecting any sections.","連接任何部分之前,徹底閱讀附上的說明書,了解每個步驟。"],[73,"Identify and categorize each individual component beforehand to reduce confusion during the assembly process.","事先辨認並分類每個零件,以減少組裝過程中的混亂。"],[103,"Use only the designated tools to secure each connection properly and maintain long-term structural stability.","只使用指定的工具把每個接合處固定好,以維持長期的結構穩定。"],[124,"Follow every instruction precisely to prevent misalignment, accidental damage, or assembly errors that may compromise durability.","精確遵照每個指示,避免可能影響耐用度的錯位、意外損壞或組裝錯誤。"],[148,"If any critical component is missing, defective, or damaged, immediately contact customer support for an appropriate replacement.","如果任何重要零件缺少、有瑕疵或損壞,請立即聯絡客服更換合適的零件。"]]},
{"n":164,"adv":false,"v":"nZRkUSkGCdE","s":[[17,"Check your vehicle regularly.","定期檢查你的車子。"],[32,"Make sure the tires have enough air.","確認輪胎的氣足夠。"],[47,"Change the oil when it becomes old or dirty.","機油變舊或變髒時就要更換。"],[53,"Inspect the brakes carefully to ensure they work properly.","仔細檢查煞車,確保它們正常運作。"],[83,"Keep the battery clean and check it for any signs of damage.","保持電瓶清潔,並檢查有沒有任何損壞的跡象。"],[102,"Refill essential fluids regularly to maintain smooth performance and prevent mechanical problems.","定期補充必要的油液,以維持順暢的性能並預防機械故障。"],[124,"Follow the recommended maintenance schedule to avoid costly repairs and keep your vehicle operating safely.","依照建議的保養時程,避免昂貴的維修費用,並讓車子安全運作。"]]},
{"n":165,"adv":false,"v":"urHr-j-u27w","s":[[17,"Choose soft yarn carefully first.","先仔細挑選柔軟的毛線。"],[32,"Select suitable knitting needles for your project.","為你的作品選擇合適的棒針。"],[48,"Begin by casting on your stitches carefully.","先小心地起針。"],[65,"Keep each row smooth and even while knitting.","編織時讓每一排都平順均勻。"],[82,"Check your scarf's length regularly as you continue working.","繼續編織時,定期檢查圍巾的長度。"],[101,"Fix any dropped stitches quickly to maintain a neat, consistent pattern.","快速修補任何漏針,保持整齊一致的花樣。"],[121,"Once your scarf is complete, bind off securely and carefully trim all remaining loose strands.","圍巾完成後,確實收針,並小心修剪所有剩下的線頭。"]]},
{"n":166,"adv":false,"v":"3rQfy2HLpuM","s":[[17,"Start with a small pot.","先準備一個小花盆。"],[32,"Fill it with fresh potting soil.","在裡面裝滿新的盆栽土。"],[48,"Place seeds evenly across the surface.","把種子均勻地撒在表面。"],[65,"Cover them lightly with a thin layer of soil.","在上面輕輕蓋一層薄薄的土。"],[83,"Water the soil gently to keep it moist but not too wet.","輕輕澆水,讓土壤保持濕潤但不要太濕。"],[103,"Place the pot in a sunny area where it can receive enough natural light.","把花盆放在陽光充足、能照到足夠自然光的地方。"],[124,"If the soil becomes dry, water the plant again to support steady and healthy growth.","如果土壤變乾,就再澆水,讓植物穩定健康地生長。"]]},
{"n":167,"adv":false,"v":"nax-BlJ4OTg","s":[[17,"Check the drill before use.","使用前先檢查電鑽。"],[31,"Select the correct drill bit.","選擇正確的鑽頭。"],[48,"Insert the bit securely into the chuck.","把鑽頭牢牢裝進夾頭裡。"],[65,"Hold the drill steady and position it at the desired point.","穩穩握住電鑽,對準想要鑽孔的位置。"],[83,"Apply gentle pressure while keeping the drill aligned with the surface.","輕輕施力,同時讓電鑽與表面保持對齊。"],[102,"Start at a low speed to maintain control and prevent slipping during drilling.","先用低速開始,以保持控制並防止鑽孔時打滑。"],[123,"If the drill becomes difficult to control, stop immediately and adjust your grip and positioning.","如果電鑽變得難以控制,立刻停下來,調整你的握法和位置。"]]},
{"n":168,"adv":false,"v":"xx5Knl7J1Dk","s":[[17,"Preheat the oven first.","先把烤箱預熱。"],[32,"Prepare all baking ingredients.","準備好所有烘焙材料。"],[48,"Mix the dry ingredients in a bowl.","把乾性材料放在碗裡混合。"],[65,"Add wet ingredients and stir until the dough forms.","加入濕性材料,攪拌到成為麵團。"],[84,"Scoop dough onto a baking sheet, leaving space between each piece.","把麵團舀到烤盤上,每塊之間留些空間。"],[102,"Bake the cookies until the edges turn golden and the centers remain soft.","把餅乾烤到邊緣金黃、中心仍然柔軟。"],[123,"Let the cookies cool slightly before serving to improve texture and prevent possible burns.","讓餅乾稍微放涼再吃,口感更好,也能避免燙傷。"]]},
{"n":169,"adv":true,"v":"NTB0Tj9q0gI","s":[[25,"Choose an appropriate desk area with enough space for comfortable work.","選一個空間足夠、能舒適工作的合適桌面區域。"],[44,"Clear the desk before beginning work to create a clean, organized environment.","開始工作前先清理桌面,營造乾淨整齊的環境。"],[64,"Arrange essential office supplies within easy reach for convenience and efficiency.","把必要的辦公用品放在伸手可及的地方,方便又有效率。"],[85,"Position your chair and monitor at a comfortable height to support posture and reduce strain.","把椅子和螢幕調到舒適的高度,以維持良好姿勢並減少疲勞。"],[106,"Place frequently used items nearby to improve efficiency and reduce unnecessary movement during tasks.","把常用物品放在附近,提高效率並減少工作時不必要的走動。"],[129,"Ensure proper lighting and screen placement to support focus and reduce eye strain throughout the workday.","確保照明和螢幕位置適當,幫助整個工作日保持專注並減少眼睛疲勞。"],[152,"If the workspace becomes disorganized, take time to reorganize items and maintain a clean and efficient office environment.","如果工作區變得雜亂,花時間重新整理物品,維持乾淨又有效率的辦公環境。"]]},
{"n":170,"adv":false,"v":"ewZ30VFd46k","s":[[17,"Go directly to the refund counter.","直接到退款櫃台。"],[32,"Bring your ticket and original receipt.","帶著你的票和原始收據。"],[48,"State the reason for your refund request.","說明你要求退款的原因。"],[65,"Present your documents politely to the staff member.","有禮貌地把文件交給工作人員。"],[84,"Wait patiently while the service agent reviews your request.","服務人員審核你的申請時,請耐心等候。"],[103,"Confirm the refund amount and payment method before completing the process.","完成程序前,確認退款金額和退款方式。"],[123,"Once approved, collect your refund receipt and verify all transaction details before leaving.","核准後,領取退款收據,並在離開前核對所有交易明細。"]]},
{"n":171,"adv":false,"v":"jzcJwZ_D5Vo","s":[[17,"Flat tires can happen unexpectedly.","爆胎可能會突然發生。"],[32,"Pull over safely when a tire loses air.","輪胎漏氣時,要安全地停到路邊。"],[48,"Activate hazard lights before exiting your vehicle.","下車前先打開警示燈。"],[53,"Inspect the damaged tire before gathering necessary tools.","拿必要的工具之前,先檢查受損的輪胎。"],[83,"Retrieve the spare and jack from storage inside the trunk.","從後車廂取出備胎和千斤頂。"],[102,"Loosen each lug nut before raising the car with proper support.","用適當的支撐把車子頂起來之前,先把每顆輪胎螺帽轉鬆。"],[121,"Once replacement is complete, visit a nearby mechanic for professional inspection and permanent repair.","換好輪胎後,到附近的修車廠做專業檢查和永久修理。"]]},
{"n":172,"adv":false,"v":"xonP6d8XbC0","s":[[18,"Gather all your dirty clothes.","把所有髒衣服集中起來。"],[32,"Sort laundry by color and garment type.","依照顏色和衣服種類把要洗的衣物分類。"],[48,"Check clothing labels carefully for washing instructions.","仔細查看衣服標籤上的洗滌說明。"],[66,"Place the sorted clothes evenly inside the washing machine.","把分類好的衣服平均放進洗衣機裡。"],[84,"Add detergent to the designated compartment before starting the cycle.","開始洗衣前,把洗衣精加進指定的槽裡。"],[104,"Select the appropriate cycle based on fabric type and clothing condition.","依照布料種類和衣服狀況選擇合適的洗衣模式。"],[125,"Once the cycle finishes, remove clothes promptly to reduce wrinkles and prevent unpleasant odors.","洗完後立刻把衣服拿出來,以減少皺褶並防止產生異味。"]]},
{"n":173,"adv":false,"v":"zIlayezN6Mc","s":[[17,"Locate your smoke alarm first.","先找到你的煙霧警報器。"],[31,"Stand safely beneath the device.","安全地站在警報器下方。"],[45,"Press the test button firmly once.","用力按一次測試鈕。"],[63,"Listen carefully for the alarm sound afterward.","接著仔細聽警報聲。"],[80,"Replace old batteries immediately if no sound occurs.","如果沒有聲音,立刻更換舊電池。"],[98,"Clean the unit regularly to prevent dust buildup and maintain reliable performance.","定期清潔警報器,防止灰塵堆積並維持可靠的性能。"],[118,"Test every smoke alarm monthly to ensure your home remains protected during unexpected emergencies.","每個月測試每一個煙霧警報器,確保家裡在突發緊急狀況時仍受到保護。"]]},
{"n":174,"adv":false,"v":"Ji2GHgnFvWE","s":[[17,"Choose a safe fire pit.","選一個安全的火坑。"],[32,"Clear dry leaves and branches nearby.","清除附近的乾葉和樹枝。"],[49,"Gather small sticks and tinder materials.","收集小樹枝和引火材料。"],[66,"Arrange the materials carefully in the pit.","小心地把材料擺放在火坑裡。"],[84,"Light the tinder gently and watch the flame grow.","輕輕點燃引火物,看著火焰慢慢變大。"],[102,"Add larger pieces gradually to build a steady, controlled fire.","逐漸加入較大的木柴,升起穩定且受控制的火。"],[115,"Before leaving the campsite, extinguish the fire completely with water and confirm that no heat remains.","離開營地前,用水把火完全熄滅,並確認沒有任何餘熱。"]]},
{"n":175,"adv":true,"v":"KwpftS6P0ao","s":[[26,"Skies will remain mostly clear throughout the morning.","整個上午天空大致晴朗。"],[45,"Temperatures are expected to rise slightly during the early afternoon.","預計午後初段氣溫會稍微上升。"],[65,"Light winds may develop later in the day across the southern regions.","南部地區稍晚可能會吹起微風。"],[86,"A brief chance of rain is possible in the evening depending on cloud movement.","視雲層移動情況,傍晚可能會有短暫降雨。"],[108,"Humidity levels will gradually increase, which may make the air feel warmer than the actual temperature.","濕度會逐漸升高,可能讓空氣感覺比實際氣溫更熱。"],[131,"Weather conditions are expected to remain stable overnight, with cooler temperatures developing after sunset in most regions.","預計夜間天氣狀況維持穩定,大部分地區日落後氣溫會轉涼。"],[155,"Although conditions will remain mostly stable throughout the day, sudden temperature drops may occur after sunset in some local areas.","雖然全天的天氣大致穩定,但部分地區日落後可能會突然降溫。"]]},
{"n":176,"adv":false,"v":"o-OVopJdJeA","s":[[17,"Choose a sunny garden spot.","選一個陽光充足的花園位置。"],[31,"Clear weeds and rocks completely.","把雜草和石頭完全清除。"],[47,"Loosen the soil carefully.","小心地把土壤翻鬆。"],[65,"Dig small planting holes for each plant.","為每株植物挖小小的種植洞。"],[83,"Place the seeds gently into prepared spaces.","把種子輕輕放進準備好的位置。"],[102,"Cover everything lightly with soil and water the area thoroughly.","輕輕蓋上一層土,並把整個區域徹底澆濕。"],[123,"Check your garden regularly by watering plants, removing weeds, and watching for healthy growth.","定期照顧你的花園:澆水、除草,並觀察植物是否健康生長。"]]},
{"n":177,"adv":false,"v":"Lc-uu7nYFi8","s":[[17,"Set up the ironing board.","架好燙衣板。"],[30,"Plug in the iron carefully first.","先小心地把熨斗插上電。"],[44,"Adjust the heat setting for the fabric.","依照布料調整溫度設定。"],[51,"Smooth each garment completely before ironing.","燙衣服之前先把每件衣服完全攤平。"],[79,"Press slowly to remove wrinkles evenly throughout.","慢慢地燙,把整件衣服的皺褶平均燙平。"],[97,"Use steam when necessary to improve results on stubborn areas.","必要時使用蒸氣,讓難燙的地方效果更好。"],[118,"After finishing, unplug the iron safely and allow it to cool completely before storage.","燙完後,安全地拔掉熨斗插頭,讓它完全冷卻後再收起來。"]]},
{"n":178,"adv":false,"v":"M2Hur7qHC8E","s":[[17,"Observe posted noise limits.","遵守公告的噪音限制。"],[32,"Lower your volume promptly when necessary.","必要時立刻降低音量。"],[48,"Avoid shouting excessively in shared spaces.","避免在共用空間大聲喊叫。"],[66,"Use headphones for personal audio devices.","使用個人音響裝置時請戴耳機。"],[77,"Respect established quiet hours in designated areas.","在指定區域遵守規定的安靜時段。"],[104,"Minimize unnecessary noise to maintain comfort for everyone nearby.","盡量減少不必要的噪音,讓附近的每個人都感到舒適。"],[125,"Follow all noise regulations carefully to support a peaceful environment and prevent possible complaints.","仔細遵守所有噪音規定,維護安寧的環境並避免可能的投訴。"]]},
{"n":179,"adv":false,"v":"RM_Yhfe4prM","s":[[17,"Inspect your bicycle regularly.","定期檢查你的腳踏車。"],[32,"Check the tire pressure carefully.","仔細檢查胎壓。"],[48,"Clean the chain with proper supplies.","用合適的用品清潔鏈條。"],[66,"Adjust the brakes before riding outdoors.","到戶外騎車前先調整煞車。"],[82,"Tighten any loose parts to improve overall safety.","鎖緊任何鬆動的零件,以提升整體安全。"],[102,"Lubricate moving components regularly to maintain smooth performance and reduce unnecessary wear.","定期為活動零件上油,維持順暢的性能並減少不必要的磨損。"],[115,"Before every ride, examine the bicycle thoroughly to ensure all equipment functions safely and efficiently.","每次騎車前,徹底檢查腳踏車,確保所有裝置都安全且有效地運作。"]]},
{"n":180,"adv":false,"v":"OJJPWFQLmY0","s":[[17,"Arrive at the cooking class early.","提早到烹飪教室。"],[32,"Wash your hands before preparing ingredients.","準備食材之前先洗手。"],[49,"Read the recipe instructions carefully first.","先仔細閱讀食譜說明。"],[67,"Organize your tools before starting the lesson.","上課開始前先整理好你的工具。"],[85,"Measure ingredients accurately to improve consistency and flavor.","精確測量食材,讓成品更一致、風味更好。"],[106,"Follow the chef's guidance carefully while preparing each part of the dish.","準備料理的每個部分時,仔細遵照主廚的指導。"],[127,"After completing the recipe, clean your workstation thoroughly and store all equipment in the proper place.","完成料理後,把你的工作檯徹底清乾淨,並把所有器具放回原位。"]]},
{"n":181,"adv":true,"v":"9fuFJdak8aE","s":[[26,"Visit the Student Success Center to access academic guidance and useful campus resources.","前往學生成功中心,取得學業輔導和實用的校園資源。"],[47,"Schedule an appointment early to discuss coursework and study strategies for educational goals.","及早預約,討論課業以及達成學習目標的讀書策略。"],[60,"Prepare documents beforehand so advisers can review your academic progress more efficiently.","事先準備好文件,讓輔導老師能更有效率地檢視你的學業進度。"],[91,"Participate actively in workshops that strengthen time management skills and improve overall academic performance.","積極參加能加強時間管理能力、提升整體學業表現的工作坊。"],[114,"Consult experienced staff regularly to receive helpful feedback and solutions for recurring academic difficulties.","定期請教有經驗的工作人員,針對反覆出現的學業困難取得有用的建議和解決方法。"],[137,"Take advantage of tutoring services and career counseling programs to build confidence and support long-term achievement.","善用課業輔導服務和職涯諮詢計畫,建立自信並支持長期的成就。"],[160,"By using available resources consistently, students can improve academic performance and develop stronger habits for future success.","持續運用現有資源,學生就能提升學業表現,並培養有助於未來成功的良好習慣。"]]},
{"n":182,"adv":false,"v":"Q4kjDyne5Ns","s":[[18,"Open the account login page.","打開帳號登入頁面。"],[31,"Select the password reset option.","選擇重設密碼的選項。"],[47,"Enter your registered email address correctly.","正確輸入你註冊的電子郵件地址。"],[64,"Check your inbox for the verification message.","到收件匣查看驗證信。"],[83,"Follow the provided link to create a new password securely.","點選提供的連結,安全地建立新密碼。"],[102,"Choose a strong password containing letters, numbers, and symbols for better protection.","選擇包含字母、數字和符號的強密碼,以獲得更好的保護。"],[124,"After updating your information, sign in again to confirm that your new password works properly.","更新資料後,再登入一次,確認新密碼可以正常使用。"]]},
{"n":183,"adv":false,"v":"XlFnRYm3ySc","s":[[17,"Remove large food pieces first.","先清掉大塊的食物殘渣。"],[32,"Open the dishwasher door carefully.","小心打開洗碗機的門。"],[48,"Place plates securely in the lower rack.","把盤子穩穩地放在下層架上。"],[64,"Arrange cups and glasses in the upper section.","把杯子和玻璃杯排在上層。"],[82,"Keep utensils separated to improve cleaning performance and organization.","把餐具分開放,清洗效果更好也更整齊。"],[103,"Add dishwasher detergent before selecting the appropriate washing cycle for the load.","先加入洗碗機清潔劑,再依照碗盤量選擇合適的清洗模式。"],[124,"After the cycle finishes completely, unload clean dishes and store everything in the proper place.","清洗程序完全結束後,取出乾淨的碗盤,並把所有東西收回原位。"]]},
{"n":184,"adv":false,"v":"mVzKr2hesp4","s":[[17,"Fill the coffee maker with water.","把咖啡機加滿水。"],[31,"Add fresh coffee grounds carefully.","小心加入新鮮的咖啡粉。"],[47,"Place the paper filter into the machine properly.","把濾紙正確地放進機器裡。"],[65,"Press the start button to begin the brewing process.","按下開始鍵開始沖煮。"],[83,"Wait patiently while the coffee brews completely inside the machine.","耐心等待咖啡在機器裡完全煮好。"],[103,"Pour the freshly brewed coffee slowly into a clean mug before serving.","把剛煮好的咖啡慢慢倒進乾淨的馬克杯再享用。"],[122,"After drinking, clean the machine properly to maintain flavor and prevent residue buildup.","喝完後,好好清潔機器,以保持風味並防止殘留物堆積。"]]},
{"n":185,"adv":false,"v":"GRDttbH4HI0","s":[[17,"Choose the correct screwdriver.","選擇正確的螺絲起子。"],[32,"Match the tip to the screw head.","讓起子頭和螺絲頭的形狀吻合。"],[47,"Place the tip firmly before turning the screw.","轉動螺絲之前,先把起子頭穩穩地抵住。"],[66,"Hold the handle steadily while keeping the tool aligned.","穩穩握住握把,並讓工具保持對齊。"],[85,"Turn the screwdriver slowly to tighten or loosen the screw without slipping.","慢慢轉動螺絲起子來鎖緊或鬆開螺絲,不要打滑。"],[105,"Apply steady pressure throughout use to maintain control and prevent surface damage.","使用時持續施加穩定的力道,以保持控制並避免表面損傷。"],[127,"If the screw does not move easily, stop and check alignment to avoid stripping the screw head.","如果螺絲轉不太動,先停下來檢查是否對齊,以免把螺絲頭轉花。"]]},
{"n":186,"adv":false,"v":"9DWXo9tUEtY","s":[[17,"Place the router near your computer.","把路由器放在電腦附近。"],[32,"Connect the modem using the correct cable.","用正確的線連接數據機。"],[49,"Turn on the equipment and wait several minutes.","打開設備並等候幾分鐘。"],[65,"Check the indicator lights before opening the network settings.","打開網路設定之前先檢查指示燈。"],[85,"Position the router carefully to improve signal strength throughout your home.","仔細擺放路由器的位置,讓整個家裡的訊號更強。"],[104,"Create a secure password to protect your wireless connection from unauthorized access.","設定安全的密碼,保護你的無線網路不被未經授權的人使用。"],[126,"After setup is complete, test the connection on multiple devices to confirm stable internet access.","設定完成後,在多台裝置上測試連線,確認網路連線穩定。"]]},
{"n":187,"adv":true,"v":"QZxoriSCar8","s":[[26,"Place the router near your workspace for stronger and more reliable wireless coverage.","把路由器放在你的工作區附近,讓無線網路的覆蓋更強、更穩定。"],[47,"Connect the modem properly before turning on the networking equipment for initial configuration.","開啟網路設備進行初始設定之前,先把數據機正確連接好。"],[68,"Verify that all indicator lights function normally before attempting to access the wireless connection settings.","嘗試進入無線連線設定之前,確認所有指示燈都正常運作。"],[91,"Create a secure network password containing letters, numbers, and symbols to improve overall protection.","建立包含字母、數字和符號的安全網路密碼,以提升整體防護。"],[104,"Access the router settings carefully through a web browser to customize security preferences and connection details.","透過網頁瀏覽器小心進入路由器設定,自訂安全偏好和連線細節。"],[138,"Position the equipment strategically to minimize signal interference from nearby electronics, walls, or large metal surfaces.","有策略地擺放設備,將附近電子產品、牆壁或大型金屬表面造成的訊號干擾降到最低。"],[163,"After completing the configuration process, restart all connected devices and confirm that the wireless network operates consistently and securely.","完成設定後,重新啟動所有連線的裝置,並確認無線網路穩定又安全地運作。"]]},
{"n":188,"adv":false,"v":"1r0mo3h91v8","s":[[18,"Trim all stems at an angle.","把所有花莖斜剪。"],[33,"Place the cut flowers in fresh water immediately.","立刻把剪好的花放進乾淨的水裡。"],[51,"Remove any leaves that fall below the waterline.","摘掉所有會泡到水的葉子。"],[68,"Select blooms in complementary colors to create visual balance.","挑選顏色互補的花朵,營造視覺上的平衡。"],[88,"Position taller stems in the center and shorter ones around the outside.","把較高的花放在中間,較矮的放在外圍。"],[109,"Follow the instructor's guidance on stem angles and spacing to improve your arrangement.","依照老師對花莖角度和間距的指導,改善你的插花作品。"],[131,"After finishing the arrangement, rinse your tools and store the vases away from sunlight.","插完花後,把工具沖洗乾淨,並把花瓶放在避開陽光的地方。"]]},
{"n":189,"adv":false,"v":"dWQmDOGpMV8","s":[[18,"Wear an apron before starting.","開始之前先穿上圍裙。"],[32,"Wedge the clay firmly on the table.","在桌上用力揉黏土。"],[48,"Center the clay carefully on the spinning wheel.","小心地把黏土放在轉動的拉坯機正中央。"],[66,"Use both hands to open the clay from the middle.","用雙手從中間把黏土打開。"],[84,"Apply steady pressure with your fingers to shape the walls evenly.","用手指施加穩定的力道,把坯壁塑造得均勻。"],[104,"Follow the instructor's guidance on pulling the clay upward to build height.","依照老師的指導把黏土往上拉高。"],[124,"After finishing your piece, clean the wheel and store unused clay in a sealed container.","完成作品後,清理拉坯機,並把沒用完的黏土存放在密封容器裡。"]]},
{"n":190,"adv":false,"v":"o2v40YrCJm0","s":[[17,"Boil water in a large pot.","在大鍋子裡把水煮滾。"],[33,"Add a pinch of salt to the water.","在水裡加一小撮鹽。"],[49,"Stir the pasta gently after placing it in the pot.","把義大利麵放進鍋子後輕輕攪拌。"],[67,"Check the package instructions for the recommended cooking time.","查看包裝上的說明,了解建議的烹煮時間。"],[87,"Drain the pasta carefully once it reaches your desired texture.","麵煮到你想要的口感後,小心地把水瀝乾。"],[107,"Toss the cooked pasta with your sauce immediately to prevent the noodles from sticking.","立刻把煮好的麵和醬汁拌勻,以免麵條黏在一起。"],[128,"After plating your dish, turn off the stove and wipe down the cooking area with a clean cloth.","裝盤後關掉爐火,用乾淨的布擦拭烹飪區。"]]},
{"n":191,"adv":false,"v":"85J-W_txadQ","s":[[17,"Arrive at the tea room quietly and respectfully.","安靜且恭敬地進入茶室。"],[33,"Sit calmly and wait for the host to begin.","安靜坐好,等待主人開始。"],[49,"Place the tea bowl gently in front of you with both hands.","用雙手輕輕把茶碗放在你面前。"],[67,"Watch the host carefully as they scoop the powdered tea into the bowl.","仔細看主人把抹茶粉舀進碗裡。"],[86,"Pour the hot water slowly and steadily over the tea powder using the ladle.","用杓子把熱水慢慢、穩穩地倒在茶粉上。"],[106,"Whisk the tea in a quick zigzag motion until a smooth and even foam appears.","用快速的 Z 字形動作刷茶,直到出現細緻均勻的泡沫。"],[127,"After drinking, turn the bowl twice in your hands and place it quietly back on the mat.","喝完後,在手中把茶碗轉兩次,再安靜地放回墊子上。"]]},
{"n":192,"adv":false,"v":"ncB-dzz2VjY","s":[[17,"Please handle the camera gently.","請小心使用相機。"],[32,"Load the film in complete darkness.","在全黑的環境中裝底片。"],[49,"Advance the film carefully after each shot.","每拍完一張,小心地把底片往前捲。"],[67,"Set the correct ISO before shooting in different lighting.","在不同光線下拍攝前,先設定正確的 ISO。"],[85,"Look through the viewfinder and frame your subject before shooting.","拍照前從觀景窗看出去,把主體放進畫面裡構圖。"],[105,"Adjust the aperture and shutter speed based on the available light conditions.","依照現場的光線條件調整光圈和快門速度。"],[125,"After finishing the roll, rewind the film fully and remove it before opening the back cover.","拍完一整捲後,先把底片完全捲回去,再打開後蓋取出。"]]},
{"n":193,"adv":true,"v":"Zes284S1XFY","s":[[27,"Ensure your hands are completely clean before handling any camera equipment.","拿任何相機器材之前,確保你的手完全乾淨。"],[44,"Keep the camera away from direct sunlight to protect the internal mechanics.","讓相機避開陽光直射,以保護內部機件。"],[62,"Load the film roll in total darkness to prevent any accidental light exposure.","在全黑的環境中裝底片,以免意外曝光。"],[82,"Adjust the ISO setting on your camera to match the film speed on the box.","把相機的 ISO 設定調到和底片盒上的感光度一致。"],[101,"Look through the viewfinder and confirm your composition is balanced before pressing the shutter release.","按下快門之前,從觀景窗確認你的構圖是平衡的。"],[123,"Study the relationship between aperture and shutter speed to achieve proper exposure in any lighting situation.","研究光圈和快門速度的關係,讓你在任何光線下都能得到正確的曝光。"],[145,"Once the roll is finished, rewind the film fully inside the camera before carefully opening the back and removing it.","一捲拍完後,先在相機內把底片完全捲回,再小心打開後蓋取出。"]]},
{"n":194,"adv":false,"v":"j4itux31K_s","s":[[18,"Wear safety goggles before starting.","開始之前先戴上護目鏡。"],[32,"Measure the wood twice before making any cuts.","鋸木頭之前先量兩次。"],[49,"Sand the surface evenly to remove any rough edges.","把表面均勻磨砂,去除粗糙的邊緣。"],[67,"Secure the wood firmly in place before using any tool.","使用任何工具前,先把木頭牢牢固定。"],[85,"Choose the correct saw blade depending on the type of cut needed.","依照需要的切割方式選擇正確的鋸片。"],[105,"Apply wood glue evenly along the joint and press both pieces together firmly.","在接合處均勻塗上木工膠,把兩塊木頭用力壓緊。"],[127,"After finishing your piece, sweep away all sawdust and store your tools in their proper place.","完成作品後,把木屑掃乾淨,並把工具放回原位。"]]},
{"n":195,"adv":false,"v":"TwEclReXmFo","s":[[18,"Remove the valve cap first.","先拿掉氣嘴蓋。"],[32,"Press the gauge onto the valve stem.","把胎壓計壓在氣嘴上。"],[48,"Read the pressure level on the gauge display.","讀出胎壓計上顯示的胎壓。"],[65,"Compare the reading against the recommended pressure level.","把讀數和建議的胎壓比較。"],[83,"Add air slowly until you reach the correct pressure setting.","慢慢打氣,直到達到正確的胎壓。"],[101,"Release a small amount of air if the tire pressure reads too high.","如果胎壓太高,就放掉一點氣。"],[122,"After checking all four tires, secure each valve cap and record the pressure readings.","檢查完四個輪胎後,把每個氣嘴蓋鎖好,並記下胎壓讀數。"]]},
{"n":196,"adv":false,"v":"k9oWtkz0io8","s":[[18,"Arrange your tools neatly before starting.","開始之前先把工具排好。"],[33,"Slice the lemons carefully on a clean cutting board.","在乾淨的砧板上小心地切檸檬。"],[49,"Squeeze the fresh lemons into a large pitcher slowly.","把新鮮檸檬慢慢擠進一個大水壺裡。"],[67,"Add water, sugar, and ice in the correct amounts.","加入適量的水、糖和冰塊。"],[86,"Stir the mixture thoroughly for several seconds to combine the flavors evenly.","把混合物充分攪拌幾秒鐘,讓味道均勻融合。"],[106,"Pour the lemonade slowly into chilled glasses to ensure a smooth and consistent serving process.","把檸檬汁慢慢倒進冰過的杯子,讓倒飲料的過程平順穩定。"],[128,"After serving the lemonade, rinse the pitcher and utensils to prevent residue from building up.","端上檸檬汁後,把水壺和器具沖洗乾淨,避免殘留物堆積。"]]},
{"n":197,"adv":false,"v":"MvxhlmYgdU8","s":[[17,"Cut the wrapping paper to the right size.","把包裝紙裁成適當的大小。"],[33,"Place the gift face down in the center.","把禮物正面朝下放在中間。"],[49,"Fold the paper neatly over each side of the box.","把紙整齊地摺過盒子的每一面。"],[67,"Crease the edges firmly to keep the folds in place.","把邊緣用力壓出摺痕,讓摺好的地方固定住。"],[85,"Secure each fold with a small piece of clear tape.","用一小段透明膠帶固定每個摺邊。"],[96,"Attach a ribbon along the center and fasten it neatly with a knot.","沿著中間綁上緞帶,並整齊地打個結固定。"],[124,"After finishing, attach a gift tag with a short personal message for the recipient.","完成後,貼上一張寫著給收禮者簡短祝福的禮物卡。"]]},
{"n":198,"adv":false,"v":"4NJJrWpfGQE","s":[[17,"Lay a drop cloth along the base of the wall.","沿著牆腳鋪上防塵布。"],[33,"Apply masking tape along the edges and corners carefully.","小心地沿著邊緣和角落貼上紙膠帶。"],[50,"Stir the paint smoothly before pouring it into the tray.","把油漆倒進漆盤前先攪拌均勻。"],[68,"Roll the paint evenly across the wall in a steady upward motion.","用穩定的向上動作把油漆均勻滾在牆上。"],[88,"Work in small sections to maintain a consistent and even coat.","分成小區塊進行,讓漆面保持一致又均勻。"],[108,"Allow the first coat to dry completely before applying a second layer.","等第一層完全乾了之後,再上第二層。"],[129,"Once the paint has dried, peel off the masking tape and clean all painting tools thoroughly.","油漆乾了以後,撕掉紙膠帶,並把所有油漆工具徹底清洗乾淨。"]]},
{"n":199,"adv":false,"v":"Pjcykm9aKxQ","s":[[17,"Lay the tent flat on even ground.","把帳篷平鋪在平坦的地面上。"],[33,"Spread the ground sheet out before assembling anything.","組裝任何東西之前,先把地布攤開。"],[50,"Slide the poles through the designated sleeves carefully.","小心地把營柱穿過指定的套管。"],[68,"Push each pole end into the correct corner eyelet.","把每根營柱的末端插進正確的角落扣環。"],[87,"Pull the tent fabric taut to avoid any sagging or pooling.","把帳篷布拉緊,避免下垂或積水。"],[107,"Secure all the guy ropes and pegs firmly into the ground below.","把所有營繩和營釘牢牢固定在地面上。"],[128,"After setting up, check every connection point and adjust the tension for a stable shelter.","搭好之後,檢查每個連接點並調整拉力,讓帳篷穩固。"]]},
{"n":200,"adv":true,"v":"KpMuqkSTNpM","s":[[26,"Choose a flat and sheltered spot away from any uneven or rocky terrain.","選一個平坦又有遮蔽的地點,遠離不平或多石的地形。"],[46,"Clear the ground of sharp objects before laying down the ground sheet.","鋪地布之前,先清除地上的尖銳物品。"],[67,"Thread the poles carefully through each designated sleeve without bending or forcing them.","小心地把營柱穿過每個指定的套管,不要彎折或硬塞。"],[89,"Secure the pole ends firmly into the corner eyelets to give the tent its full structure.","把營柱末端牢牢固定在角落扣環上,讓帳篷撐出完整的結構。"],[111,"Pull the outer fabric evenly from all sides to eliminate any sagging or loose areas.","從各個方向平均拉緊外帳,消除下垂或鬆垮的地方。"],[133,"Hammer the pegs into the ground at an outward angle to maximize tension and stability.","把營釘以向外傾斜的角度敲進地面,讓拉力和穩定度達到最大。"],[155,"Once fully assembled, walk around the tent and adjust every guy rope until the structure feels completely secure and weatherproof.","完全搭好後,繞帳篷走一圈,調整每條營繩,直到整個結構完全穩固又能防風雨。"]]},
{"n":201,"adv":false,"v":"5kKyp0Ca42U","s":[[18,"Place the cooled cake on a turntable.","把放涼的蛋糕放在轉台上。"],[32,"Prepare the frosting before decorating.","裝飾之前先準備好糖霜。"],[49,"Spread a thin layer evenly across the surface.","在表面均勻抹上一層薄薄的糖霜。"],[66,"Smooth the sides carefully using an icing scraper.","用抹刀小心地把側面抹平。"],[85,"Add decorative borders around the edges for a polished appearance.","在邊緣加上裝飾花邊,讓外觀更精緻。"],[103,"Pipe designs steadily to create consistent patterns and improve the overall presentation.","穩穩地擠出圖案,做出一致的花樣並提升整體的呈現。"],[125,"Once decorating is complete, refrigerate the cake briefly to help the frosting set properly.","裝飾完成後,把蛋糕冷藏一下,讓糖霜好好定型。"]]},
{"n":202,"adv":false,"v":"SbKTwG8UUsA","s":[[17,"Arrive early in comfortable practice attire.","穿著舒適的練習服提早到。"],[33,"Stretch your muscles thoroughly before beginning practice.","開始練習前充分伸展肌肉。"],[50,"Watch the instructor demonstrate the routine carefully.","仔細看老師示範整套動作。"],[68,"Learn each movement slowly before increasing speed and intensity.","先慢慢學會每個動作,再加快速度和強度。"],[87,"Practice the sequence repeatedly to improve timing and coordination.","反覆練習整套動作,提升節拍感和協調性。"],[107,"Focus on transitions between movements to create a smoother and more polished performance.","專注在動作之間的轉換,讓表演更流暢、更完美。"],[129,"At the end of class, perform the complete routine while maintaining consistent rhythm and proper technique.","下課前,保持一致的節奏和正確的技巧,完整表演整套動作。"]]},
{"n":203,"adv":false,"v":"DxZfEu9-5Po","s":[[17,"Approach the vending machine prepared to choose.","走到自動販賣機前準備選購。"],[33,"Review the available items carefully before choosing.","選擇之前仔細看看有哪些商品。"],[51,"Choose the product that best matches your preference.","選擇最符合你喜好的商品。"],[69,"Enter the corresponding number on the keypad correctly.","在按鍵上正確輸入對應的號碼。"],[88,"Insert your payment and wait for the transaction to process successfully.","投入付款,等待交易順利完成。"],[108,"Confirm your selection before completing the purchase to avoid ordering the wrong item.","完成購買前確認你的選擇,以免買錯商品。"],[130,"Once the product is dispensed, collect your item and any change before leaving the machine.","商品掉出來後,拿好你的東西和找的零錢再離開販賣機。"]]},
{"n":204,"adv":false,"v":"gwNCzfq_0TY","s":[[17,"Locate the battery compartment first.","先找到電池盒。"],[33,"Turn off the device before opening the cover.","打開蓋子前先把裝置關機。"],[49,"Remove the battery cover carefully without forcing it.","小心取下電池蓋,不要硬扳。"],[67,"Take out the old batteries and inspect the interior for corrosion.","取出舊電池,並檢查內部有沒有腐蝕。"],[86,"Insert the new batteries according to the indicated polarity markings.","依照標示的正負極放入新電池。"],[106,"Secure the cover properly to ensure the batteries remain in position during use.","把蓋子蓋好,確保使用時電池固定不動。"],[128,"After replacement is complete, test the device to confirm that it operates correctly and consistently.","更換完成後,測試裝置,確認它能正確且穩定地運作。"]]},
{"n":205,"adv":false,"v":"duUBNa6cSmw","s":[[17,"Gather a small container for your first aid supplies.","準備一個小容器來裝急救用品。"],[33,"Place adhesive bandages inside for treating minor cuts and scrapes.","在裡面放 OK 繃,用來處理小割傷和擦傷。"],[50,"Add antiseptic wipes to help clean wounds before applying treatment.","加入消毒濕紙巾,在處理傷口前幫忙清潔。"],[62,"Include basic medical supplies for common injuries and everyday situations.","放入應付常見傷害和日常狀況的基本醫療用品。"],[90,"Organize the contents neatly so important items remain easy to locate.","把內容物整理整齊,讓重要的物品容易找到。"],[112,"Check expiration dates regularly to ensure supplies remain safe and effective.","定期檢查有效期限,確保用品安全有效。"],[124,"Before storing the kit, confirm that all essential items are complete and accessible.","收好急救包之前,確認所有必需品都齊全且容易拿取。"]]},
{"n":206,"adv":true,"v":"BHUlsofc_bc","s":[[26,"Gather essential medical supplies and place them on a clean, organized surface.","準備好必要的醫療用品,放在乾淨整齊的檯面上。"],[46,"Review each item carefully to ensure it remains usable and within its expiration date.","仔細檢查每樣物品,確保仍可使用且在有效期限內。"],[68,"Examine the available supplies to determine whether they meet basic emergency preparedness requirements.","檢查現有的用品,判斷它們是否符合基本的緊急應變需求。"],[90,"Organize the materials systematically to improve accessibility and reduce confusion during urgent situations.","有系統地整理用品,讓拿取更方便,並減少緊急時的混亂。"],[115,"Store frequently used items in visible locations so they can be located quickly when needed.","把常用物品放在看得到的地方,需要時才能很快找到。"],[139,"Verify that emergency contact information and critical supplies remain current and ready for immediate use.","確認緊急聯絡資料和重要用品都是最新的,並可以立即使用。"],[152,"Before storing the kit, confirm that all contents are complete, properly organized, and easily accessible during unexpected emergencies.","收好急救包之前,確認所有內容物都齊全、整理妥當,並在突發緊急狀況時容易拿取。"]]},
{"n":207,"adv":false,"v":"0LGfs4OxaQQ","s":[[17,"Gather all necessary tableware before setting the table.","擺餐桌之前先準備好所有需要的餐具。"],[33,"Place the dinner plates evenly at each seating position.","把餐盤平均地放在每個座位上。"],[52,"Arrange the utensils according to the order of use.","依照使用的順序擺放餐具。"],[70,"Position the drinking glasses above the knives on the right.","把水杯放在右側餐刀的上方。"],[89,"Fold the napkins neatly and place them beside or on each plate.","把餐巾摺整齊,放在每個盤子旁邊或上面。"],[109,"Check the spacing carefully to ensure guests have adequate room for comfortable dining.","仔細檢查間距,確保客人有足夠的空間舒適用餐。"],[130,"Before guests arrive, inspect the entire table arrangement to confirm a clean and well-organized presentation.","客人到達前,檢查整個餐桌的擺設,確認乾淨又井然有序。"]]},
{"n":208,"adv":false,"v":"CI7lFhbwHJE","s":[[18,"Hold the compass flat in your hand.","把指南針平放在手上。"],[34,"Move away from large metal objects nearby.","遠離附近的大型金屬物品。"],[51,"Allow the needle to settle before taking a reading.","等指針穩定後再讀方向。"],[70,"Rotate your body until the needle aligns with north.","轉動身體,直到指針對準北方。"],[82,"Identify your intended direction using the compass markings and reference points.","利用指南針上的刻度和參考點找出你要前往的方向。"],[110,"Maintain the correct heading while checking the needle for accuracy and consistency.","保持正確的方向,同時檢查指針是否準確一致。"],[132,"As you travel, monitor your position regularly and adjust your route to stay on course.","行進時定期確認你的位置,並調整路線以免偏離方向。"]]},
{"n":209,"adv":false,"v":"aobdX2dvn_c","s":[[18,"Gather your cleaning supplies first.","先準備好清潔用品。"],[32,"Remove dust from the entire window surface.","清除整個窗戶表面的灰塵。"],[48,"Spray the glass evenly with a suitable cleaner.","用合適的清潔劑均勻噴在玻璃上。"],[66,"Wipe the surface thoroughly using a clean microfiber cloth.","用乾淨的超細纖維布把表面徹底擦乾淨。"],[86,"Clean the corners thoroughly to remove accumulated dirt and residue.","徹底清潔角落,去除累積的髒污和殘留物。"],[106,"Dry the glass with smooth vertical strokes to reduce streaks and improve clarity.","以平順的上下方向把玻璃擦乾,減少水痕並讓玻璃更透亮。"],[128,"After cleaning all windows, inspect the glass from different angles to ensure a clear and spotless finish.","擦完所有窗戶後,從不同角度檢查玻璃,確保清澈無痕。"]]},
{"n":210,"adv":false,"v":"lbfVsYY3D-E","s":[[17,"Locate a public bicycle rental kiosk nearby.","找到附近的公共自行車租借站。"],[33,"Review the rental instructions displayed on the screen.","查看螢幕上顯示的租借說明。"],[50,"Select a bicycle and choose the desired rental period.","選一台腳踏車,並選擇想要的租借時間。"],[69,"Enter your payment information and confirm the transaction.","輸入付款資料並確認交易。"],[88,"Wait for the system to unlock the assigned bicycle automatically.","等待系統自動解鎖分配給你的腳踏車。"],[109,"Inspect the bicycle briefly to ensure the brakes and tires are in proper condition.","稍微檢查腳踏車,確保煞車和輪胎狀況良好。"],[121,"Before starting your ride, confirm that the rental is active and all equipment functions correctly.","出發騎車前,確認租借已啟用,所有裝備都運作正常。"]]},
{"n":211,"adv":false,"v":"L_nqqpM0UAw","s":[[18,"Turn the bicycle upside down carefully.","小心地把腳踏車倒過來放。"],[33,"Locate the section where the chain came off.","找出鏈條脫落的地方。"],[49,"Position the chain around the appropriate gears.","把鏈條套在適當的齒輪上。"],[67,"Rotate the pedals slowly to guide the chain into place.","慢慢轉動踏板,讓鏈條歸位。"],[86,"Check the chain alignment to ensure smooth movement and proper engagement.","檢查鏈條是否對齊,確保轉動順暢並正確咬合。"],[104,"Inspect nearby components for damage and remove any dirt that may affect performance.","檢查附近的零件是否損壞,並清除可能影響性能的髒污。"],[118,"Before riding again, test the pedals several times to confirm the chain operates smoothly and securely.","再次騎乘前,試踩幾次踏板,確認鏈條運作順暢且牢固。"]]},
{"n":212,"adv":true,"v":"bPP7o3k3-u4","s":[[26,"Arrive with a notebook and several ideas for potential writing projects.","帶著筆記本和幾個可能的寫作構想前來。"],[46,"Review the workshop prompt carefully and consider multiple approaches before beginning your draft.","開始寫草稿前,仔細閱讀工作坊的題目並考慮多種寫法。"],[69,"Develop an original concept by exploring character motivation, setting, and the central conflict.","透過探索角色動機、背景和核心衝突,發展出原創的構想。"],[92,"Write an initial draft that establishes a clear narrative voice and engages readers effectively.","寫出一份初稿,建立清楚的敘事口吻並有效吸引讀者。"],[115,"Participate in peer discussions to exchange constructive feedback and identify opportunities for meaningful revision.","參與同儕討論,交換建設性的意見,並找出值得修改的地方。"],[139,"Refine your work by strengthening descriptive language, improving structure, and enhancing overall clarity.","透過加強描寫用語、改善結構和提升整體清晰度來潤飾作品。"],[153,"Before concluding the workshop, revise your piece thoroughly and evaluate how effectively it communicates your intended message.","工作坊結束前,徹底修改你的作品,並評估它傳達你想表達的訊息有多成功。"]]},
{"n":213,"adv":false,"v":"16ZOa5ys5ds","s":[[18,"Open the suitcase on a flat surface.","在平坦的地方打開行李箱。"],[32,"Gather the items you plan to bring.","把你打算帶的東西集中起來。"],[48,"Fold your clothes neatly to save space.","把衣服摺整齊以節省空間。"],[65,"Place heavier items at the bottom of the suitcase.","把較重的物品放在行李箱底部。"],[84,"Store smaller belongings in separate compartments for easier organization.","把小東西放在不同的隔層裡,方便整理。"],[104,"Check your travel documents and essential items before closing the suitcase.","關上行李箱前,檢查你的旅行證件和必需品。"],[117,"Before leaving, confirm that everything is packed securely and that the suitcase closes properly.","出發前,確認所有東西都裝好了,行李箱也能好好關上。"]]},
{"n":214,"adv":false,"v":"SZc0RIHduD4","s":[[17,"Place your foot firmly on the ground surface.","把腳穩穩地踩在地面上。"],[33,"Hold both shoelaces securely with your hands.","用雙手抓穩兩條鞋帶。"],[50,"Cross the laces and pull them tightly together.","把鞋帶交叉並拉緊。"],[67,"Form a loop with one shoelace carefully at first.","先小心地用其中一條鞋帶做出一個圈。"],[86,"Wrap the other lace around the loop to create a secure knot.","把另一條鞋帶繞過這個圈,打成一個牢固的結。"],[105,"Pull both loops evenly to secure the knot and prevent it from loosening.","平均拉緊兩個圈,把結綁牢,防止它鬆開。"],[126,"Before walking away, check that the shoelaces are tied firmly and comfortably for movement.","走開之前,檢查鞋帶是否綁得牢固又方便活動。"]]},
{"n":215,"adv":false,"v":"NCp9wkb7kw4","s":[[17,"Locate the nearest fire extinguisher immediately.","立刻找到最近的滅火器。"],[32,"Move to a safe distance first before acting.","行動前先移到安全的距離。"],[49,"Pull the safety pin from the handle carefully.","小心地拔掉握把上的安全插銷。"],[67,"Aim the nozzle toward the base of the fire directly.","把噴嘴直接對準火源的底部。"],[86,"Squeeze the handle firmly to release the extinguishing agent.","用力握緊握把,噴出滅火劑。"],[105,"Sweep the nozzle from side to side to cover the affected area evenly.","左右掃動噴嘴,均勻覆蓋著火的區域。"],[126,"Once the fire is under control, monitor the area and contact emergency personnel if necessary.","火勢控制住後,持續注意該區域,必要時聯絡緊急救援人員。"]]},
{"n":216,"adv":false,"v":"VhM5_EWO29U","s":[[18,"Unfold the trail map completely.","把步道地圖完全攤開。"],[33,"Identify your current location on the map.","在地圖上找出你目前的位置。"],[50,"Locate the main paths and nearby landmarks.","找出主要的路線和附近的地標。"],[68,"Check the symbols to understand trail features and facilities.","查看圖例,了解步道的特色和設施。"],[88,"Compare the route options carefully to determine the most suitable path.","仔細比較各條路線,決定最合適的路徑。"],[108,"Estimate the distance and elevation changes to prepare for the hike effectively.","估算距離和高度變化,為健行做好充分準備。"],[121,"Before continuing, confirm your direction and review important landmarks to avoid getting lost.","繼續前進前,確認方向並複習重要的地標,以免迷路。"]]},
{"n":217,"adv":true,"v":"gjdNH9FSuzs","s":[[25,"Gather essential hiking equipment and arrange everything neatly on a clean surface.","準備好必要的登山裝備,並把所有東西整齊地放在乾淨的地方。"],[47,"Review the weather forecast carefully before selecting appropriate clothing and emergency supplies.","挑選合適的衣物和緊急用品前,先仔細查看天氣預報。"],[70,"Organize heavier items strategically to distribute weight evenly and maintain overall balance.","有策略地安排較重的物品,讓重量平均分配並保持整體平衡。"],[93,"Pack frequently used necessities in accessible compartments for greater convenience during the hike.","把常用的必需品放在容易拿取的隔層,健行時更方便。"],[116,"Verify that your supplies are sufficient to support the duration and difficulty of the planned route.","確認你的補給足以應付計畫路線的時間長度和難度。"],[139,"Adjust the shoulder straps properly to improve comfort and reduce unnecessary physical strain throughout the journey.","適當調整肩帶,提升舒適度並減少整趟旅程中不必要的身體負擔。"],[153,"Before departing, confirm that all essential supplies are secure and that your backpack is properly balanced for changing trail conditions.","出發前,確認所有必需品都已固定好,背包也平衡妥當,能應付多變的步道狀況。"]]},
{"n":218,"adv":false,"v":"4FAvgtRJhTI","s":[[18,"Choose a suitable location on the wall.","在牆上選一個合適的位置。"],[33,"Measure the area before marking the spot.","做記號之前先測量那個區域。"],[50,"Mark the desired position with a pencil.","用鉛筆標出想要的位置。"],[67,"Install the appropriate hook or wall anchor securely.","牢牢裝上合適的掛鉤或壁虎。"],[85,"Lift the picture frame carefully and align it with the marked position.","小心地拿起相框,對準標記的位置。"],[105,"Adjust the frame slightly to ensure it hangs straight and remains stable.","稍微調整相框,確保它掛得正又穩固。"],[126,"After hanging the frame, step back and confirm that it is centered properly and visually balanced.","掛好相框後,退後一步確認它位置置中且視覺上平衡。"]]},
{"n":219,"adv":false,"v":"3S2mw6Wm8-c","s":[[17,"Prepare your watercolor paper and painting supplies.","準備好水彩紙和繪畫用具。"],[33,"Arrange your palette before starting the painting.","開始畫之前先整理好調色盤。"],[49,"Wet the brush lightly to create an initial wash.","把畫筆稍微沾濕,先刷一層淡彩。"],[66,"Apply the base layer using smooth and controlled brush strokes.","用平順且有控制的筆觸畫上底色。"],[85,"Allow each layer to dry before adding details and deeper tones.","等每一層乾了之後,再加上細節和較深的色調。"],[105,"Blend the colors gradually to create smooth transitions and balanced contrast.","慢慢混色,營造柔和的過渡和平衡的對比。"],[127,"After completing the painting, clean your brushes thoroughly and let the artwork dry completely.","畫完之後,把畫筆徹底洗乾淨,並讓作品完全乾燥。"]]},
{"n":220,"adv":false,"v":"4KuwQv5e1ys","s":[[17,"Gather your ingredients and blending equipment.","準備好食材和果汁機。"],[33,"Wash and prepare the fruit before blending.","打果汁前先把水果洗好並處理好。"],[49,"Add the ingredients to the blender in order.","依照順序把材料加進果汁機。"],[66,"Pour in the liquid base and secure the lid.","倒入液體基底,並把蓋子蓋緊。"],[84,"Blend the mixture thoroughly until it reaches a smooth consistency.","把混合物充分打勻,直到質地滑順。"],[104,"Adjust the texture gradually by adding more liquid if necessary.","必要時加入更多液體,逐步調整口感。"],[125,"After preparing the smoothie, pour it into a glass and serve immediately for the best flavor.","果昔做好後倒進杯子裡,馬上享用風味最好。"]]},
{"n":221,"adv":false,"v":"yO_b71ulaHs","s":[[17,"Place your houseplants in a suitable location.","把你的室內植物放在合適的位置。"],[33,"Check the soil moisture before watering regularly.","定期澆水前先檢查土壤的濕度。"],[49,"Remove dead leaves to encourage healthy growth.","摘除枯葉,讓植物長得更健康。"],[67,"Rotate the pots occasionally to ensure even sunlight exposure.","偶爾轉動花盆,讓植物均勻照到陽光。"],[86,"Apply fertilizer carefully during the growing season to support development.","在生長季節小心施肥,幫助植物生長。"],[106,"Monitor temperature and humidity levels to maintain favorable growing conditions.","注意溫度和濕度,維持良好的生長環境。"],[127,"Inspect your plants regularly and address any signs of stress or pests promptly.","定期檢查植物,一發現不健康或有害蟲的跡象就立刻處理。"]]},
{"n":222,"adv":false,"v":"ToTud7fUgVg","s":[[17,"Prepare your molds and soap-making supplies.","準備好模具和做肥皂的用品。"],[32,"Measure each ingredient according to the recipe.","依照配方量好每一種材料。"],[49,"Melt the soap base slowly using low, steady heat.","用穩定的小火慢慢融化皂基。"],[68,"Add fragrance and color while mixing the ingredients gently.","輕輕攪拌材料時,加入香料和顏色。"],[86,"Pour the mixture carefully into the prepared molds to prevent spills.","小心地把混合物倒進準備好的模具,避免溢出。"],[106,"Allow the soap to cool completely before removing it from the mold safely.","等肥皂完全冷卻後,再安全地把它從模具中取出。"],[126,"After unmolding the soap, store it properly and allow sufficient time for curing before use.","脫模後,妥善存放肥皂,並在使用前給它足夠的時間熟成。"]]},
{"n":223,"adv":true,"v":"YKjQ0jkVv5o","s":[[26,"Prepare the ingredients carefully and organize your workspace before beginning the fermentation process.","開始發酵程序前,仔細準備好材料並整理好工作區。"],[50,"Measure the flour and yeast accurately to ensure consistent results throughout the procedure.","精確測量麵粉和酵母,確保整個過程的成果一致。"],[73,"Combine the ingredients thoroughly and mix until the dough reaches a uniform texture.","把材料充分混合,攪拌到麵團質地均勻。"],[96,"Allow the dough to rest while monitoring temperature and humidity for optimal yeast activity.","讓麵團靜置,同時注意溫度和濕度,讓酵母發揮最佳活性。"],[119,"Perform several gentle folds to strengthen the gluten structure and improve overall elasticity.","輕柔地摺疊麵團幾次,以強化麩質結構並提升整體彈性。"],[131,"Observe the dough carefully and adjust the fermentation time according to its gradual expansion.","仔細觀察麵團,並依照它逐漸膨脹的情形調整發酵時間。"],[156,"Before baking, confirm that the dough has developed sufficient volume and exhibits a well-balanced internal structure throughout.","烘烤前,確認麵團已膨脹到足夠的體積,且內部結構均勻良好。"]]},
{"n":224,"adv":false,"v":"icEGsqJmKDg","s":[[17,"Prepare your fabric and sewing materials.","準備好布料和縫紉材料。"],[32,"Thread the machine and position the fabric carefully.","替縫紉機穿好線,並小心擺好布料。"],[50,"Select the appropriate stitch setting for the fabric type.","依照布料種類選擇合適的針法設定。"],[67,"Lower the presser foot and guide the fabric steadily during stitching.","放下壓布腳,縫製時穩穩地引導布料。"],[86,"Maintain a consistent speed to produce straight seams and prevent uneven tension.","保持一致的速度,車出筆直的縫線並避免鬆緊不均。"],[105,"Inspect the stitches periodically and make adjustments to ensure accurate alignment.","定期檢查針腳並做調整,確保對齊準確。"],[126,"After completing the project, trim excess thread and examine the finished seams for overall quality.","完成作品後,剪掉多餘的線,並檢查縫好的接縫整體品質。"]]},
{"n":225,"adv":false,"v":"MXdcIM5Qo80","s":[[17,"Prepare your bottles and fragrance materials.","準備好瓶子和香氛材料。"],[33,"Arrange the ingredients before beginning the blending process.","開始調配前先把材料排好。"],[50,"Measure each essence carefully using the provided tools.","用提供的工具仔細量取每一種精油。"],[68,"Combine the selected scents to create a balanced fragrance.","把選好的香味混合,調出平衡的香氣。"],[86,"Allow the mixture to rest briefly before evaluating the aroma.","讓混合物靜置一下,再評估它的香氣。"],[105,"Adjust the proportions to achieve the desired fragrance and overall balance.","調整比例,達到想要的香味和整體平衡。"],[126,"After bottling, store it properly and allow the scent to mature naturally over time.","裝瓶後妥善存放,讓香味隨著時間自然熟成。"]]},
{"n":226,"adv":false,"v":"hvs74DKi7ww","s":[[17,"Open the feedback page on your device.","在你的裝置上打開意見回饋頁面。"],[33,"Review the instructions before completing the form.","填寫表單前先看清楚說明。"],[50,"Enter the required information in the appropriate fields.","在適當的欄位中輸入必要的資訊。"],[69,"Describe your experience clearly and provide relevant details.","清楚描述你的經驗並提供相關細節。"],[89,"Attach supporting documents when additional clarification is necessary.","需要進一步說明時,附上佐證文件。"],[109,"Review your responses carefully to ensure accuracy and consistency before submitting.","送出前仔細檢查你的回答,確保正確且一致。"],[130,"Confirm that all information is correct and adequately addresses the issue.","確認所有資訊都正確,且充分說明了問題。"]]},
{"n":227,"adv":false,"v":"Dk0XP_YyoKw","s":[[17,"Prepare your guitar and practice materials.","準備好吉他和練習教材。"],[33,"Sit comfortably and hold the instrument correctly.","舒服地坐好,並正確地拿著樂器。"],[50,"Tune the strings before beginning your practice session.","開始練習前先調好弦。"],[68,"Position your fingers carefully to form basic chords.","仔細擺好手指,按出基本和弦。"],[86,"Practice simple strumming patterns to develop rhythm and coordination.","練習簡單的刷弦節奏,培養節奏感和協調性。"],[106,"Change between chords smoothly while maintaining a steady tempo and consistent timing.","流暢地換和弦,同時保持穩定的速度和一致的節拍。"],[128,"After practicing, review your technique and store the instrument properly to prevent damage.","練習完後,檢討你的技巧並妥善收好樂器以免損壞。"]]},
{"n":228,"adv":false,"v":"leHGZFDt-xs","s":[[17,"Locate the parking payment kiosk nearby.","找到附近的停車繳費機。"],[33,"Review the instructions displayed on the screen.","看清楚螢幕上顯示的說明。"],[50,"Enter your license plate number exactly as displayed.","完全依照車牌上的樣子輸入你的車牌號碼。"],[68,"Confirm the parking duration before proceeding with payment.","付款前先確認停車時間。"],[87,"Select your preferred payment method and follow the on-screen instructions.","選擇你想用的付款方式,並依照螢幕上的指示操作。"],[108,"Review the transaction details carefully to ensure the information is accurate.","仔細檢查交易明細,確保資料正確。"],[120,"Before leaving the kiosk, collect your receipt and verify that the payment has been processed.","離開繳費機前,拿好收據並確認已完成付款。"]]},
{"n":229,"adv":true,"v":"kty5BpEJCPE","s":[[23,"Locate an available self-checkout kiosk and prepare the materials for borrowing.","找一台空的自助借書機,並準備好要借的資料。"],[46,"Review the on-screen instructions carefully before initiating the checkout procedure independently.","自行開始借書程序前,先仔細閱讀螢幕上的說明。"],[70,"Scan your library card accurately to access your account and borrowing privileges.","正確掃描你的借書證,以進入你的帳戶並使用借閱權限。"],[92,"Position each item properly to ensure the system detects the identification tags correctly.","把每件物品擺放好,確保系統能正確偵測辨識標籤。"],[114,"Verify the due dates and transaction details before confirming the borrowing request electronically.","以電子方式確認借閱前,先核對到期日和交易明細。"],[138,"Examine the checkout summary carefully to ensure all materials have been recorded accurately and completely.","仔細檢查借閱摘要,確保所有資料都已正確且完整地登記。"],[151,"Before leaving the library, confirm that the receipt reflects the correct items, due dates, and borrowing information.","離開圖書館前,確認收據上的物品、到期日和借閱資訊都正確無誤。"]]},
{"n":230,"adv":false,"v":"zWsgSVeycfc","s":[[18,"Prepare the knife and sharpening tools.","準備好刀子和磨刀工具。"],[34,"Position the blade at the correct angle.","把刀刃擺在正確的角度。"],[49,"Draw the blade smoothly across the sharpening surface.","把刀刃平順地劃過磨刀面。"],[68,"Repeat the motion evenly on both sides of the blade.","在刀刃兩面平均地重複這個動作。"],[86,"Wipe the blade carefully to remove any remaining metal residue particles.","小心擦拭刀刃,去除殘留的金屬碎屑。"],[106,"Test the edge gently to ensure consistent sharpness and safe handling performance.","輕輕測試刀鋒,確保鋒利度一致且使用安全。"],[128,"After sharpening, clean and store the knife properly to preserve its edge and condition.","磨好後,把刀子清乾淨並妥善收好,以保持刀鋒和狀態。"]]},
{"n":231,"adv":false,"v":"mx-HTPkYNhY","s":[[17,"Gather the necessary cleaning tools first.","先準備好必要的清潔工具。"],[24,"Remove any visible debris from the drain opening.","清除排水孔看得到的雜物。"],[50,"Fill the sink partially with warm water before proceeding.","繼續之前,先在水槽裡放一些溫水。"],[68,"Use a plunger carefully to loosen the blockage inside the pipe.","小心地用通馬桶的吸盤疏通管子裡的堵塞物。"],[87,"Run water through the drain to determine whether the obstruction has cleared.","讓水流過排水孔,看看堵塞是否已經清除。"],[106,"Repeat the process if necessary to restore normal drainage and water flow.","必要時重複這個步驟,恢復正常的排水和水流。"],[128,"After clearing the clog, rinse the sink thoroughly and inspect the drain for remaining debris.","疏通後,把水槽徹底沖乾淨,並檢查排水孔有沒有殘留的雜物。"]]},
{"n":232,"adv":false,"v":"d5aNmVf21PQ","s":[[17,"Prepare your fabric and embroidery supplies.","準備好布料和刺繡用品。"],[33,"Secure the fabric tightly in the embroidery hoop.","把布料緊緊固定在繡框上。"],[50,"Thread the needle carefully before beginning the design.","開始繡圖案前,小心地把線穿進針。"],[68,"Practice basic stitches to develop control and consistency.","練習基本針法,培養控制力和一致性。"],[87,"Follow the pattern closely to maintain accurate spacing and alignment.","緊跟著圖樣,保持正確的間距和對齊。"],[108,"Adjust the thread tension gradually to create a neat and balanced appearance.","逐步調整線的鬆緊度,讓成品整齊又平衡。"],[129,"After completing the design, trim excess thread and inspect the finished work carefully.","完成圖案後,剪掉多餘的線,並仔細檢查成品。"]]},
{"n":233,"adv":false,"v":"Aamsvrjd_rs","s":[[17,"Approach the train ticket kiosk and begin the process.","走到火車售票機前開始操作。"],[32,"Select your preferred language before continuing.","繼續之前先選擇你想用的語言。"],[49,"Choose your destination and travel date accurately.","正確選擇目的地和乘車日期。"],[67,"Review the available options and select the appropriate fare.","查看可選的方案,並選擇合適的票價。"],[86,"Confirm the travel details before proceeding to the payment screen.","進入付款畫面前先確認乘車資訊。"],[105,"Complete the transaction and verify that the information displayed is correct.","完成交易,並確認顯示的資訊正確無誤。"],[118,"Before leaving the kiosk, collect your ticket and confirm the departure details.","離開售票機前,拿好車票並確認出發資訊。"]]},
{"n":234,"adv":false,"v":"DFRlOGv5zZs","s":[[18,"Prepare your yarn and crochet hook.","準備好毛線和鉤針。"],[33,"Hold the hook comfortably before starting.","開始前用舒服的方式握住鉤針。"],[50,"Make a slip knot to begin the project.","打一個活結來開始作品。"],[65,"Practice basic chain stitches with steady hand movements.","用穩定的手部動作練習基本的鎖針。"],[84,"Maintain even tension to create consistent stitches throughout the pattern.","保持均勻的鬆緊度,讓整個圖樣的針目一致。"],[104,"Count your stitches regularly to ensure the pattern remains accurate and well shaped.","經常數針數,確保圖樣正確且形狀漂亮。"],[126,"Once your project is complete, fasten the yarn securely and trim any loose ends neatly.","作品完成後,把毛線牢牢固定,並把線頭修剪整齊。"]]},
{"n":235,"adv":true,"v":"zVNYcbiRAMo","s":[[23,"Locate an available document printing kiosk and prepare the files for printing.","找一台空的文件列印機,並準備好要列印的檔案。"],[48,"Connect your device securely and follow the on-screen instructions to access your documents.","穩妥地連接你的裝置,並依照螢幕指示開啟你的文件。"],[71,"Select the appropriate file and review the available printing preferences before continuing.","選擇正確的檔案,繼續之前先查看可用的列印設定。"],[93,"Adjust the paper size, print quality, and copy settings according to your specific requirements.","依照你的具體需求調整紙張大小、列印品質和份數設定。"],[116,"Preview the document carefully to verify formatting, page order, and overall print accuracy before proceeding.","繼續之前仔細預覽文件,確認格式、頁序和整體列印的正確性。"],[140,"Complete the payment process and monitor the printing progress to ensure every page is produced correctly.","完成付款,並留意列印進度,確保每一頁都正確印出。"],[163,"Once printing is complete, collect all printed documents and verify that every page matches your selected settings accurately.","列印完成後,拿好所有文件,並確認每一頁都完全符合你選的設定。"]]},
{"n":236,"adv":false,"v":"JmqhIklKhFU","s":[[17,"Prepare your wax and candle-making supplies.","準備好蠟和做蠟燭的用品。"],[33,"Secure the wick inside the container firmly.","把燭芯牢牢固定在容器裡。"],[50,"Melt the wax slowly using gentle, consistent heat.","用溫和穩定的熱度慢慢把蠟融化。"],[68,"Add fragrance oil and color while stirring evenly.","一邊均勻攪拌,一邊加入香精油和顏色。"],[86,"Pour the melted wax carefully into the prepared container.","小心地把融化的蠟倒進準備好的容器。"],[105,"Allow the wax to cool completely before trimming the wick to the proper length.","等蠟完全冷卻後,再把燭芯剪到適當長度。"],[126,"Once the candle has hardened, trim the wick neatly and store it in a cool, dry place.","蠟燭凝固後,把燭芯修剪整齊,並存放在陰涼乾燥的地方。"]]},
{"n":237,"adv":false,"v":"q8JvNwlUHdM","s":[[17,"Prepare the furniture and restoration supplies.","準備好家具和修復用品。"],[33,"Inspect the surface for scratches and damage.","檢查表面有沒有刮痕和損傷。"],[49,"Remove old paint using the appropriate tools.","用合適的工具去除舊油漆。"],[66,"Sand the surface evenly to create a smooth finish.","把表面均勻地磨砂,讓它變得光滑。"],[84,"Apply wood filler carefully to repair cracks and small imperfections.","小心塗上木材填充劑,修補裂縫和小瑕疵。"],[103,"Wipe away the dust completely before applying paint or protective finish.","上油漆或保護漆之前,先把灰塵完全擦乾淨。"],[122,"Once the finish has dried, inspect the furniture carefully and polish the surface for a professional appearance.","塗層乾了之後,仔細檢查家具並把表面拋光,讓它看起來很專業。"]]},
{"n":238,"adv":false,"v":"bOoGA22rR4o","s":[[16,"Approach the photo printing kiosk and begin the process.","走到相片列印機前開始操作。"],[33,"Connect your device using an available connection method.","用可用的連線方式連接你的裝置。"],[50,"Select the photos you would like to print from your device.","從你的裝置中選擇想列印的照片。"],[68,"Choose the print size and paper type according to your preferences.","依照你的喜好選擇列印尺寸和紙張種類。"],[88,"Review the selected images before confirming the print order and payment.","確認列印訂單和付款前,先檢查選好的照片。"],[108,"Complete the transaction and wait while photographs are printed automatically.","完成交易,等待照片自動印出。"],[129,"Once printing is complete, collect your photos and receipt before checking that every image printed correctly.","列印完成後,拿好照片和收據,再檢查每張照片是否都印得正確。"]]},
{"n":239,"adv":false,"v":"XiKhR6VSeoo","s":[[17,"Gather a needle, thread, and scissors.","準備好針、線和剪刀。"],[32,"Choose a thread that matches the fabric.","選一條和布料相配的線。"],[49,"Thread the needle and knot the end securely.","把線穿進針,並把線尾牢牢打結。"],[67,"Position the button over the original stitching holes.","把鈕扣對準原本的縫線孔。"],[85,"Sew through the button repeatedly to secure it firmly.","反覆穿過鈕扣縫,把它牢牢固定。"],[104,"Tie a strong knot underneath and trim the excess thread carefully.","在下面打一個牢固的結,並小心剪掉多餘的線。"],[125,"Once the button is secure, check that it is firmly attached and properly aligned.","鈕扣縫好後,檢查它是否牢固且對齊。"]]},
{"n":240,"adv":false,"v":"pz5MHSzDNSY","s":[[18,"Park the vehicles close to each other.","把兩台車停得靠近一點。"],[32,"Turn off both engines before connecting the cables.","接電線之前先把兩台車都熄火。"],[49,"Attach the red cable to the positive battery terminals.","把紅色電線夾在電瓶的正極上。"],[68,"Connect the black cable to the recommended grounding point securely.","把黑色電線牢牢接在建議的接地點上。"],[88,"Start the working vehicle and allow the battery to charge briefly.","發動正常的車,讓電瓶充電一下。"],[107,"Start the disabled vehicle and remove the cables in the correct sequence.","發動拋錨的車,並依照正確順序拆下電線。"],[127,"Once the engine is running, drive the vehicle for a while to recharge the battery.","引擎發動後,把車開一段時間讓電瓶充電。"]]},
{"n":241,"adv":false,"v":"4fI0Ztiskto","s":[[18,"Connect your phone to a Wi-Fi network.","把你的手機連上 Wi-Fi 網路。"],[33,"Check the battery level before starting the update.","開始更新前先檢查電量。"],[50,"Open the settings menu and locate the software update option.","打開設定選單,找到軟體更新的選項。"],[69,"Download the latest update after reviewing the available version information.","查看可用的版本資訊後,下載最新的更新。"],[89,"Begin the installation process and wait for the device to restart automatically.","開始安裝,等待裝置自動重新開機。"],[109,"Verify that the update has been installed successfully and all essential features function properly.","確認更新已成功安裝,所有基本功能都正常運作。"],[131,"Once the update is complete, review your settings and confirm that the device operates normally.","更新完成後,檢查你的設定並確認裝置運作正常。"]]},
{"n":242,"adv":true,"v":"Up4GXJF7NTM","s":[[26,"Open your digital ticket and prepare it for inspection before reaching the validation point.","到驗票點之前,先打開你的電子票準備查驗。"],[47,"Adjust your screen brightness and position the barcode clearly for accurate scanning by the system.","調整螢幕亮度,把條碼清楚地對好,讓系統能正確掃描。"],[70,"Present the digital ticket steadily until the scanner successfully recognizes the displayed verification code.","穩穩地出示電子票,直到掃描器成功辨識顯示的驗證碼。"],[92,"Wait for the confirmation message and verify that the ticket has been validated without any errors.","等待確認訊息,並確認車票已順利驗證、沒有任何錯誤。"],[115,"Follow the displayed instructions carefully if additional verification or identification is required before entry.","如果進場前需要額外驗證或身分確認,請仔細依照顯示的指示操作。"],[138,"Review the validation status thoroughly to confirm that all travel information has been processed correctly.","仔細檢查驗證狀態,確認所有乘車資訊都已正確處理。"],[151,"Before proceeding, ensure the validated ticket remains accessible in case additional verification is required during your journey.","繼續前進前,確保驗證過的車票隨時能拿出來,以防旅途中需要再次查驗。"]]},
{"n":243,"adv":false,"v":"_4CG_4VuLW4","s":[[17,"Approach the hotel self-check-in kiosk.","走到飯店的自助入住機前。"],[32,"Select your preferred language to begin.","選擇你想用的語言開始操作。"],[49,"Enter your reservation information or scan your identification.","輸入你的訂房資料或掃描你的身分證件。"],[66,"Review your booking details before confirming the check-in process.","確認入住前先檢查訂房資料。"],[85,"Verify your personal information and complete any required registration steps.","核對你的個人資料,並完成必要的登記步驟。"],[105,"Follow the on-screen instructions to receive your room assignment and key card.","依照螢幕指示取得你的房間和房卡。"],[126,"Once check-in is complete, collect your key card and confirm your room number before leaving the kiosk.","入住完成後,拿好房卡,並在離開自助機前確認你的房號。"]]},
{"n":244,"adv":false,"v":"D7k38Zueqpw","s":[[17,"Prepare your ingredients and bamboo rolling mat.","準備好食材和竹製壽司捲簾。"],[33,"Cook and season the sushi rice properly.","把壽司飯煮好並適當調味。"],[49,"Spread the rice evenly across the seaweed sheet.","把飯均勻地鋪在海苔上。"],[67,"Arrange the fillings neatly along the center.","把內餡整齊地排在中間。"],[84,"Roll the sushi firmly using steady, even pressure.","用穩定均勻的力道把壽司捲緊。"],[103,"Slice the roll carefully into equal pieces with a sharp knife.","用鋒利的刀子小心地把壽司捲切成相等的小塊。"],[122,"Once the rolls are prepared, arrange them neatly and serve with appropriate condiments.","壽司捲做好後,整齊擺盤,並搭配適當的調味料上桌。"]]},
{"n":245,"adv":false,"v":"-Z3AZS9EPKA","s":[[18,"Gather the items you plan to pack.","把你打算打包的東西集中起來。"],[31,"Place the heavier items near the bottom.","把較重的物品放在靠近底部的地方。"],[47,"Arrange the remaining belongings to distribute the weight evenly.","擺放剩下的物品,讓重量平均分配。"],[65,"Store frequently used items in easily accessible compartments.","把常用的物品放在容易拿取的隔層裡。"],[84,"Tighten the compression straps to keep everything securely in place.","拉緊壓縮帶,讓所有東西都固定好。"],[103,"Adjust the load carefully to improve balance and reduce unnecessary movement.","小心調整背包的負重,以改善平衡並減少不必要的晃動。"],[116,"Before leaving, confirm that the backpack is properly organized and comfortable to carry.","出發前,確認背包整理妥當且背起來舒適。"]]},
{"n":246,"adv":false,"v":"w2ElqN5vHac","s":[[18,"Park the vehicle in a safe location.","把車停在安全的地方。"],[32,"Turn off the engine before connecting the charger.","接充電器之前先熄火。"],[48,"Attach the charger clamps to the correct battery terminals.","把充電夾夾在正確的電瓶電極上。"],[67,"Select the appropriate charging mode before turning on the charger.","打開充電器前先選擇合適的充電模式。"],[85,"Monitor the charging process regularly to ensure the battery charges safely.","定期留意充電過程,確保電瓶安全充電。"],[105,"Disconnect the charger carefully after the battery has reached a full charge.","電瓶充飽後,小心拆下充電器。"],[118,"Before starting the vehicle, confirm that the battery connections are secure and functioning properly.","發動車子前,確認電瓶接頭牢固且運作正常。"]]},
{"n":247,"adv":false,"v":"zMq-TVYIHbc","s":[[18,"Prepare your leather and crafting tools.","準備好皮革和手作工具。"],[32,"Measure the leather before marking the pattern.","在畫版型之前先測量皮革。"],[48,"Cut the material carefully along the marked lines.","沿著畫好的線小心裁切材料。"],[65,"Punch the stitching holes with consistent spacing.","以一致的間距打出縫線孔。"],[84,"Stitch the leather pieces together using strong, even thread.","用堅固均勻的線把皮革片縫在一起。"],[103,"Burnish the edges thoroughly to create a smooth and polished finish.","把邊緣徹底打磨,讓它光滑亮麗。"],[123,"Once the project is complete, inspect the stitching and apply a protective leather conditioner.","作品完成後,檢查縫線並塗上保護用的皮革保養油。"]]},
{"n":248,"adv":false,"v":"GGsOFYhX_fI","s":[[17,"Park your vehicle beside the fuel pump.","把車停在加油機旁邊。"],[33,"Turn off the engine before opening the fuel door.","打開油箱蓋外蓋之前先熄火。"],[50,"Select the correct fuel type for your vehicle.","為你的車選擇正確的油品。"],[68,"Insert the nozzle securely into the fuel tank opening.","把油槍牢牢插進油箱口。"],[86,"Squeeze the handle gently until the tank reaches the desired level.","輕輕按壓握把,直到油量達到你想要的程度。"],[106,"Remove the nozzle carefully and close the fuel cap until it clicks securely.","小心取下油槍,把油箱蓋關到發出喀一聲為止。"],[119,"Before driving away, confirm that the fuel cap is tightened properly and the fuel door is closed.","開走之前,確認油箱蓋已鎖緊,外蓋也已關好。"]]},
{"n":249,"adv":false,"v":"xWOS7fem5N4","s":[[18,"Locate an available charging station nearby.","找到附近可用的充電站。"],[33,"Check that the charging port is compatible.","確認充電孔是相容的。"],[49,"Connect your device using the appropriate charging cable.","用合適的充電線連接你的裝置。"],[67,"Confirm that the charging indicator appears on the screen.","確認螢幕上出現充電指示。"],[86,"Place your device securely to prevent accidental movement or disconnection.","把裝置放穩,以免不小心移動或斷開。"],[105,"Monitor the charging progress occasionally to ensure the connection remains stable.","偶爾留意充電進度,確保連線保持穩定。"],[118,"Before disconnecting, confirm that your device has sufficient battery power for continued use.","拔掉之前,確認你的裝置有足夠的電量可以繼續使用。"]]},
{"n":250,"adv":true,"v":"jE-1Y-0TzHc","s":[[25,"Prepare your drawing tablet and open the illustration software before starting the creative process.","開始創作之前,先準備好繪圖板並開啟繪圖軟體。"],[39,"Create a new canvas and adjust the resolution according to your project's intended purpose.","建立新的畫布,並依照作品的用途調整解析度。"],[71,"Organize the layers carefully to separate sketches from line art and coloring throughout the illustration.","仔細整理圖層,把整幅插畫的草稿、線稿和上色分開。"],[95,"Select appropriate brushes and modify their settings to achieve consistent strokes and desired artistic effects.","選擇合適的筆刷並調整設定,以畫出一致的筆觸和想要的藝術效果。"],[121,"Refine the composition gradually by improving proportions and achieving better visual balance before adding fine details.","加入細節之前,逐步修正比例、改善視覺平衡,讓構圖更完善。"],[146,"Apply color thoughtfully while considering lighting and shading to create greater depth and visual realism.","用心上色,同時考慮光線和陰影,營造更強的立體感和真實感。"],[160,"Before exporting the artwork, review every layer carefully and confirm that the final composition meets your intended creative vision.","匯出作品前,仔細檢查每個圖層,確認最後的構圖符合你想要的創作理念。"]]},
{"n":251,"adv":false,"v":"DtAXH-pBdjQ","s":[[18,"Prepare your paper and calligraphy tools.","準備好紙張和書法工具。"],[33,"Hold the pen with a relaxed grip.","用放鬆的方式握筆。"],[49,"Practice basic strokes using slow, controlled movements.","用緩慢且有控制的動作練習基本筆畫。"],[67,"Maintain consistent pressure while forming each letter carefully.","仔細寫每個字母時,保持一致的力道。"],[86,"Follow the guidelines closely to improve spacing and letter alignment.","緊貼著輔助線書寫,以改善間距和字母對齊。"],[105,"Repeat each stroke patiently to develop smoother pen control and greater consistency.","耐心地重複每個筆畫,培養更流暢的控筆和更好的一致性。"],[126,"Once your practice is complete, review your lettering carefully and identify areas for improvement.","練習完成後,仔細檢查你寫的字,找出可以改進的地方。"]]},
{"n":252,"adv":false,"v":"IQTrs9FZJI0","s":[[18,"Gather your ingredients and blending equipment.","準備好食材和果汁機。"],[32,"Add the ice cream and milk to the blender.","把冰淇淋和牛奶加進果汁機。"],[48,"Include your chosen flavoring before securing the lid.","蓋緊蓋子前加入你選的調味料。"],[66,"Blend the ingredients until the mixture becomes smooth and creamy.","把材料打到滑順綿密。"],[85,"Check the consistency and adjust the ingredients if a thicker texture is preferred.","檢查濃稠度,如果想要更濃稠就調整材料。"],[105,"Blend the mixture again briefly to ensure an even texture and consistent flavor.","再稍微打一下,確保口感均勻、風味一致。"],[126,"Once the milkshake is ready, pour it into a chilled glass and serve immediately.","奶昔做好後,倒進冰過的杯子裡馬上享用。"]]},
{"n":253,"adv":false,"v":"UekYc1SquFI","s":[[17,"Gather the bread and sandwich ingredients.","準備好麵包和三明治的材料。"],[32,"Arrange the ingredients neatly on a clean surface.","把材料整齊地放在乾淨的檯面上。"],[48,"Spread the preferred condiment evenly across each bread slice.","在每片麵包上均勻塗抹你喜歡的醬料。"],[66,"Layer the fillings carefully to achieve a balanced combination of flavors.","仔細地層層鋪上內餡,讓口味搭配均衡。"],[85,"Place the top slice evenly and press the sandwich together with gentle pressure.","把最上面那片麵包放正,輕輕把三明治壓緊。"],[104,"Cut the sandwich into equal portions and arrange it neatly for serving.","把三明治切成相等的份量,整齊擺盤上桌。"],[124,"Once the sandwich is prepared, serve it immediately or package it properly for later consumption.","三明治做好後,馬上享用,或妥善包好留著稍後再吃。"]]},
{"n":254,"adv":false,"v":"exW99LLpbLk","s":[[17,"Locate a suitable picnic table nearby.","在附近找一張合適的野餐桌。"],[33,"Choose a spot with enough shade.","選一個有足夠樹蔭的地方。"],[49,"Arrange your belongings before preparing any food.","準備食物之前先把你的東西擺好。"],[67,"Nearby facilities provide drinking water and waste disposal for visitors.","附近的設施為遊客提供飲用水和垃圾處理。"],[87,"Open grassy spaces offer plenty of room for games and outdoor activities.","開闊的草地有充足的空間可以玩遊戲和進行戶外活動。"],[108,"Many picnic areas include walking paths and scenic views for visitors to enjoy.","許多野餐區都有步道和美景供遊客欣賞。"],[121,"Before leaving, collect all personal belongings and dispose of any waste in the designated containers.","離開前,帶走所有個人物品,並把垃圾丟進指定的容器。"]]},
{"n":255,"adv":false,"v":"fIirK67BIK0","s":[[18,"Arrive at the hotel luggage storage area.","抵達飯店的行李寄放區。"],[33,"Present your luggage to the hotel staff.","把行李交給飯店人員。"],[49,"Provide your reservation details for identification.","提供你的訂房資料以確認身分。"],[67,"Receive a claim ticket before leaving your belongings behind.","留下行李前先拿取行李牌。"],[86,"Confirm the pickup time and any storage conditions before departing.","離開前確認領取時間和任何寄放條件。"],[106,"Keep the claim ticket in a safe place until you return to collect your luggage.","把行李牌放在安全的地方,直到你回來領取行李。"],[119,"Before leaving, collect your luggage and verify that all belongings are accounted for.","離開前,領回你的行李並確認所有物品都在。"]]},
{"n":256,"adv":false,"v":"QvN2woFzMYM","s":[[17,"Enter the heritage village through the main entrance.","從正門進入文化古村。"],[33,"Pick up a visitor map near the entrance.","在入口附近拿一份遊客地圖。"],[49,"Explore the historic buildings at your own pace.","依照你自己的步調參觀歷史建築。"],[66,"Many exhibits demonstrate traditional crafts and everyday village life.","許多展覽示範傳統工藝和村莊的日常生活。"],[85,"Guided tours provide historical background about important village landmarks.","導覽行程提供村中重要地標的歷史背景。"],[105,"Visitors can observe cultural performances while exploring restored village buildings.","遊客參觀修復後的村莊建築時,也可以觀賞文化表演。"],[126,"Please visit the exhibition center to learn more about the village's historical development.","請參觀展覽中心,進一步了解這個村莊的歷史發展。"]]},
{"n":257,"adv":false,"v":"oUEz0ItQEkU","s":[[18,"Enter through the planetarium main entrance.","從天文館正門進入。"],[33,"Check today's presentation schedule before entering.","進場前先查看今天的節目時間表。"],[50,"Follow signs to the dome theater entrance.","依照指標前往圓頂劇場入口。"],[67,"Interactive exhibits explain basic astronomy before each presentation.","每場節目開始前,互動展覽會介紹基本的天文學知識。"],[86,"Educational displays introduce planets, stars, and other objects in space.","教育展示介紹行星、恆星和太空中的其他天體。"],[106,"Visitors learn how the night sky changes throughout different seasons.","遊客可以了解夜空在不同季節中如何變化。"],[127,"The dome theater presents realistic simulations of constellations and planetary movement.","圓頂劇場呈現星座和行星運行的逼真模擬。"]]},
{"n":258,"adv":false,"v":"veSVLg_4diw","s":[[18,"Review the relocation notice carefully.","仔細閱讀搬遷通知。"],[32,"Confirm the dates and temporary address information.","確認日期和臨時地址資訊。"],[48,"Update your records to reflect the change.","更新你的紀錄以反映這項變更。"],[64,"Inform relevant contacts about the temporary relocation.","通知相關的聯絡人這次的臨時搬遷。"],[82,"Arrange essential services to ensure uninterrupted communication and access.","安排必要的服務,確保通訊和聯繫不中斷。"],[102,"Verify that all correspondence will be forwarded to the correct location.","確認所有信件都會轉寄到正確的地點。"],[114,"Before relocating, confirm that necessary arrangements have been completed and important information has been shared.","搬遷之前,確認必要的安排都已完成,重要資訊也已告知相關人士。"]]},
{"n":259,"adv":false,"v":"C_QOBpNR2v8","s":[[18,"Enter the tailor shop with your clothing.","帶著你的衣服走進裁縫店。"],[34,"Explain the alterations you need clearly.","清楚說明你需要的修改。"],[50,"Discuss the desired fit with the tailor.","和裁縫師討論你想要的合身程度。"],[67,"The tailor measures your clothing for accurate alterations.","裁縫師會測量你的衣服,以便精準修改。"],[87,"Fabric samples help customers select suitable materials and matching thread colors.","布料樣本幫助顧客挑選合適的材質和搭配的線色。"],[107,"Skilled tailoring improves garment fit while maintaining comfort and overall appearance.","精湛的裁縫手藝能改善衣服的合身度,同時保持舒適和整體外觀。"],[128,"Before leaving, confirm the pickup date and review your alteration request carefully.","離開前,確認取件日期並仔細檢查你的修改需求。"]]},
{"n":260,"adv":true,"v":"Gx6tiL3QCVs","s":[[23,"Discuss the desired alterations and expected fit before leaving the garment for service.","把衣服留下來修改之前,先討論想要的修改內容和預期的合身程度。"],[48,"The tailor evaluates the fabric condition and identifies adjustments required to improve the overall fit.","裁縫師評估布料狀況,並找出改善整體合身度所需的調整。"],[61,"Accurate body measurements ensure that every alteration matches the customer's proportions and personal preferences.","精確的身體測量確保每一處修改都符合顧客的身材比例和個人喜好。"],[94,"Different fabrics require specialized techniques to preserve their structure while achieving precise construction and durability.","不同的布料需要專門的技術,才能在保持結構的同時做到精準的製作與耐用度。"],[118,"During the fitting session, the tailor evaluates garment balance and recommends additional adjustments for improved comfort.","試穿時,裁縫師會評估衣服的平衡感,並建議額外的調整以提升舒適度。"],[142,"Professional alterations enhance both appearance and functionality while maintaining the garment's original design and structural integrity.","專業的修改能同時提升外觀與功能,並保留衣服原本的設計和結構完整性。"],[166,"Before completing the alterations, the tailor carefully verifies every measurement to ensure a balanced fit and lasting comfort.","完成修改前,裁縫師會仔細核對每個尺寸,確保合身均衡且持久舒適。"]]},
{"n":261,"adv":false,"v":"nH4BPSoivu0","s":[[18,"Enter the drive-in theater with your ticket.","帶著票進入汽車電影院。"],[32,"Follow the signs to your assigned parking space.","依照指標開到你被分配的停車位。"],[49,"Position your vehicle facing the outdoor projection screen.","把車子停好,面向戶外投影螢幕。"],[66,"Tune your car radio to the specified frequency for movie audio.","把車上的收音機調到指定頻率來收聽電影聲音。"],[84,"Adjust your seating position and prepare refreshments before the feature begins.","在正片開始前調整好座位並準備點心飲料。"],[105,"The large outdoor screen provides clear viewing from every designated parking space.","巨大的戶外螢幕讓每個指定停車位都能清楚觀看。"],[126,"Enjoy the presentation from your vehicle while listening through the broadcast radio frequency.","透過廣播頻率收聽,在車內享受電影放映。"]]},
{"n":262,"adv":false,"v":"nNnvduyqIMI","s":[[17,"Enter the storage facility with your access code.","用你的通行密碼進入倉儲設施。"],[33,"Locate your assigned storage unit before unloading belongings.","卸下物品前先找到你被分配的儲物間。"],[50,"Arrange larger items first to maximize the available storage space.","先擺放大型物品,以充分利用可用的儲存空間。"],[67,"Place frequently used belongings near the entrance for convenient access later.","把常用的物品放在入口附近,之後拿取比較方便。"],[86,"Proper organization helps prevent damage and makes stored belongings easier to locate.","妥善整理有助於防止損壞,也讓存放的物品更容易找到。"],[106,"Secure valuable possessions inside sturdy containers to provide additional protection during storage.","把貴重物品放在堅固的容器裡,在存放期間提供額外保護。"],[120,"Before leaving, confirm your storage unit is locked and all personal belongings remain secure.","離開前,確認儲物間已上鎖,所有個人物品都安全無虞。"]]},
{"n":263,"adv":false,"v":"qCxx_gwYPbI","s":[[18,"Enter the clinic for your appointment.","按照預約時間進入診所。"],[33,"Check in at the reception desk upon arrival.","抵達時先到櫃台報到。"],[49,"Describe your symptoms and physical discomfort to the therapist.","向治療師描述你的症狀和身體不適。"],[67,"The therapist evaluates your movement to identify areas requiring treatment.","治療師評估你的動作,找出需要治療的部位。"],[79,"Personalized exercises improve flexibility and strengthen muscles supporting the affected joints.","個人化的運動能改善柔軟度,並強化支撐受影響關節的肌肉。"],[107,"Regular therapy sessions promote recovery while improving mobility and reducing discomfort.","定期治療能促進康復,同時改善活動能力並減輕不適。"],[130,"Consistent participation helps restore normal movement and supports long-term recovery after injury.","持續參與治療有助於恢復正常活動,並支持受傷後的長期康復。"]]},
{"n":264,"adv":false,"v":"_iqL9XLkJ2k","s":[[18,"Enter the bowling alley with your group.","和你的團體一起進入保齡球館。"],[33,"Select the appropriate bowling shoe size before playing.","打球前先選擇合適尺寸的保齡球鞋。"],[49,"Choose a bowling ball with a suitable weight for control.","選一顆重量適合、方便控制的保齡球。"],[66,"Enter player names before beginning the first bowling game.","開始第一局之前先輸入玩家名字。"],[84,"Roll the ball smoothly while aiming toward the center of the lane.","瞄準球道中央,平順地把球滾出去。"],[104,"Electronic scoreboards automatically record each frame and display the current score.","電子計分板會自動記錄每一格並顯示目前的分數。"],[126,"Players can enjoy the game while improving accuracy and developing better control.","玩家可以一邊享受比賽,一邊提升準確度並培養更好的控球能力。"]]},
{"n":265,"adv":false,"v":"_h3cQbhJY1E","s":[[18,"Enter the buffet restaurant and find your table.","走進自助餐廳並找到你的座位。"],[33,"Review the available dishes before choosing your meal.","選餐前先看看有哪些菜色。"],[51,"Select a plate and serve food from the buffet.","拿一個盤子,從自助餐台取餐。"],[69,"Explore various dishes while considering different flavors and ingredients.","一邊考慮不同的口味和食材,一邊嘗試各種菜餚。"],[88,"Customers can sample multiple cuisines and discover new dishes during their meal.","顧客用餐時可以品嚐多種料理並發現新菜色。"],[107,"The buffet arrangement allows guests to enjoy a wide selection of prepared foods.","自助式的安排讓客人能享用各式各樣已準備好的餐點。"],[128,"Visitors can experience diverse flavors while creating their own meal combinations from available options.","客人可以從現有的選擇中自行搭配餐點,體驗多元的風味。"]]},
{"n":266,"adv":true,"v":"3A6GsxM6Oaw","s":[[26,"Visitors explore various food stations featuring dishes from different regions around the world.","遊客探索各個美食攤位,品嚐來自世界各地的菜餚。"],[48,"The festival offers opportunities to sample traditional cuisines while learning about their cultural backgrounds.","這個美食節提供品嚐傳統料理的機會,同時了解它們的文化背景。"],[70,"Food vendors prepare authentic recipes using regional ingredients and demonstrate unique cooking techniques throughout the event.","攤商在整個活動期間用當地食材做出道地料理,並示範獨特的烹飪技巧。"],[94,"Guests can discover unfamiliar flavors while comparing culinary traditions from diverse cultures and geographic locations.","客人可以發現陌生的風味,同時比較不同文化與地區的飲食傳統。"],[118,"The event showcases international cuisine through carefully prepared dishes that represent the history and identity of different communities.","這個活動透過精心準備、代表不同族群歷史與身分的菜餚,展現國際美食。"],[142,"Professional chefs introduce advanced cooking methods while explaining the cultural significance behind their carefully selected ingredients and recipes.","專業主廚介紹進階的烹飪方法,並解說精選食材和食譜背後的文化意義。"],[167,"Visitors can experience a wide range of global flavors while gaining a deeper understanding of culinary traditions and cultural connections.","遊客可以體驗各式各樣的世界風味,同時更深入了解飲食傳統與文化之間的連結。"]]},
{"n":267,"adv":false,"v":"tAHI6dMd45c","s":[[18,"Enter the climbing gym and check in.","進入攀岩館並報到。"],[32,"Select suitable equipment before starting your climbing session.","開始攀岩前先挑選合適的裝備。"],[49,"Wear a safety harness and review basic climbing techniques.","穿上安全吊帶,並複習基本攀岩技巧。"],[67,"Practice climbing routes while improving balance and body coordination.","練習攀爬路線,同時提升平衡感和身體協調。"],[86,"Follow different routes that challenge climbers with various levels of difficulty.","嘗試不同難度、能挑戰攀岩者的各種路線。"],[105,"Experienced climbers develop strength and confidence through consistent practice on challenging walls.","有經驗的攀岩者透過在高難度岩壁上持續練習,培養力量與自信。"],[127,"Visitors can enjoy the activity while improving their skills and exploring new climbing techniques.","遊客可以享受這項活動,同時提升技巧並探索新的攀岩技術。"]]},
{"n":268,"adv":false,"v":"yF8H8LUHd1g","s":[[17,"Gather the ingredients and prepare your cooking tools.","準備好食材和烹飪工具。"],[33,"Heat the milk slowly in a small saucepan.","在小鍋子裡慢慢加熱牛奶。"],[49,"Add cocoa powder and mix the ingredients thoroughly together.","加入可可粉,把材料徹底攪拌均勻。"],[67,"Stir the mixture until the chocolate becomes smooth and evenly blended.","攪拌混合物,直到巧克力變得滑順且均勻融合。"],[86,"Adjust the sweetness by adding sugar according to your personal preference.","依照個人喜好加糖調整甜度。"],[105,"Pour the hot chocolate into a cup and add toppings for extra flavor.","把熱巧克力倒進杯子裡,再加上配料增添風味。"],[125,"Serve the drink while warm and enjoy the rich chocolate flavor after preparation is complete.","做好後趁熱享用,品嚐濃郁的巧克力風味。"]]},
{"n":269,"adv":false,"v":"nA0FsgURYLE","s":[[18,"Bring your clothing to the dry cleaner.","把衣服拿到乾洗店。"],[33,"Explain the cleaning service you need for each item.","說明每件衣物需要的清洗服務。"],[50,"Check the estimated pickup date before leaving your clothing.","留下衣服前先確認預計的取件日期。"],[67,"The staff examines fabric types and recommends suitable cleaning methods.","店員檢查布料種類並建議合適的清洗方式。"],[87,"Special treatments help remove stains while protecting delicate materials from damage.","特殊處理有助於去除污漬,同時保護細緻的材質不受損。"],[107,"Professional cleaning services restore clothing quality and extend the lifespan of various garments.","專業清洗服務能恢復衣物品質,並延長各種衣服的壽命。"],[129,"Customers can retrieve their cleaned items after confirming the service details and completing payment.","顧客確認服務內容並付款後,就可以取回洗好的衣物。"]]},
{"n":270,"adv":false,"v":"LH_JIOR1xzg","s":[[18,"Gather the ingredients and prepare your mixing bowl.","準備好食材和攪拌碗。"],[33,"Combine the ingredients until the mixture becomes smooth.","把材料混合,直到變得滑順。"],[49,"Add your favorite flavor and stir the mixture evenly.","加入你喜歡的口味,並把混合物攪拌均勻。"],[67,"Chill the mixture before transferring it into the ice cream maker.","把混合物冷藏後再倒進冰淇淋機。"],[85,"The machine freezes the mixture while creating a smooth and creamy texture.","機器會把混合物冷凍,同時做出滑順綿密的口感。"],[105,"Additional ingredients add flavor and improve the texture of the finished ice cream.","額外的配料能增添風味,並改善成品冰淇淋的口感。"],[126,"You can serve the finished ice cream and enjoy its smooth texture and rich flavor.","你可以端上做好的冰淇淋,享受它滑順的口感和濃郁的風味。"]]},
{"n":271,"adv":false,"v":"Frrnelf1-gU","s":[[18,"Drive your vehicle into the car wash.","把車子開進洗車場。"],[33,"Select the appropriate wash program before proceeding.","繼續前進前先選擇合適的洗車方案。"],[49,"Position your vehicle according to the entrance guide.","依照入口的引導把車子停好位置。"],[66,"Automated equipment cleans the vehicle using specialized cleaning solutions.","自動化設備使用專用清潔劑清洗車子。"],[85,"Rotating brushes and dryers remove dirt while protecting the vehicle's exterior.","旋轉刷和烘乾機能去除髒污,同時保護車子的外觀。"],[105,"Regular washing helps preserve the vehicle's appearance and reduces surface damage.","定期洗車有助於維持車子外觀並減少表面損傷。"],[126,"Leave the car wash with a clean vehicle and improved visibility for safer driving.","開著乾淨的車離開洗車場,視線更清楚,開車更安全。"]]},
{"n":272,"adv":true,"v":"igDwWhK-_60","s":[[26,"Select an appropriate wash program before guiding your vehicle toward the automated entrance.","把車開向自動入口之前,先選擇合適的洗車方案。"],[49,"Follow the illuminated directions to position your vehicle correctly before the cleaning process begins.","清洗開始前,依照發亮的指示把車子停在正確的位置。"],[72,"Specialized equipment applies cleaning solutions that remove accumulated dirt while protecting the vehicle's exterior finish.","專用設備噴上清潔劑,去除累積的髒污,同時保護車子的外部烤漆。"],[97,"Rotating brushes and high-pressure water systems remove surface contaminants without damaging properly maintained paintwork.","旋轉刷和高壓水柱系統能去除表面污染物,而不會損傷保養良好的烤漆。"],[121,"Advanced drying equipment reduces remaining moisture and improves visibility by removing water from exterior surfaces efficiently.","先進的烘乾設備能有效去除車身表面的水,減少殘留水分並改善視線。"],[147,"Routine vehicle washing helps preserve exterior materials while minimizing long-term damage caused by environmental contaminants and road debris.","定期洗車有助於保護車身外部材質,並將環境污染物和路面碎屑造成的長期損害降到最低。"],[173,"Consistent maintenance through professional cleaning services protects the vehicle's appearance and contributes to its long-term condition and value.","透過專業清潔服務持續保養,能保護車子的外觀,並有助於維持它的長期車況與價值。"]]},
{"n":273,"adv":false,"v":"Xz8Bc42cSPE","s":[[18,"Rent ice skates before entering the rink.","進入溜冰場前先租溜冰鞋。"],[33,"Check the rink schedule before choosing a session.","選擇場次前先查看溜冰場的時刻表。"],[48,"Step onto the ice and join other skaters.","踏上冰面,加入其他溜冰的人。"],[67,"Skate around the rink while enjoying the open space.","繞著溜冰場滑行,享受開闊的空間。"],[84,"Follow the flow of skaters as you make your way around.","繞場滑行時跟著其他溜冰者的方向前進。"],[101,"The rink provides ample space for recreational skating throughout the day.","溜冰場全天都提供充足的空間讓大家休閒溜冰。"],[121,"Visitors can enjoy a relaxing skating experience in the rink's lively atmosphere.","遊客可以在溜冰場熱鬧的氣氛中享受輕鬆的溜冰體驗。"]]},
{"n":274,"adv":false,"v":"134aCSGQF8w","s":[[18,"Enter the shop and browse available flowers.","走進花店,瀏覽店裡的花。"],[33,"Select a bouquet based on your preferred colors.","依照你喜歡的顏色挑選一束花。"],[49,"Discuss your choices with the florist before purchasing.","購買前和花藝師討論你的選擇。"],[67,"Fresh flowers are arranged with decorative wrapping for customers.","新鮮的花會為顧客搭配裝飾包裝。"],[86,"The florist recommends suitable flowers for different occasions and arrangements.","花藝師會針對不同場合和花藝設計推薦合適的花。"],[106,"Customers can request personalized designs with various flowers and decorations.","顧客可以要求用各種花材和裝飾做個人化設計。"],[128,"You can take home the arrangement and display it as a decorative addition.","你可以把花藝作品帶回家,當作裝飾擺放。"]]},
{"n":275,"adv":false,"v":"tZNjp9qB2e0","s":[[18,"Set up the grill in a safe area.","在安全的地方架好烤架。"],[32,"Season the chicken with your preferred herbs and spices.","用你喜歡的香草和香料替雞肉調味。"],[48,"Heat the grill before placing the chicken on the surface.","把雞肉放上烤架前先把烤架加熱。"],[65,"Cook the chicken evenly while monitoring the temperature.","一邊注意溫度,一邊把雞肉均勻烤熟。"],[82,"Turn the chicken occasionally to create a balanced texture and flavor.","偶爾翻動雞肉,讓口感和風味更均衡。"],[101,"Proper grilling techniques help maintain moisture while developing a rich smoky flavor.","正確的燒烤技巧有助於保留水分,同時烤出濃郁的煙燻風味。"],[122,"You can serve the grilled chicken with side dishes and enjoy the finished meal.","你可以把烤雞搭配配菜上桌,享用做好的餐點。"]]},
{"n":276,"adv":false,"v":"03jVg45OSwI","s":[[18,"Stay behind the safety line.","請站在安全線後方。"],[32,"Watch your surroundings at all times.","隨時注意周遭環境。"],[49,"Avoid leaning over the platform railing.","避免把身體探出平台欄杆。"],[66,"Hold personal belongings securely while moving nearby.","在附近走動時要拿好個人物品。"],[84,"Follow all posted instructions to maintain safety in crowded areas.","遵守所有公告的指示,以維護擁擠區域的安全。"],[104,"Keep pathways clear to prevent accidents and allow others to move comfortably.","保持走道暢通,以防止意外並讓其他人能舒適通行。"],[124,"During emergencies, remain calm and follow staff directions while exiting the viewing area.","緊急狀況時,保持冷靜並依照工作人員的指示離開觀景區。"]]},
{"n":277,"adv":false,"v":"rzQOzcPTDfY","s":[[18,"Enter the tea house and find a table.","走進茶館並找個位子坐。"],[33,"Review the tea menu before making your selection.","選擇之前先看看茶單。"],[50,"Choose a tea based on your preferred flavor.","依照你喜歡的口味選一種茶。"],[67,"The server prepares your tea according to the selected variety.","服務人員依照你選的茶種為你泡茶。"],[85,"Traditional tea houses offer a peaceful setting for visitors to relax.","傳統茶館提供寧靜的環境讓客人放鬆。"],[105,"Different teas provide distinct flavors and aromas depending on their preparation.","不同的茶依沖泡方式而有獨特的風味和香氣。"],[126,"Visitors can enjoy a calming atmosphere while experiencing a traditional tea service.","客人可以在令人放鬆的氛圍中體驗傳統的奉茶服務。"]]},
{"n":278,"adv":true,"v":"FjeYeRdwsNc","s":[[26,"Guests gather quietly together nearby before the traditional tea ceremony begins.","傳統茶道開始前,客人們安靜地聚集在附近。"],[49,"The host prepares the tea using carefully selected traditional utensils and fresh ingredients.","主人用精心挑選的傳統茶具和新鮮材料準備茶。"],[71,"Each movement follows a carefully established sequence that reflects the ceremony's rich cultural traditions.","每個動作都遵循精心制定的順序,反映出茶道豐富的文化傳統。"],[95,"Participants observe the preparation process while appreciating its meaningful symbolic gestures and deliberate pace throughout.","參與者觀看泡茶的過程,欣賞其中富有意義的象徵性動作和從容的節奏。"],[119,"The ceremony emphasizes mindfulness through carefully performed actions and thoughtful communication between all participants.","茶道透過細心執行的動作和參與者之間用心的交流來強調專注當下。"],[144,"Traditional tea ceremonies preserve cultural practices while creating opportunities for quiet reflection and meaningful social interaction.","傳統茶道保存了文化習俗,同時創造靜心反思和有意義社交互動的機會。"],[170,"The careful preparation and respectful gestures demonstrate how cultural traditions can be preserved and shared across generations.","細心的準備和恭敬的動作展現了文化傳統如何被保存並代代相傳。"]]},
{"n":279,"adv":false,"v":"ojzHpkCCbXA","s":[[18,"Visit the locksmith with your damaged key.","帶著損壞的鑰匙去找鎖匠。"],[33,"Explain the problem with your door lock.","說明你的門鎖有什麼問題。"],[49,"The locksmith examines the lock before suggesting a solution.","鎖匠先檢查鎖,再提出解決辦法。"],[68,"Some locksmiths can repair electronic locks and replace key fobs.","有些鎖匠會修理電子鎖並更換感應鑰匙。"],[87,"Modern access systems provide convenient entry for many buildings.","現代的門禁系統讓許多建築物進出更方便。"],[107,"A locksmith can duplicate traditional keys and program access devices.","鎖匠可以複製傳統鑰匙,也能設定門禁裝置。"],[128,"Professional locksmith services help customers maintain secure access to homes and vehicles.","專業的鎖匠服務幫助顧客確保住家和車輛的安全進出。"]]},
{"n":280,"adv":false,"v":"2gE8fj64qDg","s":[[17,"Gather the ingredients and prepare a small saucepan.","準備好食材和一個小鍋子。"],[34,"Combine the milk and cocoa powder in the pan.","在鍋中混合牛奶和可可粉。"],[51,"Add sugar and stir the mixture over medium heat.","加入糖,用中火攪拌混合物。"],[65,"Continue stirring until the chocolate mixture becomes smooth and thick.","持續攪拌,直到巧克力混合物變得滑順濃稠。"],[88,"Remove the pudding from the heat and let it cool slightly.","把布丁從火上移開,讓它稍微冷卻。"],[107,"Pour the pudding into small bowls and refrigerate until completely set.","把布丁倒進小碗裡,冷藏到完全凝固。"],[127,"You can serve the pudding chilled for a smooth and creamy dessert.","你可以冰冰地享用布丁,是一道滑順綿密的甜點。"]]},
{"n":281,"adv":false,"v":"DTsYrfypZkk","s":[[18,"Choose a club and collect your golf ball.","選一支球桿並拿好你的高爾夫球。"],[33,"Follow the course map to the first hole.","依照球場地圖走到第一洞。"],[49,"Take your first shot and aim toward the hole.","瞄準球洞,打出你的第一桿。"],[65,"Each hole features obstacles requiring careful positioning and shots.","每一洞都有障礙物,需要仔細站位和擊球。"],[84,"Players adjust their approach depending on the shape of each course.","玩家依照每個球道的形狀調整打法。"],[103,"The mini golf course provides an entertaining setting with obstacles and designs.","迷你高爾夫球場有各種障礙和設計,提供有趣的環境。"],[123,"Visitors can enjoy a casual game while exploring challenges throughout the course.","遊客可以輕鬆打一場球,同時探索整個球場的各種挑戰。"]]},
{"n":282,"adv":false,"v":"QzYF7lMofTk","s":[[18,"Enter the center and check the visitor information.","進入中心並查看遊客資訊。"],[33,"Explore the exhibits featuring local plants and animals.","參觀介紹當地動植物的展覽。"],[50,"Follow the marked trail through the surrounding natural area.","沿著標示好的步道穿越周圍的自然區域。"],[54,"Informational displays explain how local wildlife adapts to its environment.","解說展示說明當地野生動物如何適應環境。"],[87,"Visitors can observe native species and learn about their habitats.","遊客可以觀察原生物種並認識牠們的棲息地。"],[107,"The center provides educational programs that introduce visitors to local ecosystems.","中心提供教育課程,向遊客介紹當地的生態系統。"],[129,"You can explore the exhibits and discover more about the surrounding natural environment.","你可以參觀展覽,更深入認識周遭的自然環境。"]]},
{"n":283,"adv":false,"v":"bLDPuvZmP5M","s":[[18,"Bring your shoes to the repair shop.","把鞋子拿到修鞋店。"],[33,"Explain the problem with your shoes clearly.","清楚說明你的鞋子有什麼問題。"],[49,"The repair staff examines the shoes before suggesting repairs.","修鞋師傅先檢查鞋子,再建議如何修理。"],[68,"Different materials require specific methods to restore damaged areas.","不同的材質需要特定的方法來修復損壞的部分。"],[87,"The staff can replace worn soles and repair loose stitching.","師傅可以更換磨損的鞋底,並修補鬆脫的縫線。"],[106,"Careful repairs can improve comfort while extending the life of your shoes.","仔細的修理能提升舒適度,同時延長鞋子的壽命。"],[128,"You can pick up your repaired shoes after the requested service is complete.","服務完成後,你就可以取回修好的鞋子。"]]},
{"n":284,"adv":true,"v":"woJmXBb4DTo","s":[[27,"Bring your damaged shoes to the repair shop for professional assessment.","把損壞的鞋子帶到修鞋店做專業評估。"],[48,"The repair specialist examines the materials and identifies areas requiring restoration or replacement.","修鞋專家檢查材質,並找出需要修復或更換的部位。"],[72,"Different types of footwear require specialized techniques to preserve their structure and original appearance.","不同種類的鞋子需要專門的技術來保持結構和原本的外觀。"],[95,"Skilled repairs can restore worn soles while maintaining the flexibility and comfort of the shoes.","熟練的修理能修復磨損的鞋底,同時維持鞋子的柔軟度和舒適度。"],[117,"The specialist may recommend replacing damaged components when repairs cannot provide sufficient durability or support.","當修理無法提供足夠的耐用度或支撐時,專家可能會建議更換損壞的零件。"],[142,"Careful restoration techniques can extend the lifespan of quality footwear while preserving its original design and functionality.","細心的修復技術能延長優質鞋子的壽命,同時保留原本的設計和功能。"],[167,"Professional shoe repair allows customers to maintain valuable footwear and reduce unnecessary replacement by restoring items to usable condition.","專業修鞋讓顧客能把鞋子恢復到可穿的狀態,保養珍貴的鞋子並減少不必要的更換。"]]},
{"n":285,"adv":false,"v":"D1QIdEAQdtc","s":[[18,"Enter the shop and browse the displays.","走進商店並瀏覽陳列商品。"],[33,"Look through the shelves for suitable souvenirs.","在貨架上找合適的紀念品。"],[50,"Choose a gift based on the recipient's interests.","依照收禮者的興趣挑選禮物。"],[67,"The shop offers various items representing local culture and traditions.","這家店提供各種代表當地文化和傳統的商品。"],[87,"Visitors can find unique products that reflect the area's history and character.","遊客可以找到反映當地歷史和特色的獨特商品。"],[108,"Many items provide memorable reminders of places and experiences from their visit.","許多商品能讓人難忘地回想起旅途中的地點和經歷。"],[130,"You can select a meaningful souvenir to remember your trip for years to come.","你可以挑選一件有意義的紀念品,讓你多年後仍記得這趟旅行。"]]},
{"n":286,"adv":false,"v":"vXosEIwiNUs","s":[[18,"Choose a bowl before approaching the salad bar.","走到沙拉吧之前先選一個碗。"],[33,"Browse the available ingredients before making your selections.","做選擇之前先看看有哪些食材。"],[50,"Add vegetables and other toppings according to your preference.","依照你的喜好加入蔬菜和其他配料。"],[68,"Select a dressing that complements the ingredients in your bowl.","選一種能搭配碗中食材的沙拉醬。"],[87,"Combine different ingredients to create a balanced and flavorful salad.","組合不同的食材,做出營養均衡又美味的沙拉。"],[108,"The salad bar offers a variety of fresh options for customers.","沙拉吧為顧客提供各種新鮮的選擇。"],[128,"You can create your own salad by combining ingredients that suit your taste.","你可以組合符合自己口味的食材,做出專屬的沙拉。"]]},
{"n":287,"adv":false,"v":"_1IujHpBd6Q","s":[[18,"Check in at the blood donation center.","在捐血中心報到。"],[33,"Complete the required health information form.","填寫必要的健康資料表。"],[49,"A staff member reviews your information before donation.","捐血前會有工作人員檢查你的資料。"],[66,"The staff checks basic health measurements before beginning the procedure.","開始前,工作人員會檢查基本的健康數值。"],[85,"During the donation, remain seated while the staff monitors your condition.","捐血時請保持坐著,工作人員會注意你的狀況。"],[105,"Donated blood is carefully collected and prepared for patients who need transfusions.","捐出的血會被小心收集,並為需要輸血的病人做準備。"],[126,"Blood donations support medical treatment and help hospitals maintain an adequate supply.","捐血能支援醫療,並幫助醫院維持充足的血量。"]]},
{"n":288,"adv":false,"v":"PBwl3KdcrZE","s":[[18,"Enter the recreation center and check in.","進入休閒活動中心並報到。"],[33,"Explore the available facilities before choosing an activity.","選擇活動前先看看有哪些設施。"],[51,"Join a group activity or spend time in the open area.","參加團體活動,或在開放區域待一會兒。"],[70,"The center offers various programs for exercise and social interaction.","中心提供各種運動和社交互動的課程。"],[90,"Visitors can participate in activities that match their interests and abilities.","遊客可以參加符合自己興趣和能力的活動。"],[110,"Recreational programs provide opportunities to stay active while developing new interests.","休閒課程提供保持活躍、同時培養新興趣的機會。"],[134,"You can explore different activities and discover enjoyable ways to spend your free time.","你可以嘗試不同的活動,發掘愉快的休閒方式。"]]},
{"n":289,"adv":false,"v":"D_AtJnQ6EcY","s":[[17,"Recycling bins are available next to trash cans.","垃圾桶旁邊有資源回收桶。"],[33,"Students should turn off lights before leaving their classrooms.","學生離開教室前應該關燈。"],[50,"The university encourages students to reduce waste whenever possible.","大學鼓勵學生盡可能減少浪費。"],[69,"Solar panels on the library roof help reduce the building's energy use.","圖書館屋頂的太陽能板有助於減少大樓的能源使用。"],[87,"Students can help care for the community garden near the student union.","學生可以幫忙照顧學生活動中心附近的社區花園。"],[106,"The environmental club is planting trees behind the science building this weekend.","環保社這個週末要在科學館後面種樹。"],[126,"These simple efforts can help create a cleaner and greener campus for everyone.","這些簡單的努力能為大家打造更乾淨、更環保的校園。"]]},
{"n":290,"adv":true,"v":"H0cayQFF_8E","s":[[27,"Recycling initiatives encourage students to reduce waste throughout the campus.","資源回收計畫鼓勵學生在整個校園減少浪費。"],[47,"The university has introduced policies designed to limit unnecessary plastic consumption.","大學已推出旨在限制不必要塑膠使用的政策。"],[69,"Students are encouraged to conserve energy by turning off lights in unoccupied classrooms.","學生被鼓勵關掉無人教室的燈來節約能源。"],[90,"The environmental club organizes projects that promote sustainable practices among students and staff.","環保社籌辦各種計畫,在師生之間推廣永續的做法。"],[113,"Solar panels installed on campus buildings help reduce energy consumption and lower operating costs.","裝在校園建築上的太陽能板有助於減少能源消耗並降低營運成本。"],[135,"New landscaping projects use native plants that require less water and provide habitats for local wildlife.","新的景觀計畫使用需水量較少的原生植物,並為當地野生動物提供棲息地。"],[158,"As the university works toward greater sustainability, future construction projects must consider their environmental impact and long-term energy efficiency.","隨著大學朝更永續的方向努力,未來的建設計畫必須考量其環境影響和長期的能源效率。"]]},
{"n":291,"adv":false,"v":"RJwU5Qyvlh0","s":[[18,"Tap the screen to begin registration.","點一下螢幕開始登記。"],[33,"Select your preferred language from the menu.","從選單中選擇你想用的語言。"],[49,"Enter your name and basic information carefully.","仔細輸入你的姓名和基本資料。"],[66,"Review your details before confirming the registration.","確認登記前先檢查你的資料。"],[85,"The system displays your registration number after confirmation.","確認後,系統會顯示你的登記號碼。"],[104,"Follow the instructions to complete the remaining steps.","依照指示完成剩下的步驟。"],[123,"You can collect your confirmation slip after finishing the registration.","完成登記後,你可以領取確認單。"]]},
{"n":292,"adv":false,"v":"RlctMfivMwM","s":[[17,"The gym has daily limits for certain equipment.","健身房對某些器材有每日使用限制。"],[32,"Members can use each machine for a limited time.","會員每台機器只能使用一段有限的時間。"],[50,"During busy hours, users may need to share equipment.","尖峰時段,使用者可能需要共用器材。"],[68,"These limits help more members access the gym throughout the day.","這些限制讓更多會員整天都能使用健身房。"],[87,"Staff may ask members to finish their sessions when others are waiting.","有人在等候時,工作人員可能會請會員結束使用。"],[106,"Members should follow the posted time limits to ensure fair access for everyone.","會員應遵守公告的時間限制,確保每個人都能公平使用。"],[127,"Following these guidelines helps create a comfortable environment for all gym users.","遵守這些規定有助於為所有健身房使用者營造舒適的環境。"]]},
{"n":293,"adv":false,"v":"Hdyv-fGaOQI","s":[[17,"Visit the passport office during business hours.","在上班時間前往護照辦公室。"],[32,"Bring your identification and required documents.","攜帶你的身分證件和必要文件。"],[49,"Complete the application form with your personal information.","在申請表上填寫你的個人資料。"],[67,"Submit your documents and application to the staff.","把文件和申請表交給工作人員。"],[87,"The staff reviews your information before processing the application.","工作人員會先審核你的資料,再處理申請。"],[108,"Applicants may need to provide a recent photograph for their passport.","申請人可能需要提供一張近照用於護照。"],[129,"You can collect your passport after the application has been processed.","申請處理完成後,你就可以領取護照。"]]},
{"n":294,"adv":false,"v":"pvbF0XgFEJo","s":[[17,"Gather the ingredients and prepare the waffle maker.","準備好食材和鬆餅機。"],[32,"Mix the flour, eggs, milk, and sugar together.","把麵粉、蛋、牛奶和糖混合在一起。"],[51,"Pour the batter into the heated waffle maker.","把麵糊倒進預熱好的鬆餅機。"],[65,"Close the lid and cook the waffles until golden brown.","蓋上蓋子,把鬆餅烤到金黃色。"],[85,"Check the waffles occasionally to make sure they cook evenly.","偶爾檢查鬆餅,確保烤得均勻。"],[103,"Remove the waffles carefully and place them on a clean plate.","小心取出鬆餅,放在乾淨的盤子上。"],[123,"You can serve the waffles with syrup for a simple and delicious breakfast.","你可以淋上糖漿享用鬆餅,當作簡單又美味的早餐。"]]},
{"n":295,"adv":false,"v":"vhwa3nIetbc","s":[[18,"Approach the kiosk and tap the screen.","走近資訊站,點一下螢幕。"],[33,"Browse the main menu to explore available information.","瀏覽主選單,查看可用的資訊。"],[50,"Check the map to locate nearby facilities and services.","查看地圖,找出附近的設施和服務。"],[68,"The kiosk displays details about local attractions and transportation.","資訊站會顯示當地景點和交通的詳細資訊。"],[88,"Visitors can search for directions and check information before leaving.","遊客出發前可以搜尋路線並查看資訊。"],[109,"The touchscreen provides instructions to help visitors reach their destinations.","觸控螢幕提供指示,幫助遊客抵達目的地。"],[130,"Visitors can use the kiosk to find helpful information about the surrounding area.","遊客可以用資訊站找到周邊地區的實用資訊。"]]},
{"n":296,"adv":true,"v":"fb1Kx_3c9mY","s":[[26,"Visitors can access detailed information about nearby attractions and public facilities.","遊客可以取得附近景點和公共設施的詳細資訊。"],[48,"The interactive screen provides maps and directions to help visitors find important destinations throughout the area.","互動螢幕提供地圖和路線,幫助遊客找到這一帶的重要地點。"],[71,"Users can search for transportation information and check travel times before deciding how to reach their destination.","使用者可以搜尋交通資訊並查看交通時間,再決定怎麼前往目的地。"],[95,"The kiosk provides information about local events and attractions that visitors may want to explore.","資訊站提供遊客可能想去探索的當地活動和景點資訊。"],[118,"Detailed maps help visitors find nearby facilities when they are exploring an unfamiliar area on their own.","當遊客獨自探索陌生地區時,詳細的地圖能幫助他們找到附近的設施。"],[142,"The system allows users to compare transportation options and choose a route that suits their needs.","這個系統讓使用者比較各種交通方式,並選擇適合自己需求的路線。"],[165,"With updated directions and useful local information, the kiosk helps visitors navigate unfamiliar surroundings more easily and confidently.","有了最新的路線和實用的當地資訊,資訊站幫助遊客更輕鬆、更有自信地在陌生環境中找路。"]]},
{"n":297,"adv":false,"v":"MikczvtqNuI","s":[[17,"Enter the language center and check the class schedule.","進入語言中心並查看課表。"],[33,"Choose a class that matches your learning level.","選擇符合你學習程度的課程。"],[49,"Practice speaking with other students during the session.","上課時和其他同學練習口說。"],[67,"Teachers provide guidance to improve your communication skills.","老師提供指導,幫助你提升溝通能力。"],[85,"The center offers resources for developing listening, reading, and writing abilities.","中心提供培養聽力、閱讀和寫作能力的資源。"],[106,"Students can access language materials and receive support from experienced instructors.","學生可以使用語言教材,並獲得經驗豐富的老師協助。"],[128,"Practice helps learners build confidence and communicate more effectively in everyday situations.","練習能幫助學習者建立自信,在日常情境中更有效地溝通。"]]},
{"n":298,"adv":false,"v":"STUXtAKeN9Y","s":[[17,"Find an available computer at the library station.","在圖書館電腦區找一台空的電腦。"],[33,"Log in using your library card information.","用你的借書證資料登入。"],[49,"Open the program you need from the desktop.","從桌面開啟你需要的程式。"],[66,"Use the computer to search for books and online resources.","用電腦搜尋書籍和線上資源。"],[84,"You can access library databases for research and academic information.","你可以使用圖書館的資料庫來查找研究和學術資料。"],[104,"Save your work carefully before ending the session at the station.","結束使用前,記得小心儲存你的檔案。"],[115,"Remember to log out properly when you finish using the computer.","用完電腦時記得正確登出。"]]},
{"n":299,"adv":false,"v":"lMPv_OhTekc","s":[[18,"Check in at the car rental counter.","在租車櫃台辦理手續。"],[33,"Show your driver's license and rental reservation.","出示你的駕照和租車預約。"],[49,"Confirm the rental period and vehicle details with the staff.","和工作人員確認租期和車輛細節。"],[67,"The staff explains the rental terms and insurance options.","工作人員說明租車條款和保險方案。"],[85,"Check the vehicle for any existing damage before leaving.","出發前檢查車子是否有既有的損傷。"],[102,"The rental agreement includes important information about returning the vehicle.","租車合約包含有關還車的重要資訊。"],[123,"Return the car on time and follow the instructions provided by the rental company.","準時還車,並遵守租車公司提供的指示。"]]},
{"n":300,"adv":false,"v":"ebgEIZs3CmU","s":[[17,"Browse the electronics section for available products.","在電子產品區瀏覽現有的商品。"],[33,"Compare different devices based on their features and prices.","依照功能和價格比較不同的裝置。"],[50,"Ask a sales associate about the product you are interested in.","向店員詢問你感興趣的產品。"],[68,"Customers can test some devices before deciding what to purchase.","顧客決定購買前可以先試用部分裝置。"],[86,"The store offers various electronic products for home and personal use.","這家店提供各種家用和個人用的電子產品。"],[106,"Staff members can explain important features and answer questions about different devices.","店員可以說明重要的功能,並回答關於不同裝置的問題。"],[127,"Customers can compare several options and choose a device that best meets their needs.","顧客可以比較幾種選擇,挑出最符合自己需求的裝置。"]]},
{"n":301,"adv":false,"v":"fhi3tq0CMgY","s":[[17,"Visit the student services office for campus support.","到學生服務處尋求校園協助。"],[33,"Ask the staff about support available for students.","向工作人員詢問學生可以獲得的協助。"],[49,"The staff can explain how to apply for different services.","工作人員可以說明如何申請不同的服務。"],[67,"Students can get information about campus programs and available resources.","學生可以取得校園計畫和可用資源的資訊。"],[86,"The office provides assistance with common student needs and questions.","這個辦公室協助處理學生常見的需求和問題。"],[106,"You can speak with a staff member about problems related to your studies.","你可以和工作人員談談與課業有關的問題。"],[126,"The staff can help students find useful resources when they need additional support.","當學生需要更多協助時,工作人員可以幫他們找到有用的資源。"]]},
{"n":302,"adv":true,"v":"Cs1z3UV31KU","s":[[27,"Visit the student services office when you need help on campus.","在校園裡需要幫忙時,就到學生服務處。"],[49,"Staff members can explain university procedures and help you understand available support.","工作人員可以說明學校的程序,並幫助你了解可用的協助。"],[69,"The office provides guidance to students who have questions about their academic programs.","這個辦公室為對學程有疑問的學生提供指導。"],[91,"You can speak with an adviser about concerns that may affect your studies.","你可以和輔導老師談談可能影響課業的煩惱。"],[112,"Experienced staff can help students find appropriate resources when they need additional academic support.","當學生需要更多學業協助時,經驗豐富的工作人員可以幫他們找到合適的資源。"],[134,"The office connects students with university services that can provide more specialized assistance when necessary.","必要時,這個辦公室會為學生連結能提供更專業協助的學校服務。"],[158,"By helping students understand their options, the office makes it easier to manage challenges during their university experience.","透過幫助學生了解自己的選擇,這個辦公室讓學生更容易應對大學生活中的挑戰。"]]},
{"n":303,"adv":false,"v":"yLUuHNb3w0E","s":[[17,"Stop by the convenience store for snacks and drinks.","順道去便利商店買點零食和飲料。"],[33,"You can find basic food items near the front counter.","在前面櫃台附近可以找到基本的食品。"],[49,"The store also sells everyday products that customers need.","店裡也賣顧客需要的日常用品。"],[67,"Some convenience stores provide tables where customers can enjoy their food.","有些便利商店提供桌子讓顧客享用食物。"],[86,"Customers can heat prepared meals using a microwave inside the store.","顧客可以用店內的微波爐加熱即食餐點。"],[106,"Many stores stay open late so customers can shop at convenient times.","許多店營業到很晚,讓顧客可以在方便的時間購物。"],[127,"Convenience stores provide quick access to products when people need something on the way home.","當人們在回家路上需要什麼東西時,便利商店能讓他們快速買到。"]]},
{"n":304,"adv":false,"v":"I677rvIoqeE","s":[[18,"Bring the item back to the store.","把商品帶回店裡。"],[33,"Show your receipt to the customer service staff.","向客服人員出示你的收據。"],[49,"Explain why you would like to return the item.","說明你想退貨的原因。"],[65,"The staff checks the item before processing your return.","店員會先檢查商品,再處理你的退貨。"],[83,"You may receive a refund after the return is approved.","退貨核准後,你可能會拿到退款。"],[102,"Some stores offer an exchange if you prefer another item.","如果你比較想要其他商品,有些店提供換貨。"],[121,"Check the store's return policy before bringing an item back to the store.","把商品帶回店裡之前,先查看這家店的退貨政策。"]]},
{"n":305,"adv":false,"v":"heNgoem5tyg","s":[[17,"Check the holiday schedule before making plans.","做計畫之前先查看假日時間表。"],[32,"Some classes may have different times during holidays.","有些課程在假日期間時間可能不同。"],[49,"The office may adjust its hours during the holiday season.","辦公室在假期期間可能會調整辦公時間。"],[66,"Students should check for schedule changes before visiting the office.","學生前往辦公室前應先確認時間是否有變動。"],[85,"Please find updated information about holiday hours on the university website.","請在學校網站上查看假日時間的最新資訊。"],[105,"Staff members can explain any changes to the regular schedule during holidays.","工作人員可以說明假日期間一般時間表的任何變動。"],[125,"Check the updated schedule carefully before planning your visit during the holiday period.","在假期期間安排來訪之前,仔細查看更新後的時間表。"]]},
{"n":306,"adv":false,"v":"h2LbdAKDKQk","s":[[18,"Place your paper and pencils on the table.","把紙和鉛筆放在桌上。"],[33,"Start with a light sketch of the main shapes.","先輕輕畫出主要的形狀。"],[48,"Add simple lines to show the basic form of the object.","加上簡單的線條,畫出物體的基本外形。"],[66,"Use your pencil to create darker areas where the light does not reach.","用鉛筆在光線照不到的地方畫出較暗的區域。"],[84,"Look closely at the object and add smaller details to your drawing.","仔細觀察物體,在畫上加入更小的細節。"],[104,"Try different amounts of pressure to create lighter and darker pencil marks.","嘗試用不同的力道,畫出較淺和較深的筆觸。"],[125,"Step back from your drawing and make small changes to improve the overall appearance.","退後一步看看你的畫,做些小修改來改善整體的樣子。"]]},
{"n":307,"adv":false,"v":"ytf-LMKYofA","s":[[17,"Reserve a practice room before your music session.","音樂練習前先預約琴房。"],[32,"Bring your instrument and sheet music into the room.","把你的樂器和樂譜帶進琴房。"],[48,"Adjust the chair and music stand before you begin playing.","開始演奏前調整好椅子和譜架。"],[66,"Check the instrument carefully and make sure everything is ready.","仔細檢查樂器,確認一切都準備好了。"],[84,"Practice the difficult sections slowly before playing the entire piece.","演奏整首曲子之前,先慢慢練習困難的段落。"],[104,"Follow the practice room rules to avoid disturbing other students nearby.","遵守琴房規定,以免打擾附近的其他同學。"],[124,"Once your practice session is over, return the room to its original condition.","練習結束後,把琴房恢復原狀。"]]},
{"n":308,"adv":true,"v":"JdrHnM_nla0","s":[[26,"Begin your practice session by reviewing the musical passages that require the most attention.","練習一開始,先複習最需要注意的樂段。"],[49,"Work through difficult passages slowly before gradually increasing the tempo.","先慢慢練熟困難的樂段,再逐漸加快速度。"],[70,"Pay close attention to rhythm and articulation when practicing technically demanding sections.","練習技巧要求高的段落時,要特別注意節奏和音的表現方式。"],[92,"Record yourself occasionally so you can identify areas that need further improvement.","偶爾把自己的演奏錄下來,才能找出需要再改進的地方。"],[115,"When practicing a new piece, divide it into smaller sections before putting everything together.","練習新曲子時,先分成小段落練習,再把全部串起來。"],[138,"After mastering the difficult sections, practice the entire piece continuously to improve your overall consistency.","練熟困難的段落後,把整首曲子從頭到尾連續練習,以提升整體的一致性。"],[162,"Once you become comfortable with the piece, experiment with different interpretations while maintaining its original musical structure.","熟悉曲子之後,在保持原本音樂結構的同時,嘗試不同的詮釋方式。"]]},
{"n":309,"adv":false,"v":"2-ctYtBI1kY","s":[[18,"Choose a small pot for your indoor plant.","為你的室內植物選一個小花盆。"],[32,"Fill the pot with fresh soil before planting.","種植前把花盆裝滿新的土壤。"],[48,"Make a small hole in the soil for the seedling.","在土裡為幼苗挖一個小洞。"],[64,"Place the seedling in the hole and cover its roots with soil.","把幼苗放進洞裡,用土蓋住它的根。"],[82,"Add a small amount of water to help the plant adjust.","澆少量的水幫助植物適應。"],[101,"Place the pot near a window where the plant can get enough sunlight.","把花盆放在窗戶附近,讓植物能照到足夠的陽光。"],[121,"Check the soil regularly and add water when the surface becomes completely dry.","定期檢查土壤,表面完全乾了就要澆水。"]]},
{"n":310,"adv":false,"v":"-DDXlmCwMhc","s":[[19,"Check in with the resident adviser first.","先向宿舍輔導員報到。"],[33,"Please keep your room key with you.","請隨身攜帶你的房間鑰匙。"],[48,"Laundry machines are located on the ground floor.","洗衣機在一樓。"],[67,"Quiet hours begin every evening at 10:00.","每天晚上 10 點開始是安靜時間。"],[85,"You must submit a maintenance request online for any repairs.","任何維修都必須在網路上提出申請。"],[104,"Guests are allowed in the common room, but they must sign in at the front desk.","訪客可以進入交誼廳,但必須在櫃台登記。"],[125,"Although cooking is permitted in the shared kitchen, students are expected to clean up their own dishes.","雖然可以在共用廚房煮東西,但學生必須自己清洗餐具。"]]},
{"n":311,"adv":false,"v":"Vyxrwf_e1ns","s":[[18,"Show your student ID at the counter.","在櫃台出示你的學生證。"],[25,"Prescriptions are filled on the first floor.","處方藥在一樓領取。"],[49,"The campus pharmacy is open until 5 today.","校園藥局今天營業到 5 點。"],[67,"Over-the-counter medicines are available in the main lobby.","主大廳有販售成藥。"],[86,"You can consult the pharmacist if you have any questions.","如果有任何問題,可以諮詢藥師。"],[104,"Most health insurance plans cover basic medications, but extra fees may apply.","大多數健康保險方案都有給付基本藥物,但可能要另外付費。"],[126,"Although walk-in service is offered, scheduling an appointment online saves time.","雖然可以現場服務,但在網路上預約比較節省時間。"]]},
{"n":313,"adv":false,"v":"_06uOntbZM4","s":[[18,"Check the museum map before you begin.","開始參觀前先看看博物館地圖。"],[32,"Start with the oldest exhibits in the gallery.","從展廳裡最古老的展品開始看。"],[49,"Read the information panels beside each historical artifact.","閱讀每件歷史文物旁邊的說明牌。"],[67,"Ask the museum guide about anything you do not understand.","有任何不懂的地方就問博物館導覽員。"],[85,"Take brief notes on objects that seem interesting to you.","把你覺得有趣的物品簡單記下來。"],[103,"Compare the artifacts from different periods to notice important changes.","比較不同時期的文物,注意重要的變化。"],[115,"Before leaving, review your notes and consider how the exhibits connect to each other.","離開前,複習你的筆記,想想這些展品之間有什麼關聯。"]]},
{"n":314,"adv":true,"v":"AcOzP6BipK8","s":[[26,"Start by looking at the oldest exhibits on display in the main gallery.","先從主展廳裡展出的最古老展品開始看。"],[49,"Take your time and read the descriptions beside the artifacts carefully.","慢慢來,仔細閱讀文物旁邊的說明。"],[70,"Notice how some of the objects changed as people developed new ways of living.","注意有些物品如何隨著人們發展出新的生活方式而改變。"],[92,"As you move through the gallery, think about how each exhibit connects to the next.","在展廳中參觀時,想想每件展品和下一件之間有什麼關聯。"],[115,"You may find it helpful to compare similar objects from different periods as you continue your visit.","繼續參觀時,比較不同時期的相似物品可能會對你有幫助。"],[137,"When you come across something unfamiliar, read the background information before moving on to another exhibit.","遇到不熟悉的東西時,先讀背景資料,再前往下一件展品。"],[160,"After you have explored the entire gallery, try to explain how the exhibits show changes in everyday life.","參觀完整個展廳後,試著說明這些展品如何呈現日常生活的變化。"]]},
{"n":315,"adv":false,"v":"X4dtDdWPvYU","s":[[19,"Choose a movie from the list.","從清單中選一部電影。"],[33,"Select your preferred showtime from the screen.","在螢幕上選擇你想要的場次。"],[50,"Choose the number of tickets you need.","選擇你需要的票數。"],[66,"Select your seats before moving to the payment screen.","進入付款畫面前先選好座位。"],[84,"Check the ticket details carefully before completing your purchase.","完成購買前仔細檢查票券資訊。"],[103,"Pay with your card and wait for the kiosk to print your tickets.","用卡片付款,等售票機印出你的票。"],[122,"Take your tickets from the machine and check the theater number before leaving.","從機器取出你的票,離開前確認影廳號碼。"]]},
{"n":316,"adv":false,"v":"wKOZlfJ_G1Y","s":[[18,"Find the equipment desk near the library.","找到圖書館附近的器材借用櫃台。"],[33,"Tell the staff member which equipment you need.","告訴工作人員你需要哪些器材。"],[49,"Show your student card before checking out equipment.","借用器材前出示你的學生證。"],[66,"Inspect the equipment carefully for any visible damage.","仔細檢查器材是否有明顯的損壞。"],[84,"Ask for instructions if you are unfamiliar with the equipment.","如果不熟悉這個器材,請詢問使用說明。"],[103,"Confirm the return date before taking the equipment with you.","把器材帶走前先確認歸還日期。"],[123,"Keep the equipment in good condition and return everything to the desk on time.","保持器材狀況良好,並準時把所有東西歸還到櫃台。"]]},
{"n":317,"adv":false,"v":"3P4W3rPjcMA","s":[[18,"The system will be unavailable tonight.","系統今晚將無法使用。"],[33,"Scheduled maintenance will begin after midnight.","預定的維修將在午夜後開始。"],[48,"Please save your work before the maintenance begins.","請在維修開始前儲存你的工作。"],[65,"Some online services may be temporarily unavailable during this period.","在這段期間,部分線上服務可能暫時無法使用。"],[85,"You may experience delays when accessing your account or files.","存取帳戶或檔案時可能會有延遲。"],[104,"The system should return to normal once the maintenance is complete.","維修完成後,系統應該就會恢復正常。"],[124,"Please check the service later if you experience any problems after maintenance.","如果維修後遇到任何問題,請稍後再查看服務狀況。"]]},
{"n":318,"adv":false,"v":"9VSytc35QpQ","s":[[18,"Find the currency exchange counter near the entrance.","找到入口附近的外幣兌換櫃台。"],[32,"Check the current exchange rate before exchanging money.","換錢前先查看目前的匯率。"],[48,"Tell the clerk how much money you want to exchange.","告訴櫃員你想換多少錢。"],[65,"Ask whether there is an additional fee for the transaction.","詢問這筆交易是否有額外的手續費。"],[82,"Count the local currency carefully before leaving the counter at the airport.","在機場離開櫃台前,仔細點清當地貨幣。"],[101,"Keep your receipt safely in case you need to check the transaction later.","妥善保管收據,以防日後需要核對交易。"],[122,"If anything seems unclear, ask the clerk about the current exchange rate before completing the transaction.","如果有任何不清楚的地方,完成交易前先向櫃員詢問目前的匯率。"]]},
{"n":319,"adv":false,"v":"6S82d_Cf5F0","s":[[17,"Choose a good location before taking photographs.","拍照前先選一個好地點。"],[33,"Check the lighting before taking your first picture.","拍第一張照片前先看看光線。"],[48,"Adjust the camera settings for the available natural light.","依照現有的自然光調整相機設定。"],[65,"Try different angles to create a more balanced composition.","嘗試不同的角度,拍出更平衡的構圖。"],[82,"Keep your subject in focus while taking each photograph.","拍每一張照片時都讓主體保持清晰對焦。"],[100,"Take several pictures from different angles to compare the results.","從不同角度多拍幾張照片來比較效果。"],[120,"Review your photographs carefully and choose the ones that best capture the subject.","仔細檢視你的照片,挑出最能捕捉主體的幾張。"]]},
{"n":320,"adv":true,"v":"hj2tFY1l7k0","s":[[25,"Before taking photographs, consider how the location will affect the overall appearance of your pictures.","拍照之前,想想地點會如何影響照片的整體樣貌。"],[48,"Pay attention to the direction of the light, especially when photographing people outdoors.","注意光線的方向,尤其是在戶外拍人的時候。"],[70,"Experiment with different camera settings to create the effect you want in each photograph.","嘗試不同的相機設定,在每張照片中營造你想要的效果。"],[91,"When composing a photograph, consider how the position of your subject affects the balance of the image.","構圖時,想想主體的位置如何影響畫面的平衡。"],[114,"Try changing your position slightly if the background makes it difficult to keep your subject clearly visible.","如果背景讓主體不容易清楚呈現,試著稍微改變你的位置。"],[137,"Take several photographs from different angles so you can compare how each position changes the final image.","從不同角度多拍幾張照片,比較每個位置如何改變最後的影像。"],[160,"After reviewing your photographs, select the strongest images and consider what you could improve in your next session.","檢視照片後,挑出最好的幾張,並想想下次拍攝可以改進什麼。"]]},
{"n":321,"adv":false,"v":"TYU2BY-Lxus","s":[[18,"Find the tourist center near the station.","找到車站附近的遊客中心。"],[33,"Ask the staff member for a city map.","向工作人員要一份城市地圖。"],[49,"Tell them which attractions you want to visit.","告訴他們你想去哪些景點。"],[66,"Ask about transportation options between the main attractions nearby.","詢問附近主要景點之間有哪些交通方式。"],[85,"Check the opening hours before planning your visit for tomorrow morning.","規劃明天上午的行程前,先查好開放時間。"],[105,"Ask whether any local events are happening during your stay this week.","問問這週你停留期間有沒有當地活動。"],[117,"Before leaving, collect all the information you need to plan your sightseeing schedule.","離開前,收集好規劃觀光行程需要的所有資訊。"]]},
{"n":322,"adv":false,"v":"_93pIVEGPVM","s":[[18,"Find your seat before the seminar begins.","研討會開始前先找到你的座位。"],[33,"Pick up the seminar materials near the entrance.","在入口附近拿研討會資料。"],[50,"Listen carefully as the speaker introduces the main topic.","講者介紹主題時請仔細聆聽。"],[68,"Take notes carefully on the key points during the presentation.","簡報時仔細記下重點。"],[87,"Write down any important questions you want to ask during the discussion.","寫下討論時你想問的重要問題。"],[107,"Join the discussion when the speaker invites participants to share their ideas.","講者邀請與會者分享想法時,加入討論。"],[119,"Before leaving, collect the resources mentioned during the seminar for future reference.","離開前,收集研討會中提到的資源以供日後參考。"]]},
{"n":323,"adv":false,"v":"KVnzWdf_BWU","s":[[18,"Choose a new color scheme for your room.","為你的房間選一組新的配色。"],[33,"Decide which furniture you want to keep or replace.","決定哪些家具要保留或更換。"],[50,"Measure the available space carefully before buying new furniture.","買新家具前仔細測量可用的空間。"],[69,"Move larger pieces first to make enough space for changes.","先搬大型家具,騰出足夠的空間做調整。"],[87,"Arrange the furniture so the room feels more open and comfortable.","擺放家具,讓房間感覺更開闊舒適。"],[107,"Add a few decorations to give the room a more personal style.","加一些裝飾,讓房間更有個人風格。"],[127,"After finishing the changes, rearrange the furniture to create a more comfortable and organized space.","改造完成後,重新擺放家具,營造更舒適整齊的空間。"]]},
{"n":324,"adv":false,"v":"WpFb8gVLBNk","s":[[18,"Find the stationery section near the entrance.","找到入口附近的文具區。"],[33,"Look for the supplies you need for your classes.","找找你上課需要的用品。"],[49,"Compare different notebooks before choosing one for your notes.","比較不同的筆記本,再選一本來做筆記。"],[66,"Check the prices carefully before adding items to your basket.","把商品放進購物籃前仔細看價格。"],[84,"Choose pens and markers that are suitable for your current assignment.","選擇適合你目前作業的筆和麥克筆。"],[102,"Ask a staff member for assistance if you cannot find a particular item.","如果找不到某樣商品,請向店員尋求協助。"],[114,"Before paying, review your supplies and make sure you have everything needed for class.","付款前,檢查你的用品,確認上課需要的東西都買齊了。"]]},
{"n":325,"adv":false,"v":"THMoHM7vRnA","s":[[19,"Measure the wood before cutting it.","鋸木頭之前先測量。"],[33,"Mark the cutting line with a pencil.","用鉛筆畫出切割線。"],[50,"Hold the wood firmly while using the saw.","用鋸子時把木頭牢牢抓穩。"],[66,"Cut along the marked line with steady movements.","用穩定的動作沿著畫好的線鋸。"],[84,"Check the pieces carefully before putting them together.","組合之前仔細檢查每一塊木頭。"],[101,"Position the nails evenly and hammer them into the wood.","把釘子平均排好,再把它們敲進木頭裡。"],[120,"After assembling the pieces, check the finished project for any loose parts.","組合好之後,檢查完成的作品有沒有鬆動的地方。"]]},
{"n":326,"adv":true,"v":"qyEQD8jmC1M","s":[[27,"Measure the wood carefully before marking the exact point where you want to cut.","在標出要鋸的確切位置之前,先仔細測量木頭。"],[48,"Use a pencil to mark a straight cutting line across the surface of the wood.","用鉛筆在木頭表面畫一條筆直的切割線。"],[71,"Hold the wood firmly and guide the saw along the marked line with steady movements.","把木頭抓穩,用穩定的動作讓鋸子沿著標線前進。"],[93,"Once you finish cutting, check the edges carefully to make sure the pieces fit together properly.","鋸完後,仔細檢查邊緣,確保木塊能正確接合。"],[117,"Position the nails evenly before using the hammer to join the wooden pieces securely.","用鐵鎚把木塊牢牢釘在一起之前,先把釘子平均排好。"],[138,"As you assemble the project, make sure each piece is aligned correctly before hammering the nails completely into place.","組裝作品時,把釘子完全敲進去之前,確保每一塊都正確對齊。"],[163,"After completing the project, inspect the entire structure carefully and make any necessary adjustments before applying the final finish.","完成作品後,仔細檢查整個結構,並在上最後一層塗料前做必要的調整。"]]},
{"n":327,"adv":false,"v":"D1X8AEgejzo","s":[[18,"Choose a wallpaper design for your room.","為你的房間選一款壁紙圖案。"],[33,"Measure the walls before buying enough wallpaper.","買足量的壁紙之前先測量牆面。"],[50,"Move furniture away from the work area before starting.","開始之前,把家具搬離工作區域。"],[68,"Clean the entire surface carefully before you apply the wallpaper.","貼壁紙前,仔細清潔整個牆面。"],[86,"Make sure each section is aligned properly as you continue working.","繼續貼的時候,確保每一段都對齊。"],[106,"Smooth out the surface carefully to remove any wrinkles or air bubbles.","仔細把表面抹平,去除任何皺褶或氣泡。"],[127,"After finishing the walls, rearrange the furniture to create a more comfortable living space.","貼完牆面後,重新擺放家具,營造更舒適的居住空間。"]]},
{"n":328,"adv":false,"v":"Z4IKJwE-Okc","s":[[18,"Find an available pump near the entrance.","在入口附近找一台空的加油機。"],[34,"Park your vehicle beside the pump.","把車停在加油機旁邊。"],[50,"Turn off the engine before getting out.","下車前先熄火。"],[66,"Select the fuel type recommended for your vehicle.","選擇你的車建議使用的油品。"],[84,"Check the price per liter before starting the transaction.","開始交易前先查看每公升的價格。"],[103,"Follow the instructions on the screen and choose your preferred payment method.","依照螢幕上的指示,選擇你想用的付款方式。"],[123,"After refueling, replace the nozzle securely and keep your receipt for future reference.","加完油後,把油槍放回原位,並保留收據以供日後參考。"]]},
{"n":329,"adv":false,"v":"gOROjkcwuTU","s":[[18,"Pick up an audio guide at the gallery entrance.","在美術館入口領取語音導覽機。"],[34,"Select your preferred language before starting the tour.","開始導覽前選擇你想聽的語言。"],[51,"Enter the number displayed beside the first painting.","輸入第一幅畫旁邊標示的號碼。"],[54,"Listen carefully as the guide describes the artwork.","導覽介紹這件藝術品時請仔細聆聽。"],[86,"Move closer to the painting to examine its finer details.","走近畫作,仔細觀察更細微的地方。"],[105,"Notice how the artist uses color and texture to create a particular effect.","注意畫家如何運用色彩和質感營造特別的效果。"],[126,"Before moving on, pause the recording and review the information you found most interesting.","前往下一幅畫之前,暫停語音,回想你覺得最有趣的資訊。"]]},
{"n":330,"adv":false,"v":"bY4jJqH6oag","s":[[18,"Find a recharge kiosk near the ticket gates.","在閘門附近找一台加值機。"],[33,"Place your subway card on the reader.","把你的地鐵卡放在感應區上。"],[49,"Select the recharge option on the screen.","在螢幕上選擇加值的選項。"],[66,"Choose the amount you want to add to your card.","選擇你要加值的金額。"],[83,"Insert cash or select another available payment method on the screen.","投入現金,或在螢幕上選擇其他可用的付款方式。"],[103,"Check the balance and confirm the transaction before removing your card.","取出卡片前,查看餘額並確認交易。"],[124,"Take your card and receipt, then make sure the updated balance is correct before leaving.","拿好卡片和收據,離開前確認更新後的餘額是正確的。"]]},
{"n":331,"adv":false,"v":"3VN2oO2yzHw","s":[[18,"Renovation work will begin next Monday.","整修工程將從下週一開始。"],[33,"The main entrance will be temporarily closed.","正門將暫時關閉。"],[49,"Please use the side entrance during this period.","這段期間請使用側門。"],[66,"Some areas may be inaccessible while workers complete repairs.","工人進行維修時,部分區域可能無法進入。"],[86,"Expect occasional noise and delays throughout the renovation process.","整修期間可能偶爾會有噪音和延誤。"],[105,"The affected facilities should reopen once the work is complete.","工程完成後,受影響的設施應該就會重新開放。"],[125,"Please check the posted notices regularly for updates and any changes to the schedule.","請定期查看公告,了解最新消息和時程的任何變動。"]]},
{"n":332,"adv":true,"v":"ysK_etgyeqw","s":[[26,"Renovation work will begin next Monday, so please review the updated schedule before visiting the building.","整修工程將從下週一開始,所以來大樓之前請先查看更新後的時程。"],[49,"The main entrance will remain closed while contractors replace the doors and repair the surrounding structure.","承包商更換大門和修理周圍結構期間,正門將持續關閉。"],[73,"Visitors should use the side entrance and follow the temporary signs to reach their usual destinations.","訪客應使用側門,並依照臨時指標前往平常要去的地方。"],[96,"Several facilities may be temporarily unavailable as workers complete essential repairs throughout the building.","工人在整棟大樓進行必要維修時,有幾項設施可能暫時無法使用。"],[120,"Although the renovation may cause occasional noise, most offices will remain open during their regular business hours.","雖然整修可能偶爾會產生噪音,但大多數辦公室在正常上班時間仍會開放。"],[144,"Please allow extra time for your visit, especially if you need to access areas near the construction site.","來訪時請預留額外的時間,特別是如果你需要前往施工區附近的地方。"],[168,"Once the renovation is complete, check the posted notices for information about reopened facilities and any changes to the building layout.","整修完成後,請查看公告,了解重新開放的設施以及大樓配置的任何變動。"]]},
{"n":333,"adv":false,"v":"LOlrY6aaMt0","s":[[18,"Choose a canvas from the storage shelf.","從儲物架上選一塊畫布。"],[32,"Set up your easel near the window.","把畫架架在窗戶旁邊。"],[47,"Sketch the outline of the landscape in pencil.","用鉛筆勾勒出風景的輪廓。"],[64,"Select the paints you need for the background.","選擇畫背景需要的顏料。"],[82,"Mix different colors on your palette to match the scenery.","在調色盤上混合不同的顏色,調出和景色相符的色彩。"],[101,"Let the background dry completely before painting the trees and buildings.","等背景完全乾了,再畫樹木和建築物。"],[113,"Before leaving the studio, clean your workspace and return all the materials to their proper places.","離開畫室前,清理你的工作區,並把所有材料放回原位。"]]},
{"n":334,"adv":false,"v":"m8ewuE0HyGA","s":[[19,"Choose a lump of clay from the workbench.","從工作檯上拿一塊黏土。"],[34,"Place the clay on the pottery wheel.","把黏土放在拉坯機上。"],[51,"Wet your hands before shaping the clay.","塑形之前先把手弄濕。"],[68,"Press gently as the wheel begins to spin.","拉坯機開始轉動時輕輕按壓。"],[85,"Slowly pull the clay upward to form the sides of the bowl.","慢慢把黏土往上拉,做出碗的側邊。"],[103,"Smooth the surface with a damp sponge before removing the bowl from the wheel.","把碗從拉坯機上取下前,用濕海綿把表面抹平。"],[123,"Place the finished bowl on a drying shelf, then clean your tools before leaving the studio.","把完成的碗放在晾乾架上,然後在離開工作室前清洗工具。"]]},
{"n":335,"adv":false,"v":"19ldkGf7vbg","s":[[18,"The farmers market opens early every Saturday.","農夫市集每週六一早就開始營業。"],[27,"Local farmers sell their products here.","在地農夫在這裡販售他們的產品。"],[51,"You can find fresh produce at many stalls.","你可以在許多攤位找到新鮮農產品。"],[68,"Check the signs for prices and product information.","查看標示上的價格和產品資訊。"],[87,"Compare prices and select the freshest produce within your budget.","比較價格,在預算內挑選最新鮮的農產品。"],[107,"Keep your purchases organized in a shopping bag to protect delicate items.","把買的東西整齊地放在購物袋裡,保護容易壓壞的物品。"],[120,"Before leaving the market, stop by another stall to see whether any seasonal fruits are available.","離開市集前,再去另一個攤位看看有沒有當季水果。"]]},
{"n":336,"adv":false,"v":"UpkTc6FFoqg","s":[[19,"Meet your guide near the cave entrance.","在洞穴入口附近和導遊會合。"],[25,"Wear a helmet and sturdy shoes.","戴上安全帽,穿上堅固的鞋子。"],[50,"Follow the marked path into the cave.","沿著標示的路徑進入洞穴。"],[67,"Watch your step on the uneven ground.","在不平的地面上要小心腳步。"],[85,"Listen carefully as your guide explains how the cave was formed.","導遊解說洞穴如何形成時,請仔細聆聽。"],[105,"Stay with the group as you explore narrow passages and unusual rock formations.","探索狹窄的通道和奇特的岩石地形時,請跟著團體。"],[117,"Before leaving, enjoy the underground scenery and make sure you have all your belongings.","離開前,欣賞一下地底的景色,並確認你的物品都帶齊了。"]]},
{"n":337,"adv":false,"v":"gJkO0e0aOdc","s":[[19,"Pull into the rest area safely.","安全地駛進休息區。"],[34,"Park your car in an available space.","把車停在空的車位上。"],[50,"Follow the signs to find restrooms.","依照指標找到洗手間。"],[67,"Visit the food court for a quick meal.","到美食街簡單吃個飯。"],[83,"Check the information board for traffic updates and road conditions.","查看資訊看板上的最新交通資訊和路況。"],[102,"Stretch your legs and refill your water bottle before continuing your journey.","繼續上路前,伸展一下雙腿並把水壺裝滿。"],[114,"Before returning to the highway, check your fuel level and make sure everyone is ready to travel.","回到高速公路前,檢查油量,並確認每個人都準備好出發了。"]]},
{"n":338,"adv":true,"v":"gjZQLKTBtEw","s":[[27,"Enter the rest area slowly and follow the directional signs carefully.","慢慢駛入休息區,並仔細遵照方向指標。"],[48,"Choose a designated parking space away from the main traffic lanes nearby.","選一個遠離附近主要車道的指定停車位。"],[71,"Check the facility map to locate the public restrooms, dining area, and convenience store.","查看設施地圖,找出公共廁所、用餐區和便利商店的位置。"],[94,"Please review the latest traffic updates online before deciding when to resume your journey.","決定何時繼續上路前,請先上網查看最新的交通資訊。"],[116,"Take a short break, stretch your muscles, and grab a snack before getting back on the road.","回到路上前,稍微休息、伸展肌肉並吃點點心。"],[138,"If you need assistance, visit the information desk to ask about road conditions or nearby service facilities.","如果需要協助,請到服務台詢問路況或附近的服務設施。"],[151,"Before merging back onto the highway, adjust your mirrors, fasten your seat belt, and make sure the road is clear.","匯入高速公路之前,調整後照鏡、繫好安全帶,並確認路上沒有來車。"]]},
{"n":339,"adv":false,"v":"9-Fen4pkK14","s":[[18,"Visit the information desk near the entrance.","到入口附近的服務台看看。"],[33,"Pick up a city map and brochure.","拿一份城市地圖和簡介手冊。"],[47,"Check the opening hours of popular attractions.","查看熱門景點的開放時間。"],[65,"Ask the staff about public transportation options.","向工作人員詢問大眾運輸的選擇。"],[82,"Find out which local events are happening during your stay.","了解你停留期間有哪些當地活動。"],[100,"Use the map to plan your route and locate nearby points of interest.","用地圖規劃路線,找出附近值得一去的地方。"],[118,"Before leaving, collect any brochures you need and confirm the directions to your next destination.","離開前,拿好你需要的簡介,並確認前往下一個目的地的路線。"]]},
{"n":340,"adv":false,"v":"ODsrJlRu8Cc","s":[[18,"Enter the bakery and check the display shelves.","走進麵包店,看看展示架上的麵包。"],[32,"Choose a pastry or loaf of bread.","選一個糕點或一條麵包。"],[47,"Check the labels for prices and ingredients.","查看標籤上的價格和成分。"],[63,"Place your selections on the counter for the cashier.","把你選好的東西放在櫃台上給收銀員。"],[81,"Ask the staff which breads have just come out of the oven.","問店員哪些麵包是剛出爐的。"],[98,"Pay for your order and request a bag to carry your purchases.","付款並要一個袋子裝你買的東西。"],[118,"Once you have collected your order, check your receipt and make sure all items are included.","拿到你買的東西後,檢查收據,確認所有品項都有。"]]},
{"n":341,"adv":false,"v":"3TCuOM7Fk8I","s":[[18,"Turn on the scanner and computer.","打開掃描器和電腦。"],[33,"Place the document face down.","把文件正面朝下放好。"],[48,"Open the scanning software on your computer.","在電腦上開啟掃描軟體。"],[66,"Select the file format and resolution you need.","選擇你需要的檔案格式和解析度。"],[84,"Preview the scanned document to make sure the text is clear and readable.","預覽掃描好的文件,確認文字清楚易讀。"],[104,"Save the digital copy in a folder where you can easily find it later.","把電子檔存在之後容易找到的資料夾裡。"],[116,"Before finishing, check the saved file and scan the document again if any details are missing.","結束前,檢查存好的檔案,如果有任何細節漏掉就再掃描一次。"]]},
{"n":342,"adv":false,"v":"XKUZMIywdLI","s":[[18,"Find the ticket collection kiosk near the entrance.","找到入口附近的取票機。"],[32,"Select the ticket pickup option on the screen.","在螢幕上選擇取票的選項。"],[48,"Enter your booking reference number carefully.","仔細輸入你的訂票代碼。"],[65,"Check your event details before confirming the request.","確認之前先檢查活動的詳細資訊。"],[82,"Follow the instructions to print your tickets and wait for them.","依照指示列印票券並稍候。"],[100,"Collect your tickets and make sure the event date and seat numbers are correct before leaving the kiosk.","離開取票機前,拿好票並確認活動日期和座位號碼都正確。"],[123,"Keep your tickets in a safe place and have them ready for entry.","把票放在安全的地方,入場時準備好出示。"]]},
{"n":343,"adv":false,"v":"JTl8uLILELM","s":[[17,"Service will be temporarily interrupted tomorrow.","明天服務將暫時中斷。"],[32,"The interruption will begin at 9 in the morning.","中斷將從早上 9 點開始。"],[48,"During this time, some facilities may be unavailable.","在這段期間,部分設施可能無法使用。"],[66,"Please check the posted notices for further information.","請查看公告以取得更多資訊。"],[84,"We apologize for any inconvenience this temporary disruption may cause.","對於這次暫時中斷可能造成的不便,我們深感抱歉。"],[103,"Normal service is expected to resume once the maintenance work is complete.","維修工作完成後,預計將恢復正常服務。"],[124,"For urgent assistance, please contact the service desk or visit our website for the latest updates.","如需緊急協助,請聯絡服務台或上我們的網站查看最新消息。"]]},
{"n":344,"adv":true,"v":"m-zDy5aDApc","s":[[27,"Temporary service disruptions are scheduled for tomorrow morning across the building.","明天早上整棟大樓預定會暫時中斷服務。"],[49,"The interruption will begin promptly at 9 and affect several facilities.","中斷將在 9 點準時開始,並影響多項設施。"],[71,"During the scheduled maintenance period, certain services may remain unavailable to the public.","在預定的維修期間,某些服務可能無法對外開放。"],[94,"Please consult the official notice for further details about the expected duration and affected areas.","請查看正式公告,了解預計的時間長度和受影響區域的詳細資訊。"],[117,"We apologize for any inconvenience and appreciate your patience while our technicians complete the necessary repairs.","造成不便,我們深感抱歉,也感謝你在技術人員完成必要維修期間的耐心等候。"],[141,"Service is expected to resume gradually once all systems have been thoroughly inspected and tested to ensure they are operating properly.","所有系統經過徹底檢查和測試、確認運作正常後,預計服務將逐步恢復。"],[166,"If the disruption affects your plans, contact our support team or check the website for alternative arrangements and further updates.","如果這次中斷影響到你的計畫,請聯絡我們的客服團隊,或上網查看替代安排和最新消息。"]]},
{"n":345,"adv":false,"v":"2JDWewky0no","s":[[18,"Breakfast is served on the ground floor.","早餐在一樓供應。"],[33,"Please check the opening hours at the entrance.","請在入口查看供餐時間。"],[49,"Choose a table before getting your food.","取餐前先選好座位。"],[66,"Pick up a clean plate and visit the buffet.","拿一個乾淨的盤子到自助餐台。"],[75,"Help yourself to a selection of hot dishes, fresh fruit, and breakfast cereals.","請自行取用各式熱食、新鮮水果和早餐穀片。"],[105,"Use the serving utensils provided and avoid taking more food than you can finish.","使用提供的公用夾具,不要拿超過你吃得完的份量。"],[117,"Before leaving the dining area, return your tray and take all your belongings with you.","離開用餐區前,歸還餐盤並帶走你所有的物品。"]]},
{"n":346,"adv":false,"v":"xrsN3rTzsHo","s":[[17,"Please keep your voice low in public areas.","在公共區域請降低音量。"],[33,"Keep walkways clear for other visitors.","為其他遊客保持走道暢通。"],[49,"Dispose of trash in the proper bins.","把垃圾丟進正確的垃圾桶。"],[66,"Avoid blocking entrances while waiting for others.","等人時避免擋住入口。"],[86,"Respect shared spaces and leave them clean for the next person.","尊重共用空間,為下一個人保持整潔。"],[106,"When using public facilities, follow posted rules and consider the comfort of others.","使用公共設施時,遵守公告的規定並顧及他人的舒適。"],[128,"Thank you for maintaining a pleasant environment by respecting others and keeping common areas tidy.","感謝你尊重他人、保持公共區域整潔,一起維護舒適的環境。"]]},
{"n":347,"adv":false,"v":"pBpOoW7XYec","s":[[17,"Priority access is available at this entrance.","這個入口提供優先通行。"],[32,"Please look for the designated signs.","請留意指定的標示。"],[48,"Allow eligible passengers to board first.","讓符合資格的乘客先上車。"],[65,"Keep the priority lane clear for those who need it.","為有需要的人保持優先通道暢通。"],[83,"Older adults and expectant mothers may also use this service.","年長者和孕婦也可以使用這項服務。"],[102,"If you need assistance, please speak to a staff member before joining the line.","如果需要協助,請在排隊前先告知工作人員。"],[123,"Thank you for respecting these guidelines and helping everyone access the facilities safely and comfortably.","感謝你遵守這些規定,幫助每個人安全舒適地使用設施。"]]},
{"n":348,"adv":false,"v":"DoaVmysTrfc","s":[[17,"Temporary passes are available at the front desk.","臨時通行證可在櫃台領取。"],[33,"Please present a valid form of identification.","請出示有效的身分證件。"],[49,"Complete the registration form with your personal details.","在登記表上填寫你的個人資料。"],[67,"Check that your pass displays the correct expiration date.","確認你的通行證上顯示正確的到期日。"],[86,"Keep your pass visible while using the facilities at all times.","使用設施時,隨時讓你的通行證保持可見。"],[104,"If your pass is lost or damaged, contact the reception desk for assistance.","如果通行證遺失或損壞,請聯絡接待櫃台協助。"],[116,"Before leaving the building, return your temporary pass to the designated collection point.","離開大樓前,把臨時通行證交回指定的回收處。"]]}];
